const MINNA_N5 = {"total":1020,"lessons":[{"n":0,"title":"Bài nhập môn","jp":"はじめに","sub":"Câu lớp học, chào hỏi, chữ số","rows":[["はじめましょう","始めましょう","ex","Chúng ta bắt đầu nào","Let's begin.","では、はじめましょう。／Vậy thì, chúng ta bắt đầu nào.","Câu giáo viên hay nói khi vào giờ học."],["おわりましょう","終わりましょう","ex","Chúng ta kết thúc nào","Let's finish (the lesson).","きょうは これで おわりましょう。／Hôm nay chúng ta kết thúc ở đây nhé.",""],["やすみましょう","休みましょう","ex","Chúng ta nghỉ giải lao nào","Let's take a break.","10ぷん やすみましょう。／Chúng ta nghỉ 10 phút nhé.",""],["わかりますか","分かりますか","ex","Các bạn có hiểu không?","Do you understand?","せんせい：わかりますか。／Thầy: Các em hiểu không?",""],["はい、わかります","","ex","Vâng, tôi hiểu","Yes, I do.","はい、わかります。／Vâng, em hiểu ạ.",""],["いいえ、わかりません","","ex","Không, tôi không hiểu","No, I don't.","すみません、いいえ、わかりません。／Xin lỗi, em không hiểu ạ.",""],["もういちど","もう一度","ex","Một lần nữa","Once more.","もういちど おねがいします。／Xin hãy nói lại một lần nữa.","Thêm おねがいします cho lịch sự."],["けっこうです","結構です","ex","Được rồi, tốt rồi","Fine. / Good.","はい、けっこうです。／Vâng, tốt rồi.","Giáo viên dùng khi câu trả lời đúng. Ở Bài 8 còn có nghĩa “không, cảm ơn”."],["だめです","駄目です","ex","Không được, sai rồi","That's not OK. / That's wrong.","それは だめです。／Cái đó không được.",""],["なまえ","名前","n","Tên","name","なまえを かいて ください。／Hãy viết tên vào.","Hỏi tên người khác lịch sự: おなまえは？"],["しけん","試験","n","Kỳ thi, bài kiểm tra","exam","あした しけんが あります。／Ngày mai có bài kiểm tra.",""],["しゅくだい","宿題","n","Bài tập về nhà","homework","しゅくだいを します。／Làm bài tập về nhà.","Đi với します."],["しつもん","質問","n","Câu hỏi","question","しつもんが あります。／Em có câu hỏi.",""],["こたえ","答え","n","Câu trả lời, đáp án","answer","こたえを いって ください。／Hãy nói câu trả lời.",""],["れい","例","n","Ví dụ","example","れいを みて ください。／Hãy xem ví dụ.",""],["おはようございます","お早うございます","ex","Chào buổi sáng","Good morning.","せんせい、おはようございます。／Chào buổi sáng thầy ạ.","Với bạn thân có thể nói gọn おはよう."],["こんにちは","今日は","ex","Xin chào (ban ngày)","Good afternoon. / Hello.","こんにちは、たなかさん。／Chào anh Tanaka.","Viết は nhưng đọc là “wa”."],["こんばんは","今晩は","ex","Chào buổi tối","Good evening.","こんばんは。いい てんきですね。／Chào buổi tối. Trời đẹp nhỉ.","Viết は nhưng đọc là “wa”."],["おやすみなさい","お休みなさい","ex","Chúc ngủ ngon","Good night.","おやすみなさい。また あした。／Chúc ngủ ngon. Hẹn mai gặp.",""],["さようなら","","ex","Tạm biệt","Good-bye.","せんせい、さようなら。／Chào thầy, em về ạ.","Dùng khi chia tay lâu; với bạn bè thường nói じゃ、また."],["ありがとうございます","","ex","Cảm ơn rất nhiều","Thank you very much.","てつだって くれて、ありがとうございます。／Cảm ơn vì đã giúp tôi.","Thân mật: ありがとう."],["すみません","","ex","Xin lỗi; xin phép (gọi ai đó)","Excuse me. / I'm sorry.","すみません、トイレは どこですか。／Xin lỗi, nhà vệ sinh ở đâu ạ?","Vừa để xin lỗi, vừa để gọi người khác, vừa để cảm ơn nhẹ."],["おねがいします","お願いします","ex","Làm ơn, nhờ anh/chị","Please.","コーヒーを おねがいします。／Cho tôi cà phê.","Dùng khi nhờ vả hoặc gọi món."],["ゼロ、れい","零","num","Số không","zero (0)","でんわばんごうは ゼロ・さん……／Số điện thoại là 0-3…","Đọc số điện thoại thường dùng ゼロ."],["いち","一","num","Một","one (1)","いちばん すきです。／Thích nhất.",""],["に","二","num","Hai","two (2)","にじに あいましょう。／Gặp nhau lúc 2 giờ nhé.",""],["さん","三","num","Ba","three (3)","りんごが さんこ あります。／Có ba quả táo.",""],["よん、し","四","num","Bốn","four (4)","よじに おきます。／Thức dậy lúc 4 giờ.","し đồng âm với “chết” nên hay dùng よん; giờ đọc là よじ."],["ご","五","num","Năm","five (5)","ごじに かえります。／Về lúc 5 giờ.",""],["ろく","六","num","Sáu","six (6)","ろくじに ばんごはんを たべます。／Ăn tối lúc 6 giờ.",""],["なな、しち","七","num","Bảy","seven (7)","しちじに おきます。／Thức dậy lúc 7 giờ.","Giờ đọc là しちじ; đếm thường dùng なな."],["はち","八","num","Tám","eight (8)","はちじから はたらきます。／Làm việc từ 8 giờ.",""],["きゅう、く","九","num","Chín","nine (9)","くじに ねます。／Ngủ lúc 9 giờ.","Giờ đọc là くじ; đếm thường dùng きゅう."],["じゅう","十","num","Mười","ten (10)","じゅうにん います。／Có mười người.",""]]},{"n":1,"title":"Bài 1","jp":"はじめまして","sub":"Giới thiệu bản thân · N1 は N2 です","rows":[["わたし","私","pr","Tôi","I","わたしは マイク・ミラーです。／Tôi là Mike Miller.","Cách xưng hô trung tính, dùng được trong mọi tình huống."],["わたしたち","私達","pr","Chúng tôi, chúng ta","we","わたしたちは がくせいです。／Chúng tôi là sinh viên.",""],["あなた","貴方","pr","Bạn, anh, chị","you","あなたは がくせいですか。／Bạn là sinh viên à?","Người Nhật ít gọi thẳng あなた; nên gọi tên + さん."],["あのひと","あの人","pr","Người kia, người đó","that person, he, she","あのひとは だれですか。／Người kia là ai vậy?",""],["あのかた","あの方","pr","Vị kia (lịch sự)","that person (polite)","あのかたは どなたですか。／Vị kia là ai ạ?","Lịch sự hơn あのひと."],["みなさん","皆さん","pr","Mọi người, các bạn","ladies and gentlemen, all of you","みなさん、おはようございます。／Chào buổi sáng mọi người.",""],["～さん","","sf","Anh, chị, ông, bà (gắn sau tên)","Mr., Ms. (title of respect)","たなかさんは かいしゃいんです。／Anh Tanaka là nhân viên công ty.","Không dùng cho chính mình."],["～ちゃん","","sf","Bé ~ (gắn sau tên trẻ em)","suffix added to a child's name","はなちゃんは なんさいですか。／Bé Hana mấy tuổi?","Dùng với trẻ con, bạn rất thân."],["～くん","～君","sf","Cậu ~ (gắn sau tên bé trai)","suffix added to a boy's name","たろうくん、こっちへ きて。／Taro ơi, lại đây.",""],["～じん","～人","sf","Người nước ~","a national of ~","わたしは ベトナムじんです。／Tôi là người Việt Nam.","Vd: アメリカじん (người Mỹ), にほんじん (người Nhật)."],["せんせい","先生","n","Thầy giáo, cô giáo","teacher, instructor","ワットさんは せんせいです。／Thầy Watt là giáo viên.","Không dùng để nói nghề của chính mình (khi đó dùng きょうし)."],["きょうし","教師","n","Giáo viên (nghề nghiệp)","teacher, instructor","わたしは きょうしです。／Tôi là giáo viên.","Dùng khi nói về nghề của mình."],["がくせい","学生","n","Học sinh, sinh viên","student","わたしは だいがくの がくせいです。／Tôi là sinh viên đại học.",""],["かいしゃいん","会社員","n","Nhân viên công ty","company employee","ちちは かいしゃいんです。／Bố tôi là nhân viên công ty.",""],["しゃいん","社員","n","Nhân viên công ty ~","employee of ~ Company","ミラーさんは IMCの しゃいんです。／Anh Miller là nhân viên công ty IMC.","Đi kèm tên công ty."],["ぎんこういん","銀行員","n","Nhân viên ngân hàng","bank employee","あのひとは ぎんこういんです。／Người kia là nhân viên ngân hàng.",""],["いしゃ","医者","n","Bác sĩ","medical doctor","あには いしゃです。／Anh trai tôi là bác sĩ.","Gọi bác sĩ trực tiếp: せんせい."],["けんきゅうしゃ","研究者","n","Nhà nghiên cứu","researcher, scholar","ワンさんは けんきゅうしゃです。／Anh Wang là nhà nghiên cứu.",""],["エンジニア","","n","Kỹ sư","engineer","わたしは エンジニアです。／Tôi là kỹ sư.",""],["だいがく","大学","n","Trường đại học","university","ふじだいがくの がくせいです。／Là sinh viên đại học Fuji.",""],["びょういん","病院","n","Bệnh viện","hospital","びょういんへ いきます。／Đi đến bệnh viện.","Đừng nhầm với びよういん (tiệm làm tóc)."],["でんき","電気","n","Điện, đèn điện","electricity, light","でんきを つけて ください。／Hãy bật đèn lên.",""],["だれ","誰","q","Ai","who","あのひとは だれですか。／Người kia là ai?",""],["どなた","","q","Vị nào (lịch sự)","who (polite)","あのかたは どなたですか。／Vị kia là ai ạ?","Lịch sự hơn だれ."],["～さい","～歳","ctr","~ tuổi","~ years old","わたしは にじゅうさいです。／Tôi 20 tuổi.","20 tuổi đọc là はたち."],["なんさい","何歳","q","Mấy tuổi","how old","おこさんは なんさいですか。／Con anh mấy tuổi?",""],["おいくつ","","q","Bao nhiêu tuổi (lịch sự)","how old (polite)","おいくつですか。／Anh/chị bao nhiêu tuổi ạ?","Lịch sự hơn なんさい."],["はい","","it","Vâng, có","yes","はい、そうです。／Vâng, đúng vậy.",""],["いいえ","","it","Không","no","いいえ、がくせいじゃ ありません。／Không, tôi không phải sinh viên.",""],["しつれいですが","失礼ですが","ex","Xin lỗi, nhưng…","Excuse me, but…","しつれいですが、おなまえは？／Xin lỗi, tên anh là gì ạ?","Dùng trước khi hỏi thông tin cá nhân."],["おなまえは？","お名前は？","ex","Tên anh/chị là gì?","May I have your name?","おなまえは？ーミラーです。／Tên anh là gì? — Tôi là Miller.",""],["はじめまして","初めまして","ex","Rất hân hạnh được gặp (lần đầu)","How do you do?","はじめまして。ミラーです。／Rất vui được gặp, tôi là Miller.","Câu đầu tiên khi tự giới thiệu."],["どうぞよろしくおねがいします","どうぞよろしくお願いします","ex","Rất mong được giúp đỡ","Pleased to meet you.","ベトナムから きました。どうぞよろしく おねがいします。／Tôi đến từ Việt Nam. Rất mong được giúp đỡ.","Câu kết thúc phần tự giới thiệu."],["こちらは～さんです","","ex","Đây là anh/chị ~","This is Mr./Ms. ~.","こちらは やまださんです。／Đây là anh Yamada.","Dùng khi giới thiệu người khác."],["～からきました","～から来ました","ex","Tôi đến từ ~","I came (come) from ~.","わたしは ハノイから きました。／Tôi đến từ Hà Nội.",""]],"ref":[["アメリカ","","n","Mỹ","USA","ミラーさんは アメリカじんです。／Anh Miller là người Mỹ.","Người: アメリカ人 · Tiếng: 英語"],["イギリス","","n","Anh (nước Anh)","UK","イギリスの ことばは えいごです。／Ngôn ngữ của nước Anh là tiếng Anh.","Người: イギリス人 · Tiếng: 英語"],["イタリア","","n","Ý","Italy","イタリアの りょうりが すきです。／Tôi thích món ăn Ý.","Người: イタリア人 · Tiếng: イタリア語"],["イラン","","n","Iran","Iran","イランの ことばは ペルシアごです。／Ngôn ngữ của Iran là tiếng Ba Tư.","Người: イラン人 · Tiếng: ペルシア語"],["インド","","n","Ấn Độ","India","カリナさんは インドネシアじんです。インドじんじゃ ありません。／Chị Karina là người Indonesia, không phải người Ấn Độ.","Người: インド人 · Tiếng: ヒンディー語"],["インドネシア","","n","In-đô-nê-xi-a","Indonesia","カリナさんは インドネシアから きました。／Chị Karina đến từ Indonesia.","Người: インドネシア人 · Tiếng: インドネシア語"],["エジプト","","n","Ai Cập","Egypt","エジプトの ことばは アラビアごです。／Ngôn ngữ của Ai Cập là tiếng Ả-rập.","Người: エジプト人 · Tiếng: アラビア語"],["オーストラリア","","n","Úc","Australia","オーストラリアは いま なつです。／Nước Úc bây giờ đang là mùa hè.","Người: オーストラリア人 · Tiếng: 英語"],["カナダ","","n","Canada","Canada","カナダでは えいごと フランスごを はなします。／Ở Canada người ta nói tiếng Anh và tiếng Pháp.","Người: カナダ人 · Tiếng: 英語, フランス語"],["かんこく","韓国","n","Hàn Quốc","South Korea","イーさんは かんこくじんです。／Chị Lee là người Hàn Quốc.","Người: 韓国人 · Tiếng: 韓国語"],["サウジアラビア","","n","Ả-rập Xê-út","Saudi Arabia","サウジアラビアは あついです。／Ả-rập Xê-út thì nóng.","Người: サウジアラビア人 · Tiếng: アラビア語"],["シンガポール","","n","Singapore","Singapore","シンガポールの ことばは えいごです。／Ngôn ngữ của Singapore là tiếng Anh.","Người: シンガポール人 · Tiếng: 英語"],["スペイン","","n","Tây Ban Nha","Spain","スペインの ことばは スペインごです。／Ngôn ngữ của Tây Ban Nha là tiếng Tây Ban Nha.","Người: スペイン人 · Tiếng: スペイン語"],["タイ","","n","Thái Lan","Thailand","タワポンさんは タイじんです。／Anh Thawaphon là người Thái.","Người: タイ人 · Tiếng: タイ語"],["ちゅうごく","中国","n","Trung Quốc","China","ワンさんは ちゅうごくじんです。／Anh Vương là người Trung Quốc.","Người: 中国人 · Tiếng: 中国語"],["ドイツ","","n","Đức","Germany","シュミットさんは ドイツじんです。／Anh Schmidt là người Đức.","Người: ドイツ人 · Tiếng: ドイツ語"],["にほん","日本","n","Nhật Bản","Japan","にほんの ことばは にほんごです。／Ngôn ngữ của Nhật Bản là tiếng Nhật.","Người: 日本人 · Tiếng: 日本語"],["フランス","","n","Pháp","France","フランスの ワインは おいしいです。／Rượu vang Pháp ngon.","Người: フランス人 · Tiếng: フランス語"],["フィリピン","","n","Philippines","Philippines","フィリピンの ことばは フィリピノごです。／Ngôn ngữ của Philippines là tiếng Philippines.","Người: フィリピン人 · Tiếng: フィリピノ語"],["ブラジル","","n","Braxin","Brazil","サントスさんは ブラジルじんです。／Anh Santos là người Braxin.","Người: ブラジル人 · Tiếng: ポルトガル語"],["ベトナム","","n","Việt Nam","Vietnam","わたしは ベトナムじんです。／Tôi là người Việt Nam.","Người: ベトナム人 · Tiếng: ベトナム語"],["マレーシア","","n","Malaysia","Malaysia","マレーシアの ことばは マレーシアごです。／Ngôn ngữ của Malaysia là tiếng Mã Lai.","Người: マレーシア人 · Tiếng: マレーシア語"],["メキシコ","","n","Mexico","Mexico","メキシコの ことばは スペインごです。／Ngôn ngữ của Mexico là tiếng Tây Ban Nha.","Người: メキシコ人 · Tiếng: スペイン語"],["ロシア","","n","Nga","Russia","ロシアは さむいです。／Nước Nga lạnh.","Người: ロシア人 · Tiếng: ロシア語"],["アラビアご","アラビア語","n","Tiếng Ả-rập","Arabic","エジプトでは アラビアごを はなします。／Ở Ai Cập người ta nói tiếng Ả-rập.",""],["スペインご","スペイン語","n","Tiếng Tây Ban Nha","Spanish","メキシコの ことばは スペインごです。／Ngôn ngữ ở Mexico là tiếng Tây Ban Nha.",""],["ポルトガルご","ポルトガル語","n","Tiếng Bồ Đào Nha","Portuguese","ブラジルの ことばは ポルトガルごです。／Ngôn ngữ của Braxin là tiếng Bồ Đào Nha.",""],["ペルシアご","ペルシア語","n","Tiếng Ba Tư","Persian","イランの ことばは ペルシアごです。／Ngôn ngữ của Iran là tiếng Ba Tư.",""],["ヒンディーご","ヒンディー語","n","Tiếng Hin-đi","Hindi","インドの ことばは ヒンディーごです。／Ngôn ngữ của Ấn Độ là tiếng Hin-đi.",""]],"refTitle":"Nước, người & ngôn ngữ","grammar":[{"title":"N1 は N2 です – câu khẳng định danh từ","form":"N1 は N2 です","explain":"は (đọc là “wa”) đánh dấu chủ đề – điều mình muốn nói tới. です đứng cuối để kết thúc câu vị ngữ danh từ một cách lịch sự, mang nghĩa “là”.\n\nです không đổi theo chủ ngữ (tôi/anh/họ đều dùng です) và có dạng phủ định, quá khứ riêng (Bài 2, Bài 12).","examples":[{"s":"わたしは マイク・ミラーです。","t":"Tôi là Mike Miller."},{"s":"わたしは かいしゃいんです。","t":"Tôi là nhân viên công ty."}],"tip":"Trợ từ は viết bằng chữ は nhưng đọc là “wa”."},{"title":"N1 は N2 じゃ（では）ありません – phủ định","form":"N1 は N2 じゃ ありません／では ありません","explain":"Phủ định của です: “không phải là”. じゃ ありません dùng trong hội thoại hằng ngày; では ありません trang trọng hơn, dùng khi phát biểu hoặc viết.","examples":[{"s":"サントスさんは がくせいじゃ ありません。","t":"Anh Santos không phải là sinh viên."},{"s":"わたしは せんせいでは ありません。","t":"Tôi không phải là giáo viên."}],"tip":"では cũng đọc là “dewa”."},{"title":"N1 は N2 ですか – câu nghi vấn","form":"Câu + か · はい、～です／いいえ、～じゃ ありません","explain":"か đặt cuối câu biến câu thành câu hỏi, cuối câu đọc lên giọng. Trật tự từ không đổi.\n\nCâu hỏi đúng/sai trả lời bằng はい hoặc いいえ. Câu hỏi có từ để hỏi (だれ, なん…) thì đặt từ để hỏi vào đúng chỗ thông tin cần hỏi, vẫn giữ か ở cuối.","examples":[{"s":"ミラーさんは アメリカじんですか。……はい、アメリカじんです。","t":"Anh Miller là người Mỹ à? – Vâng, anh ấy là người Mỹ."},{"s":"ミラーさんは せんせいですか。……いいえ、せんせいじゃ ありません。","t":"Anh Miller là giáo viên à? – Không, không phải giáo viên."},{"s":"あの かたは どなたですか。……ミラーさんです。","t":"Vị kia là ai? – Là anh Miller."}],"tip":""},{"title":"N も – cũng","form":"N も N2 です","explain":"も thay cho は khi điều được nói giống với câu trước: “… cũng …”.","examples":[{"s":"ミラーさんは かいしゃいんです。グプタさんも かいしゃいんです。","t":"Anh Miller là nhân viên công ty. Anh Gupta cũng là nhân viên công ty."},{"s":"わたしも がくせいです。","t":"Tôi cũng là sinh viên."}],"tip":"Không dùng cả は và も: Sai: わたしはも. Đúng: わたしも."},{"title":"N1 の N2 – sở thuộc","form":"N1 の N2","explain":"の nối hai danh từ, N1 bổ nghĩa cho N2. Ở bài này N1 là nơi N2 trực thuộc: “nhân viên của công ty IMC”, “giáo viên của trường Sakura”. Trật tự ngược tiếng Việt: cái bổ nghĩa đứng trước.","examples":[{"s":"ミラーさんは IMCの しゃいんです。","t":"Anh Miller là nhân viên công ty IMC."},{"s":"わたしは さくらだいがくの がくせいです。","t":"Tôi là sinh viên Đại học Sakura."}],"tip":""},{"title":"～さん – cách gọi lịch sự","form":"Họ/tên + さん · trẻ em: ～ちゃん","explain":"さん đặt sau họ hoặc tên người khác để tỏ lịch sự (anh/chị/ông/bà). KHÔNG dùng さん cho chính mình. Với trẻ con thân mật dùng ちゃん.\n\nKhi đã biết tên người nghe, người Nhật gọi tên + さん thay vì あなた; あなた chỉ dùng với người rất thân (vợ chồng), dùng sai dễ gây cảm giác thiếu lịch sự.","examples":[{"s":"あの かたは ミラーさんです。","t":"Vị kia là anh Miller."},{"s":"すずき：ミラーさんは がくせいですか。","t":"Suzuki: Anh Miller là sinh viên à?"}],"tip":"Sai: わたしは ミラーさんです. Đúng: わたしは ミラーです."}]},{"n":2,"title":"Bài 2","jp":"ほんの気持ちです","sub":"これ・それ・あれ · đồ vật","rows":[["これ","","pr","Cái này (gần người nói)","this (thing near the speaker)","これは ほんです。／Đây là quyển sách.","Đứng một mình, không đi kèm danh từ."],["それ","","pr","Cái đó (gần người nghe)","that (thing near the listener)","それは なんですか。／Cái đó là gì vậy?",""],["あれ","","pr","Cái kia (xa cả hai người)","that (thing far from both)","あれは ぎんこうです。／Kia là ngân hàng.",""],["この～","","pr","~ này","this ~","この ほんは わたしのです。／Quyển sách này là của tôi.","Luôn đi kèm danh từ: この＋N."],["その～","","pr","~ đó","that ~ (near you)","その かさは だれのですか。／Cái ô đó của ai vậy?",""],["あの～","","pr","~ kia","that ~ (over there)","あの ひとは せんせいです。／Người kia là giáo viên.",""],["ほん","本","n","Sách","book","これは にほんごの ほんです。／Đây là sách tiếng Nhật.",""],["じしょ","辞書","n","Từ điển","dictionary","じしょを かして ください。／Cho tôi mượn từ điển.",""],["ざっし","雑誌","n","Tạp chí","magazine","これは くるまの ざっしです。／Đây là tạp chí về xe hơi.",""],["しんぶん","新聞","n","Báo","newspaper","まいあさ しんぶんを よみます。／Sáng nào cũng đọc báo.",""],["ノート","","n","Vở","notebook","ノートに かいて ください。／Hãy viết vào vở.",""],["てちょう","手帳","n","Sổ tay","pocket notebook","てちょうに よていを かきます。／Ghi lịch vào sổ tay.",""],["めいし","名刺","n","Danh thiếp","business card","これは わたしの めいしです。／Đây là danh thiếp của tôi.","Đưa và nhận danh thiếp bằng hai tay."],["カード","","n","Thẻ","card","カードで はらいます。／Trả bằng thẻ.",""],["テレホンカード","","n","Thẻ điện thoại","telephone card","テレホンカードを かいます。／Mua thẻ điện thoại.",""],["えんぴつ","鉛筆","n","Bút chì","pencil","えんぴつで かきます。／Viết bằng bút chì.",""],["ボールペン","","n","Bút bi","ballpoint pen","ボールペンを ください。／Cho tôi cây bút bi.",""],["シャープペンシル","","n","Bút chì kim","mechanical pencil","これは シャープペンシルです。／Đây là bút chì kim.","Hay gọi tắt là シャーペン."],["かぎ","鍵","n","Chìa khoá","key","これは へやの かぎです。／Đây là chìa khoá phòng.",""],["とけい","時計","n","Đồng hồ","watch, clock","この とけいは たかいです。／Đồng hồ này đắt.",""],["かさ","傘","n","Cái ô","umbrella","かさを わすれました。／Tôi quên ô rồi.",""],["かばん","鞄","n","Cặp, túi xách","bag, briefcase","それは わたしの かばんです。／Đó là túi của tôi.",""],["カセットテープ","","n","Băng cát-xét","cassette tape","これは にほんごの カセットテープです。／Đây là băng cát-xét tiếng Nhật.",""],["テープレコーダー","","n","Máy ghi âm","tape recorder","テープレコーダーで ききます。／Nghe bằng máy ghi âm.",""],["テレビ","","n","Ti vi","television","ばんごはんの あとで テレビを みます。／Xem ti vi sau bữa tối.",""],["ラジオ","","n","Đài, radio","radio","ラジオで ニュースを ききます。／Nghe tin tức trên radio.",""],["カメラ","","n","Máy ảnh","camera","あたらしい カメラを かいました。／Đã mua máy ảnh mới.",""],["コンピューター","","n","Máy vi tính","computer","コンピューターで しごとを します。／Làm việc bằng máy tính.",""],["じどうしゃ","自動車","n","Ô tô","automobile, car","これは にほんの じどうしゃです。／Đây là ô tô Nhật.","Nói chuyện hằng ngày hay dùng くるま."],["つくえ","机","n","Cái bàn (học, làm việc)","desk","つくえの うえに ほんが あります。／Trên bàn có quyển sách.",""],["いす","椅子","n","Cái ghế","chair","いすに すわって ください。／Mời ngồi ghế.",""],["チョコレート","","n","Sô-cô-la","chocolate","チョコレートが すきです。／Tôi thích sô-cô-la.",""],["コーヒー","","n","Cà phê","coffee","コーヒーを のみます。／Uống cà phê.",""],["えいご","英語","n","Tiếng Anh","the English language","えいごの ほんです。／Là sách tiếng Anh.",""],["にほんご","日本語","n","Tiếng Nhật","the Japanese language","にほんごを べんきょうします。／Học tiếng Nhật.",""],["～ご","～語","sf","Tiếng ~","~ language","ベトナムごで なんですか。／Bằng tiếng Việt là gì?",""],["なん","何","q","Cái gì","what","これは なんですか。／Cái này là gì?","Đọc なん trước です, の, và số đếm; các chỗ khác đọc なに."],["そう","","adv","Như vậy, đúng thế","so","はい、そうです。／Vâng, đúng vậy.",""],["ちがいます","違います","ex","Không phải, sai rồi","No, it isn't. / You are wrong.","いいえ、ちがいます。／Không, không phải.",""],["そうですか","","ex","Vậy à, thế à","I see. / Is that so?","そうですか。わかりました。／Vậy à, tôi hiểu rồi.","Xuống giọng khi nói để tỏ ý “à, ra vậy”."],["あのう","","it","À… (ngập ngừng)","well… (hesitation)","あのう、これは なんですか。／À… cái này là gì vậy?","Mở đầu câu một cách lịch sự, ngập ngừng."],["ほんのきもちです","ほんの気持ちです","ex","Chút lòng thành thôi ạ","It's nothing. / A token of my gratitude.","これ、ほんの きもちです。／Đây là chút lòng thành ạ.","Nói khi tặng quà."],["どうぞ","","ex","Xin mời","Please. / Here you are.","どうぞ、たべて ください。／Xin mời ăn.","Dùng khi mời hoặc đưa vật gì cho ai."],["どうも","","ex","Cảm ơn","Well, thanks.","あ、どうも。／À, cảm ơn nhé.","Cách cảm ơn ngắn, thân mật."],["どうもありがとうございます","","ex","Xin cảm ơn rất nhiều","Thank you very much.","おみやげ、どうも ありがとうございます。／Cảm ơn rất nhiều vì món quà.",""],["これからおせわになります","これからお世話になります","ex","Từ nay mong được anh/chị giúp đỡ","I hope for your kind assistance hereafter.","これから おせわに なります。どうぞ よろしく。／Từ nay mong được giúp đỡ ạ.","Nói với hàng xóm, đồng nghiệp mới."],["こちらこそよろしく","","ex","Chính tôi mới là người mong được giúp đỡ","Pleased to meet you too.","こちらこそ よろしく おねがいします。／Tôi cũng rất mong được giúp đỡ.","Đáp lại どうぞよろしく."]],"ref":[["さとう","佐藤","n","Họ Satō","Sato (surname)","さとうさんは どのひとですか。／Anh/chị Satō là người nào?","Họ phổ biến nhất ở Nhật"],["すずき","鈴木","n","Họ Suzuki","Suzuki (surname)","すずきさんは かいしゃいんです。／Anh/chị Suzuki là nhân viên công ty.","Họ phổ biến thứ 2"],["たかはし","高橋","n","Họ Takahashi","Takahashi (surname)","たかはしさんは せんせいです。／Thầy/cô Takahashi là giáo viên.",""],["たなか","田中","n","Họ Tanaka","Tanaka (surname)","たなかさんの かさは これです。／Ô của anh Tanaka là cái này.",""],["わたなべ","渡辺","n","Họ Watanabe","Watanabe (surname)","わたなべさんは ぎんこういんです。／Chị Watanabe là nhân viên ngân hàng.",""],["いとう","伊藤","n","Họ Itō","Ito (surname)","いとうせんせいは にほんごの せんせいです。／Cô Itō là giáo viên tiếng Nhật.",""],["やまもと","山本","n","Họ Yamamoto","Yamamoto (surname)","やまもとさんは どなたですか。／Anh Yamamoto là vị nào?",""],["なかむら","中村","n","Họ Nakamura","Nakamura (surname)","なかむらさんは IMCの しゃいんです。／Anh Nakamura là nhân viên công ty IMC.",""],["こばやし","小林","n","Họ Kobayashi","Kobayashi (surname)","こばやしさんの ほんです。／Đây là sách của anh Kobayashi.",""],["かとう","加藤","n","Họ Katō","Kato (surname)","かとうさんは だいがくの せんせいです。／Ông Katō là giảng viên đại học.",""],["よしだ","吉田","n","Họ Yoshida","Yoshida (surname)","よしださんは いしゃです。／Anh Yoshida là bác sĩ.",""],["やまだ","山田","n","Họ Yamada","Yamada (surname)","やまださんの かぎです。／Đây là chìa khóa của chị Yamada.",""],["ささき","佐々木","n","Họ Sasaki","Sasaki (surname)","ささきさんは なんさいですか。／Anh Sasaki bao nhiêu tuổi?","々 là ký hiệu lặp lại chữ Hán phía trước"],["さいとう","斎藤","n","Họ Saitō","Saito (surname)","さいとうさんは だれですか。／Anh Saitō là ai?",""],["やまぐち","山口","n","Họ Yamaguchi","Yamaguchi (surname)","やまぐちさんは エンジニアです。／Anh Yamaguchi là kỹ sư.",""],["まつもと","松本","n","Họ Matsumoto","Matsumoto (surname)","まつもとさんは ぶちょうです。／Ông Matsumoto là trưởng phòng.",""],["いのうえ","井上","n","Họ Inoue","Inoue (surname)","いのうえさんの でんわばんごうは なんばんですか。／Số điện thoại của anh Inoue là số mấy?",""],["きむら","木村","n","Họ Kimura","Kimura (surname)","きむらさんは けんきゅうしゃです。／Anh Kimura là nhà nghiên cứu.",""],["はやし","林","n","Họ Hayashi","Hayashi (surname)","はやしさんは どこの ひとですか。／Anh Hayashi là người ở đâu?",""],["しみず","清水","n","Họ Shimizu","Shimizu (surname)","しみずさんは きょうしです。／Chị Shimizu là giáo viên.",""]],"refTitle":"Họ (cách gọi tên người Nhật)","grammar":[{"title":"これ／それ／あれ – cái này, cái đó, cái kia","form":"これ／それ／あれ は N です","explain":"Là đại từ chỉ vật, dùng như danh từ. これ: vật gần người nói; それ: vật gần người nghe; あれ: vật xa cả hai người. Hỏi “cái nào” dùng どれ (Bài 16).","examples":[{"s":"それは じしょですか。","t":"Đó có phải là từ điển không?"},{"s":"これは だれの かさですか。","t":"Đây là ô của ai?"}],"tip":""},{"title":"この N／その N／あの N – N này, N đó, N kia","form":"この／その／あの + N","explain":"Khác これ/それ/あれ, nhóm この/その/あの KHÔNG đứng một mình mà luôn đi trước danh từ để bổ nghĩa cho nó.","examples":[{"s":"この ほんは わたしのです。","t":"Quyển sách này là của tôi."},{"s":"あの かたは どなたですか。","t":"Vị kia là ai?"}],"tip":"Sai: この は ほんです. Đúng: これは ほんです / この ほんは…."},{"title":"そうです／ちがいます – trả lời đúng/sai","form":"はい、そうです · いいえ、ちがいます","explain":"Với câu hỏi danh từ dạng “có phải là… không”, có thể trả lời ngắn はい、そうです (vâng, đúng vậy). Phủ định thường nói いいえ、ちがいます (không, không phải) hoặc nói luôn đáp án đúng, ít dùng いいえ、そうじゃ ありません.","examples":[{"s":"それは じしょですか。……はい、そうです。","t":"Đó là từ điển à? – Vâng, đúng vậy."},{"s":"それは ミラーさんのですか。……いいえ、ちがいます。","t":"Đó là của anh Miller à? – Không, không phải."},{"s":"それは シャープペンシルですか。……いいえ、ボールペンです。","t":"Đó là bút chì kim à? – Không, là bút bi."}],"tip":""},{"title":"S1 か、S2 か – câu hỏi lựa chọn","form":"N1 ですか、N2 ですか","explain":"Xếp hai câu hỏi liền nhau để người nghe chọn một. Khi trả lời KHÔNG dùng はい/いいえ mà nói thẳng phương án đúng.","examples":[{"s":"これは「9」ですか、「7」ですか。……「9」です。","t":"Đây là số 9 hay số 7? – Là số 9."},{"s":"あれは ボールペンですか、シャープペンシルですか。","t":"Kia là bút bi hay bút chì kim?"}],"tip":""},{"title":"N1 の N2 – nội dung & sở hữu","form":"N1 の N2","explain":"Mở rộng cách dùng の của Bài 1: ① N1 nói rõ N2 là về cái gì (sách về máy tính); ② N1 là người sở hữu N2 (sách của tôi).","examples":[{"s":"これは コンピューターの ほんです。","t":"Đây là sách về máy tính."},{"s":"これは わたしの ほんです。","t":"Đây là sách của tôi."}],"tip":""},{"title":"の thay cho danh từ đã nhắc","form":"N1 の (bỏ N2)","explain":"Khi N2 đã xuất hiện trước đó, có thể lược N2 và chỉ nói “N1 の”: của ai đó. Chỉ dùng thay cho đồ vật, không dùng thay cho người.","examples":[{"s":"あれは だれの かばんですか。……さとうさんのです。","t":"Kia là cặp của ai? – Của chị Satō."},{"s":"この かばんは あなたのですか。……いいえ、わたしのじゃ ありません。","t":"Cái cặp này của bạn à? – Không, không phải của tôi."}],"tip":"Sai: ミラーさんは IMCのです (thay cho 社員 – người). Đúng: IMCの しゃいんです."},{"title":"お～ – tiền tố lịch sự","form":"お + N","explain":"お đặt trước một số danh từ để câu nói lịch sự, nhẹ nhàng hơn: おみやげ (quà), おさけ (rượu).","examples":[{"s":"これは おみやげです。","t":"Đây là quà lưu niệm."},{"s":"これは にほんの おさけです。","t":"Đây là rượu Nhật."}],"tip":""},{"title":"そうですか – vậy à","form":"そうですか (xuống giọng)","explain":"Dùng khi tiếp nhận một thông tin mới và tỏ ý đã hiểu: “Thế à”, “Vậy à”. Đọc xuống giọng ở cuối (không phải câu hỏi).","examples":[{"s":"この かさは あなたのですか。……いいえ、ちがいます。シュミットさんのです。そうですか。","t":"Ô này của anh à? – Không, của anh Schmidt. – Thế à."}],"tip":""}]},{"n":3,"title":"Bài 3","jp":"これをください","sub":"ここ・そこ・あそこ · mua sắm, giá cả","rows":[["ここ","","pr","Chỗ này, ở đây","here, this place","ここは きょうしつです。／Đây là phòng học.",""],["そこ","","pr","Chỗ đó","there (near you)","そこは じむしょです。／Đó là văn phòng.",""],["あそこ","","pr","Chỗ kia","that place over there","トイレは あそこです。／Nhà vệ sinh ở đằng kia.",""],["どこ","","q","Ở đâu","where","えきは どこですか。／Nhà ga ở đâu?",""],["こちら","","pr","Phía này, đằng này (lịch sự)","this way (polite ここ)","こちらへ どうぞ。／Mời đi lối này.","Còn dùng để nói lịch sự “người này / tôi”."],["そちら","","pr","Phía đó (lịch sự)","that way (polite そこ)","そちらは どうですか。／Bên đó thế nào?",""],["あちら","","pr","Phía kia (lịch sự)","that way over there (polite あそこ)","エレベーターは あちらです。／Thang máy ở phía kia.",""],["どちら","","q","Phía nào, ở đâu (lịch sự)","which way, where (polite どこ)","おくには どちらですか。／Anh đến từ nước nào ạ?",""],["きょうしつ","教室","n","Phòng học","classroom","きょうしつは 3かいです。／Phòng học ở tầng 3.",""],["しょくどう","食堂","n","Nhà ăn","dining hall, canteen","しょくどうで ひるごはんを たべます。／Ăn trưa ở nhà ăn.",""],["じむしょ","事務所","n","Văn phòng","office","じむしょは 2かいです。／Văn phòng ở tầng 2.",""],["かいぎしつ","会議室","n","Phòng họp","conference room","かいぎしつは どこですか。／Phòng họp ở đâu?",""],["うけつけ","受付","n","Quầy lễ tân","reception desk","うけつけは あそこです。／Lễ tân ở đằng kia.",""],["ロビー","","n","Hành lang, sảnh","lobby","ロビーで まって ください。／Hãy đợi ở sảnh.",""],["へや","部屋","n","Căn phòng","room","わたしの へやは せまいです。／Phòng tôi chật.",""],["トイレ（おてあらい）","お手洗い","n","Nhà vệ sinh","toilet","おてあらいは どちらですか。／Nhà vệ sinh ở đâu ạ?","おてあらい lịch sự hơn トイレ."],["かいだん","階段","n","Cầu thang","staircase","かいだんで 2かいへ いきます。／Đi lên tầng 2 bằng cầu thang.",""],["エレベーター","","n","Thang máy","elevator, lift","エレベーターは あちらです。／Thang máy ở phía kia.",""],["エスカレーター","","n","Thang cuốn","escalator","エスカレーターで うりばへ いきます。／Lên quầy hàng bằng thang cuốn.",""],["［お］くに","［お］国","n","Đất nước, quê hương","country","おくには どちらですか。／Anh là người nước nào?","Thêm お khi hỏi về nước của người khác."],["かいしゃ","会社","n","Công ty","company","かいしゃは どちらですか。／Anh làm ở công ty nào?",""],["うち","家","n","Nhà","house, home","うちへ かえります。／Về nhà.",""],["でんわ","電話","n","Điện thoại, cuộc gọi","telephone, telephone call","でんわは あそこです。／Điện thoại ở đằng kia.",""],["くつ","靴","n","Giày","shoes","この くつは いくらですか。／Đôi giày này bao nhiêu tiền?",""],["ネクタイ","","n","Cà vạt","necktie","ネクタイを みせて ください。／Cho tôi xem cà vạt.",""],["ワイン","","n","Rượu vang","wine","イタリアの ワインです。／Là rượu vang Ý.",""],["たばこ","煙草","n","Thuốc lá","tobacco, cigarette","たばこは すいません。／Tôi không hút thuốc.","Thường viết bằng hiragana."],["うりば","売り場","n","Quầy bán hàng","counter (in a department store)","くつの うりばは どこですか。／Quầy giày ở đâu?",""],["ちか","地下","n","Tầng hầm","basement","しょくどうは ちかに あります。／Nhà ăn ở tầng hầm.",""],["～かい（～がい）","～階","ctr","Tầng ~","~th floor","ワインうりばは ちか1かいです。／Quầy rượu ở tầng hầm 1.","3 tầng đọc さんがい."],["なんがい","何階","q","Tầng mấy","what floor","じむしょは なんがいですか。／Văn phòng ở tầng mấy?",""],["～えん","～円","ctr","~ yên","~ yen","これは 500えんです。／Cái này 500 yên.",""],["いくら","","q","Bao nhiêu tiền","how much","この かばんは いくらですか。／Cái túi này bao nhiêu tiền?",""],["ひゃく","百","num","Một trăm","hundred","ひゃくえんです。／Là 100 yên.","300 さんびゃく, 600 ろっぴゃく, 800 はっぴゃく."],["せん","千","num","Một nghìn","thousand","せんえんです。／Là 1000 yên.","3000 さんぜん, 8000 はっせん."],["まん","万","num","Mười nghìn","ten thousand","いちまんえんです。／Là 10.000 yên.","Phải nói いちまん, không nói まん một mình."],["すみません","すみません","ex","Xin lỗi (gọi người khác)","Excuse me.","すみません、くつの うりばは どこですか。／Xin lỗi, quầy giày ở đâu?",""],["～でございます","","ex","Là ~ (rất lịch sự)","polite equivalent of です","うりばは 2かいで ございます。／Quầy hàng ở tầng 2 ạ.","Nhân viên bán hàng hay dùng."],["［～を］みせてください","［～を］見せてください","ex","Cho tôi xem [~]","Please show me [~].","その とけいを みせて ください。／Cho tôi xem cái đồng hồ đó.",""],["じゃ","","cj","Vậy thì, thế thì","well, then","じゃ、これを ください。／Vậy thì cho tôi cái này.",""],["［～を］ください","","ex","Cho tôi [~]","Give me [~], please.","この ワインを ください。／Cho tôi chai rượu này.",""]],"ref":[["おくじょう","屋上","n","Sân thượng","rooftop","おくじょうに ゆうえんちが あります。／Trên sân thượng có khu vui chơi.",""],["ゆうえんち","遊園地","n","Công viên giải trí, khu vui chơi","amusement park","こどもと ゆうえんちへ いきます。／Tôi đi khu vui chơi với con.",""],["もよおしものかいじょう","催し物会場","n","Phòng tổ chức sự kiện","event hall","もよおしものかいじょうは 8かいです。／Phòng tổ chức sự kiện ở tầng 8.",""],["スポーツようひん","スポーツ用品","n","Dụng cụ thể thao","sporting goods","スポーツようひんは 6かいに あります。／Dụng cụ thể thao ở tầng 6.",""],["りょこうようひん","旅行用品","n","Đồ du lịch","travel goods","りょこうようひんうりばは どこですか。／Quầy đồ du lịch ở đâu?",""],["こどもふく","子ども服","n","Quần áo trẻ em","children's clothing","こどもふくは 5かいです。／Quần áo trẻ em ở tầng 5.",""],["おもちゃ","","n","Đồ chơi","toy","おもちゃうりばは どこですか。／Quầy đồ chơi ở đâu?",""],["ぶんぼうぐ","文房具","n","Văn phòng phẩm","stationery","ぶんぼうぐを かいに いきます。／Tôi đi mua văn phòng phẩm.",""],["かぐ","家具","n","Đồ gỗ, nội thất","furniture","かぐは 4かいです。／Đồ nội thất ở tầng 4.",""],["しょっき","食器","n","Bát đĩa, đồ ăn","tableware","しょっきうりばは 4かいです。／Quầy bát đĩa ở tầng 4.",""],["でんかせいひん","電化製品","n","Sản phẩm điện máy","electrical appliances","でんかせいひんは どこで うっていますか。／Đồ điện máy bán ở đâu?",""],["しんしふく","紳士服","n","Quần áo nam","men's clothing","しんしふくうりばは 3がいです。／Quầy quần áo nam ở tầng 3.",""],["ふじんふく","婦人服","n","Quần áo nữ","women's clothing","ふじんふくは 2かいに あります。／Quần áo nữ ở tầng 2.",""],["アクセサリー","","n","Đồ trang sức, phụ kiện","accessories","アクセサリーは 1かいです。／Đồ trang sức ở tầng 1.",""],["けしょうひん","化粧品","n","Mỹ phẩm","cosmetics","けしょうひんうりばは 1かいです。／Quầy mỹ phẩm ở tầng 1.",""],["しょくひん","食品","n","Thực phẩm","food","しょくひんうりばは ちかです。／Quầy thực phẩm ở tầng hầm.",""]],"refTitle":"Cửa hàng bách hóa","grammar":[{"title":"ここ／そこ／あそこ／こちら／そちら／あちら","form":"ここ (đây) · そこ (đó) · あそこ (kia) · こちら／そちら／あちら (lịch sự, chỉ hướng)","explain":"ここ: nơi người nói đang ở; そこ: nơi người nghe đang ở; あそこ: nơi xa cả hai. Khi hai người đứng cùng một chỗ thì ここ là chỗ cả hai đang đứng, そこ hơi xa, あそこ xa hơn nữa.\n\nこちら/そちら/あちら vốn chỉ phương hướng, nhưng cũng dùng thay cho ここ/そこ/あそこ với sắc thái lịch sự.","examples":[{"s":"ここは しょくどうです。","t":"Đây là nhà ăn."},{"s":"エレベーターは あちらです。","t":"Thang máy ở đằng kia ạ."}],"tip":""},{"title":"N は địa điểm です – vật/người ở đâu","form":"N は ここ／そこ／あそこ／Nơi chốn です","explain":"Mẫu câu cho biết một vật, một người hay một địa điểm ở đâu.","examples":[{"s":"おてあらいは あそこです。","t":"Nhà vệ sinh ở đằng kia."},{"s":"でんわは 2かいです。","t":"Điện thoại ở tầng 2."},{"s":"やまださんは じむしょです。","t":"Anh Yamada ở văn phòng."}],"tip":""},{"title":"どこ／どちら – ở đâu","form":"N は どこ／どちら ですか","explain":"どこ hỏi địa điểm, どちら hỏi phương hướng nhưng cũng dùng hỏi địa điểm một cách lịch sự hơn. Hỏi tên trường, công ty, đất nước mình thuộc về cũng dùng どこ/どちら (không dùng なん).","examples":[{"s":"おてあらいは どこですか。……あそこです。","t":"Nhà vệ sinh ở đâu? – Ở đằng kia."},{"s":"エレベーターは どちらですか。……あちらです。","t":"Thang máy ở chỗ nào ạ? – Ở đằng kia ạ."},{"s":"かいしゃは どちらですか。","t":"Anh/chị làm ở công ty nào ạ?"}],"tip":"Sai: がっこうは なんですか (hỏi tên trường). Đúng: がっこうは どこですか."},{"title":"N1 の N2 – xuất xứ, nhà sản xuất","form":"Quốc gia/Công ty の N","explain":"Khi N1 là tên nước hay tên công ty, N2 là sản phẩm thì の nghĩa là “sản phẩm của nước/công ty đó”. Hỏi dùng どこの N.","examples":[{"s":"これは どこの コンピューターですか。……にほんの コンピューターです。","t":"Đây là máy tính của nước nào? – Máy tính Nhật."},{"s":"……パワーでんきの コンピューターです。","t":"– Máy tính của hãng điện Power."}],"tip":""},{"title":"Hệ thống こ／そ／あ／ど","form":"これ・それ・あれ・どれ · この・その・あの・どの · ここ・そこ・あそこ・どこ · こちら・そちら・あちら・どちら","explain":"Bốn nhóm theo cùng một quy luật: こ – gần người nói, そ – gần người nghe, あ – xa cả hai, ど – từ để hỏi. Hàng đồ vật (これ…), hàng bổ nghĩa danh từ (この…), hàng nơi chốn (ここ…), hàng phương hướng / nơi chốn lịch sự (こちら…).","examples":[{"s":"この かさは だれのですか。","t":"Cái ô này của ai?"},{"s":"どの ひとが さとうさんですか。","t":"Người nào là chị Satō?"}],"tip":""},{"title":"お～ – kính trọng người nghe","form":"お + N (thuộc về người nghe / ngôi thứ ba)","explain":"Tiền tố お đặt trước từ liên quan đến người nghe hoặc người được nói tới để tỏ sự kính trọng: おくに (đất nước của anh/chị).","examples":[{"s":"おくには どちらですか。","t":"Anh/chị là người nước nào?"}],"tip":"Không dùng お cho đồ vật, đất nước của chính mình: Sai: わたしの おくに."}]},{"n":4,"title":"Bài 4","jp":"そちらは何時から何時までですか","sub":"Giờ giấc · ～から～まで · động từ ます","rows":[["おきます","起きます","v2","Thức dậy","get up, wake up","まいあさ 6じに おきます。／Sáng nào tôi cũng dậy lúc 6 giờ.","Nhóm II · thể từ điển: おきる"],["ねます","寝ます","v2","Ngủ, đi ngủ","sleep, go to bed","よる 11じに ねます。／Tôi đi ngủ lúc 11 giờ đêm.","Nhóm II · thể từ điển: ねる"],["はたらきます","働きます","v1","Làm việc","work","9じから 5じまで はたらきます。／Làm việc từ 9 giờ đến 5 giờ.","Nhóm I · thể từ điển: はたらく"],["やすみます","休みます","v1","Nghỉ ngơi, nghỉ (làm, học)","take a rest, take a holiday","どようびは やすみます。／Thứ bảy tôi nghỉ.","Nhóm I · thể từ điển: やすむ"],["べんきょうします","勉強します","v3","Học","study","まいばん にほんごを べんきょうします。／Tối nào cũng học tiếng Nhật.","Nhóm III · thể từ điển: べんきょうする"],["おわります","終わります","v1","Kết thúc, xong","finish","しごとは 6じに おわります。／Công việc xong lúc 6 giờ.","Nhóm I · thể từ điển: おわる"],["デパート","","n","Cửa hàng bách hoá","department store","デパートは 10じからです。／Bách hoá mở cửa từ 10 giờ.",""],["ぎんこう","銀行","n","Ngân hàng","bank","ぎんこうは 3じまでです。／Ngân hàng làm đến 3 giờ.",""],["ゆうびんきょく","郵便局","n","Bưu điện","post office","ゆうびんきょくへ いきます。／Đi bưu điện.",""],["としょかん","図書館","n","Thư viện","library","としょかんで べんきょうします。／Học ở thư viện.",""],["びじゅつかん","美術館","n","Bảo tàng mỹ thuật","art museum","にちようびに びじゅつかんへ いきます。／Chủ nhật đi bảo tàng mỹ thuật.",""],["いま","今","n","Bây giờ","now","いま 4じ はんです。／Bây giờ là 4 giờ rưỡi.",""],["～じ","～時","ctr","~ giờ","~ o'clock","いま なんじですか。ー3じです。／Mấy giờ rồi? — 3 giờ.","4 giờ よじ, 7 giờ しちじ, 9 giờ くじ."],["～ふん（～ぷん）","～分","ctr","~ phút","~ minute","10じ 15ふんです。／10 giờ 15 phút.","1,3,4,6,8,10 đọc ぷん: いっぷん, さんぷん, よんぷん, ろっぷん, はっぷん, じゅっぷん."],["はん","半","n","Rưỡi, một nửa","half","6じ はんに おきます。／Dậy lúc 6 giờ rưỡi.",""],["なんじ","何時","q","Mấy giờ","what time","なんじに ねますか。／Mấy giờ bạn đi ngủ?",""],["なんぷん","何分","q","Mấy phút","what minute","いま なんじ なんぷんですか。／Bây giờ là mấy giờ mấy phút?",""],["ごぜん","午前","n","Sáng, buổi sáng (a.m.)","a.m., morning","ごぜん 9じから はたらきます。／Làm việc từ 9 giờ sáng.","Đặt trước giờ."],["ごご","午後","n","Chiều (p.m.)","p.m., afternoon","ごご 2じに かいぎが あります。／Có cuộc họp lúc 2 giờ chiều.",""],["あさ","朝","n","Buổi sáng","morning","あさ コーヒーを のみます。／Buổi sáng uống cà phê.",""],["ひる","昼","n","Buổi trưa, ban ngày","daytime, noon","ひるに こうえんへ いきます。／Buổi trưa đi công viên.",""],["ばん（よる）","晩（夜）","n","Buổi tối, đêm","night, evening","ばん テレビを みます。／Buổi tối xem ti vi.",""],["おととい","一昨日","n","Hôm kia","the day before yesterday","おととい デパートへ いきました。／Hôm kia tôi đi bách hoá.",""],["きのう","昨日","n","Hôm qua","yesterday","きのう べんきょうしました。／Hôm qua tôi đã học.",""],["きょう","今日","n","Hôm nay","today","きょうは なんようびですか。／Hôm nay là thứ mấy?",""],["あした","明日","n","Ngày mai","tomorrow","あした やすみます。／Ngày mai tôi nghỉ.",""],["あさって","明後日","n","Ngày kia","the day after tomorrow","あさって しけんが あります。／Ngày kia có bài thi.",""],["けさ","今朝","n","Sáng nay","this morning","けさ 7じに おきました。／Sáng nay tôi dậy lúc 7 giờ.",""],["こんばん","今晩","n","Tối nay","this evening, tonight","こんばん べんきょうします。／Tối nay tôi học.",""],["やすみ","休み","n","Nghỉ, ngày nghỉ","rest, a holiday, a day off","やすみは にちようびです。／Ngày nghỉ là chủ nhật.",""],["ひるやすみ","昼休み","n","Nghỉ trưa","lunchtime","ひるやすみは 12じからです。／Nghỉ trưa từ 12 giờ.",""],["まいあさ","毎朝","n","Mỗi sáng","every morning","まいあさ さんぽします。／Sáng nào cũng đi dạo.",""],["まいばん","毎晩","n","Mỗi tối","every evening","まいばん にっきを かきます。／Tối nào cũng viết nhật ký.",""],["まいにち","毎日","n","Mỗi ngày","every day","まいにち はたらきます。／Ngày nào cũng làm việc.",""],["げつようび","月曜日","n","Thứ hai","Monday","げつようびから きんようびまで はたらきます。／Làm việc từ thứ hai đến thứ sáu.",""],["かようび","火曜日","n","Thứ ba","Tuesday","かようびに テストが あります。／Thứ ba có bài kiểm tra.",""],["すいようび","水曜日","n","Thứ tư","Wednesday","すいようびは やすみです。／Thứ tư là ngày nghỉ.",""],["もくようび","木曜日","n","Thứ năm","Thursday","もくようびに としょかんへ いきます。／Thứ năm đi thư viện.",""],["きんようび","金曜日","n","Thứ sáu","Friday","きんようびの ばん パーティーが あります。／Tối thứ sáu có tiệc.",""],["どようび","土曜日","n","Thứ bảy","Saturday","どようびは はたらきません。／Thứ bảy không làm việc.",""],["にちようび","日曜日","n","Chủ nhật","Sunday","にちようびに かぞくと でかけます。／Chủ nhật đi chơi với gia đình.",""],["なんようび","何曜日","q","Thứ mấy","what day of the week","きょうは なんようびですか。／Hôm nay là thứ mấy?",""],["ばんごう","番号","n","Số","number","でんわばんごうは なんばんですか。／Số điện thoại là số mấy?",""],["なんばん","何番","q","Số mấy","what number","ぎんこうの でんわばんごうは なんばんですか。／Số điện thoại ngân hàng là bao nhiêu?",""],["～から","","pt","Từ ~","from ~","9じから はたらきます。／Làm việc từ 9 giờ.",""],["～まで","","pt","Đến ~","up to ~, until ~","5じまで はたらきます。／Làm việc đến 5 giờ.","Hay đi cặp ～から～まで."],["～と～","","pt","~ và ~ (nối danh từ)","and (connecting nouns)","やすみは どようびと にちようびです。／Ngày nghỉ là thứ bảy và chủ nhật.","Chỉ nối danh từ, không nối câu."],["そちら","","pr","Chỗ của anh/chị (bên đó)","your place","そちらは なんじまでですか。／Bên đó mở cửa đến mấy giờ?","Dùng trong điện thoại để chỉ nơi người nghe."],["たいへんですね","大変ですね","ex","Vất vả nhỉ","That's tough, isn't it?","まいばん 12じまで はたらきます。ーたいへんですね。／Tối nào cũng làm đến 12 giờ. — Vất vả nhỉ.","Dùng để bày tỏ sự cảm thông."],["えーと","","it","À, để xem nào","well, let me see","えーと、3じです。／À… 3 giờ.","Khi đang suy nghĩ."],["１０４","","n","Tổng đài hỏi số điện thoại","information, directory assistance","104に でんわします。／Gọi tổng đài 104.","Đọc いちれいよん."],["おねがいします","お願いします","ex","Nhờ anh/chị (làm ơn)","Please. (lit. ask for a favor)","ばんごうを おねがいします。／Làm ơn cho tôi số điện thoại.",""],["かしこまりました","","ex","Tôi hiểu rồi ạ (rất lịch sự)","Certainly (sir, madam).","はい、かしこまりました。／Vâng, tôi hiểu rồi ạ.","Nhân viên nói với khách."],["おといあわせのばんごう","お問い合わせの番号","ex","Số điện thoại cần hỏi","the number being inquired about","おといあわせの ばんごうは 5275の2725です。／Số anh hỏi là 5275-2725.",""],["［どうも］ありがとうございました","","ex","Xin cảm ơn rất nhiều (việc đã xong)","Thank you very much.","どうも ありがとうございました。／Xin cảm ơn rất nhiều.","Dạng quá khứ: cảm ơn cho việc đã được giúp xong."]],"ref":[["こうしゅうでんわ","公衆電話","n","Điện thoại công cộng","public telephone","こうしゅうでんわは どこですか。／Điện thoại công cộng ở đâu?","Chỉ dùng được thẻ hoặc xu 10 yên, 100 yên"],["けいさつしょ","警察署","n","Đồn cảnh sát","police station","けいさつしょは 110ばんです。／Số gọi cảnh sát là 110.","Gọi 110"],["しょうぼうしょ","消防署","n","Sở cứu hỏa","fire station","かじです。しょうぼうしょに でんわして ください。／Cháy! Hãy gọi cứu hỏa.","Gọi 119"],["じほう","時報","n","Dịch vụ báo giờ","time signal","じほうは 117ばんです。／Dịch vụ báo giờ là số 117.","Gọi 117"],["てんきよほう","天気予報","n","Dự báo thời tiết","weather forecast","あしたの てんきよほうを ききます。／Tôi nghe dự báo thời tiết ngày mai.","Gọi 177"],["でんわばんごうあんない","電話番号案内","n","Dịch vụ hỏi số điện thoại","directory assistance","でんわばんごうあんないは 104ばんです。／Dịch vụ hỏi số điện thoại là 104.","Gọi 104"],["ゆうびんばんごう","郵便番号","n","Mã bưu điện","postal code","ゆうびんばんごうは 658-0063です。／Mã bưu điện là 658-0063.","Viết sau ký hiệu 〒"],["し","市","n","Thành phố","city","こうべしは ひょうごけんに あります。／Thành phố Kobe ở tỉnh Hyōgo.",""],["く","区","n","Quận","ward","ちゅうおうく／quận Chūō",""],["～ごう","～号","sf","Số (phòng, nhà)","number (room)","コウベハイツ 405ごう／phòng 405, tòa Kobe Heights",""]],"refTitle":"Điện thoại & thư tín","grammar":[{"title":"Giờ và phút – 今 ～時～分です","form":"～じ (時) ～ふん／ぷん (分) · 何時 (なんじ) · 何分 (なんぷん)","explain":"Nói giờ: số + じ; phút: số + ふん hoặc ぷん (2, 5, 7, 9 → ふん; 1, 3, 4, 6, 8, 10 → ぷん, kèm biến âm いっぷん, ろっぷん, はっぷん, じゅっぷん). Rưỡi: はん. Hỏi giờ: なんじ, hỏi phút: なんぷん.\n\nLưu ý: 4 giờ = よじ, 7 giờ = しちじ, 9 giờ = くじ.","examples":[{"s":"いま なんじですか。……7じ 10ぷんです。","t":"Bây giờ là mấy giờ? – 7 giờ 10 phút."},{"s":"ニューヨークは いま なんじですか。","t":"Ở New York bây giờ là mấy giờ?"}],"tip":""},{"title":"V ます／ません／ました／ませんでした","form":"Hiện tại/tương lai: ～ます / ～ません · Quá khứ: ～ました / ～ませんでした","explain":"Động từ đuôi ます là thể lịch sự. Dạng ます dùng cho thói quen, sự thật, và việc sẽ làm trong tương lai. Quá khứ đổi ます → ました, phủ định quá khứ ません → ませんでした.\n\nCâu hỏi: thêm か cuối câu. Trả lời bằng chính động từ đó (không dùng そうです/ちがいます cho câu động từ).","examples":[{"s":"わたしは まいにち べんきょうします。","t":"Tôi học hằng ngày."},{"s":"あした 6じに おきます。","t":"Mai tôi dậy lúc 6 giờ."},{"s":"きのう べんきょうしましたか。……いいえ、べんきょうしませんでした。","t":"Hôm qua bạn có học không? – Không, hôm qua tôi không học."}],"tip":"Sai: べんきょうしましたか。……はい、そうです. Đúng: はい、べんきょうしました."},{"title":"Thời điểm + に + V","form":"N (thời gian có số) + に + V","explain":"Trợ từ に đặt sau từ chỉ thời điểm có con số (giờ, ngày tháng, năm) để nói hành động xảy ra lúc nào.\n\nKhông dùng に với: きょう, あした, あさって, きのう, おととい, けさ, こんばん, いま, まいあさ, まいばん, まいにち, せんしゅう, こんしゅう, らいしゅう, いつ, せんげつ, こんげつ, らいげつ, ことし, らいねん, きょねん… Với thứ trong tuần, あさ, ひる, ばん, よる thì có hoặc không có に đều được.","examples":[{"s":"6じはんに おきます。","t":"Tôi dậy lúc 6 giờ rưỡi."},{"s":"7がつ ふつかに にほんへ きました。","t":"Tôi đến Nhật ngày 2 tháng 7."},{"s":"きのう べんきょうしました。","t":"Hôm qua tôi đã học. (không có に)"}],"tip":"Sai: あしたに いきます. Đúng: あした いきます."},{"title":"N1 から N2 まで – từ… đến…","form":"N1 から N2 まで","explain":"から: điểm bắt đầu, まで: điểm kết thúc của thời gian hay nơi chốn. Có thể dùng riêng lẻ. Cũng có thể gắn です ngay sau: ～から ～までです.","examples":[{"s":"9じから 5じまで べんきょうします。","t":"Tôi học từ 9 giờ đến 5 giờ."},{"s":"おおさかから とうきょうまで 3じかん かかります。","t":"Từ Ōsaka đến Tōkyō mất 3 tiếng."},{"s":"ぎんこうは 9じから 3じまでです。","t":"Ngân hàng mở cửa từ 9 giờ đến 3 giờ."},{"s":"ひるやすみは 12じからです。","t":"Giờ nghỉ trưa bắt đầu từ 12 giờ."}],"tip":""},{"title":"N1 と N2 – và","form":"N1 と N2","explain":"と nối hai danh từ ngang hàng: “và”. Chỉ nối danh từ, không nối động từ hay câu.","examples":[{"s":"ぎんこうの やすみは どようびと にちようびです。","t":"Ngân hàng nghỉ thứ Bảy và Chủ nhật."},{"s":"パンと たまごを たべます。","t":"Tôi ăn bánh mì và trứng."}],"tip":""},{"title":"～ね – nhỉ, nhé","form":"Câu + ね","explain":"ね đặt cuối câu thể hiện mong người nghe đồng tình, hoặc để xác nhận, nhắc lại điều mình hiểu: “… nhỉ”, “… đúng không”.","examples":[{"s":"まいにち 10じまで べんきょうします。……たいへんですね。","t":"Ngày nào tôi cũng học đến 10 giờ. – Vất vả nhỉ."},{"s":"やまださんの でんわばんごうは 871の 6813です。……871の 6813ですね。","t":"Số điện thoại của anh Yamada là 871-6813. – 871-6813 đúng không ạ."}],"tip":""},{"title":"～ごろ – khoảng (thời điểm) · bổ sung N5","form":"Thời điểm + ごろ (に) · số lượng + ぐらい","explain":"ごろ đặt sau mốc thời gian để nói “khoảng, tầm” (khoảng 7 giờ, khoảng tháng 5). ぐらい (Bài 11) dùng cho số lượng, độ dài thời gian.","examples":[{"s":"まいばん 11じごろ ねます。","t":"Tối nào tôi cũng ngủ khoảng 11 giờ."},{"s":"5がつごろ にほんへ いきます。","t":"Khoảng tháng 5 tôi sẽ đi Nhật."}],"tip":"Sai: 2じかんごろ. Đúng: 2じかんぐらい (độ dài) / 2じごろ (mốc giờ)."}]},{"n":5,"title":"Bài 5","jp":"甲子園へ行きますか","sub":"Đi lại · phương tiện · ngày tháng","rows":[["いきます","行きます","v1","Đi","go","あした きょうとへ いきます。／Ngày mai tôi đi Kyoto.","Nhóm I · thể từ điển: いく · chỉ hướng dùng へ."],["きます","来ます","v3","Đến","come","ミラーさんは らいねん にほんへ きます。／Năm sau anh Miller sẽ đến Nhật.","Nhóm III · thể từ điển: くる"],["かえります","帰ります","v1","Về (nhà, nước)","go home, return","7じに うちへ かえります。／7 giờ tôi về nhà.","Nhóm I · thể từ điển: かえる (dù đuôi える nhưng là nhóm I)"],["がっこう","学校","n","Trường học","school","あるいて がっこうへ いきます。／Đi bộ đến trường.",""],["スーパー","","n","Siêu thị","supermarket","スーパーで やさいを かいます。／Mua rau ở siêu thị.",""],["えき","駅","n","Nhà ga","station","えきまで あるいて 10ぷんです。／Đi bộ đến ga mất 10 phút.",""],["ひこうき","飛行機","n","Máy bay","airplane","ひこうきで ベトナムへ かえります。／Về Việt Nam bằng máy bay.","Phương tiện dùng で."],["ふね","船","n","Tàu thuỷ, thuyền","ship","ふねで おおさかへ いきます。／Đi Osaka bằng tàu thuỷ.",""],["でんしゃ","電車","n","Tàu điện","electric train","でんしゃで かいしゃへ いきます。／Đi làm bằng tàu điện.",""],["ちかてつ","地下鉄","n","Tàu điện ngầm","subway","ちかてつで しんじゅくへ いきます。／Đi Shinjuku bằng tàu điện ngầm.",""],["しんかんせん","新幹線","n","Tàu cao tốc Shinkansen","the Shinkansen, bullet train","しんかんせんで とうきょうへ いきます。／Đi Tokyo bằng Shinkansen.",""],["バス","","n","Xe buýt","bus","バスで がっこうへ いきます。／Đi học bằng xe buýt.",""],["タクシー","","n","Taxi","taxi","タクシーで うちへ かえりました。／Đã về nhà bằng taxi.",""],["じてんしゃ","自転車","n","Xe đạp","bicycle","じてんしゃで スーパーへ いきます。／Đi siêu thị bằng xe đạp.",""],["あるいて","歩いて","adv","Đi bộ","on foot","あるいて えきへ いきます。／Đi bộ ra ga.","Không dùng で: không nói あるいてで."],["ひと","人","n","Người","person, people","あの ひとは だれですか。／Người kia là ai?",""],["ともだち","友達","n","Bạn bè","friend","ともだちと えいがを みます。／Xem phim với bạn.",""],["かれ","彼","pr","Anh ấy, bạn trai","he, boyfriend","かれは がくせいです。／Anh ấy là sinh viên.","Còn có nghĩa là bạn trai."],["かのじょ","彼女","pr","Cô ấy, bạn gái","she, girlfriend","かのじょと こうえんへ いきました。／Đã đi công viên với bạn gái.",""],["かぞく","家族","n","Gia đình","family","かぞくと にほんへ きました。／Tôi đến Nhật cùng gia đình.",""],["ひとりで","一人で","adv","Một mình","alone, by oneself","ひとりで うちへ かえります。／Về nhà một mình.","Không dùng と: ひとりで."],["せんしゅう","先週","n","Tuần trước","last week","せんしゅう きょうとへ いきました。／Tuần trước tôi đi Kyoto.",""],["こんしゅう","今週","n","Tuần này","this week","こんしゅう いそがしいです。／Tuần này bận.",""],["らいしゅう","来週","n","Tuần sau","next week","らいしゅう テストが あります。／Tuần sau có bài kiểm tra.",""],["せんげつ","先月","n","Tháng trước","last month","せんげつ にほんへ きました。／Tháng trước tôi đến Nhật.",""],["こんげつ","今月","n","Tháng này","this month","こんげつは ひまです。／Tháng này rảnh.",""],["らいげつ","来月","n","Tháng sau","next month","らいげつ くにへ かえります。／Tháng sau tôi về nước.",""],["きょねん","去年","n","Năm ngoái","last year","きょねん けっこんしました。／Năm ngoái tôi kết hôn.",""],["ことし","今年","n","Năm nay","this year","ことし だいがくへ いきます。／Năm nay tôi vào đại học.",""],["らいねん","来年","n","Năm sau","next year","らいねん にほんへ いきます。／Năm sau tôi đi Nhật.",""],["～がつ","～月","ctr","Tháng ~","~th month of the year","わたしの たんじょうびは 4がつです。／Sinh nhật tôi vào tháng 4.","Tháng 4 しがつ, tháng 7 しちがつ, tháng 9 くがつ."],["なんがつ","何月","q","Tháng mấy","what month","なんがつに にほんへ きましたか。／Anh đến Nhật vào tháng mấy?",""],["ついたち","一日","n","Ngày mùng 1","first day of the month","1がつ ついたちは しょうがつです。／Ngày 1 tháng 1 là Tết.","Khi đếm “một ngày” thì đọc いちにち."],["ふつか","二日","n","Ngày mùng 2, hai ngày","second, two days","ふつかに かえります。／Về vào ngày mùng 2.",""],["みっか","三日","n","Ngày mùng 3, ba ngày","third, three days","みっか やすみます。／Nghỉ ba ngày.",""],["よっか","四日","n","Ngày mùng 4, bốn ngày","fourth, four days","よっかは かようびです。／Mùng 4 là thứ ba.",""],["いつか","五日","n","Ngày mùng 5, năm ngày","fifth, five days","5がつ いつかは こどもの ひです。／Ngày 5 tháng 5 là ngày thiếu nhi.",""],["むいか","六日","n","Ngày mùng 6, sáu ngày","sixth, six days","むいかに しけんが あります。／Mùng 6 có bài thi.",""],["なのか","七日","n","Ngày mùng 7, bảy ngày","seventh, seven days","なのかに きます。／Sẽ đến vào ngày mùng 7.",""],["ようか","八日","n","Ngày mùng 8, tám ngày","eighth, eight days","ようかは たんじょうびです。／Mùng 8 là sinh nhật.",""],["ここのか","九日","n","Ngày mùng 9, chín ngày","ninth, nine days","ここのかに かえります。／Về vào mùng 9.",""],["とおか","十日","n","Ngày mùng 10, mười ngày","tenth, ten days","とおか やすみます。／Nghỉ mười ngày.",""],["じゅうよっか","十四日","n","Ngày 14, mười bốn ngày","fourteenth, fourteen days","2がつ じゅうよっかは バレンタインデーです。／Ngày 14 tháng 2 là Valentine.",""],["はつか","二十日","n","Ngày 20, hai mươi ngày","twentieth, twenty days","はつかに パーティーを します。／Ngày 20 sẽ tổ chức tiệc.",""],["にじゅうよっか","二十四日","n","Ngày 24, hai mươi bốn ngày","twenty-fourth, twenty-four days","12がつ にじゅうよっかは クリスマスイブです。／Ngày 24 tháng 12 là đêm Giáng sinh.",""],["～にち","～日","ctr","Ngày ~, ~ ngày","~th day of the month, ~ days","15にちに きます。／Đến vào ngày 15.",""],["なんにち","何日","q","Ngày mấy, mấy ngày","which day of the month, how many days","たんじょうびは なんにちですか。／Sinh nhật ngày mấy?",""],["いつ","","q","Khi nào","when","いつ にほんへ きましたか。／Bạn đến Nhật khi nào?","Không dùng に sau いつ."],["たんじょうび","誕生日","n","Sinh nhật","birthday","たんじょうびは いつですか。／Sinh nhật bạn khi nào?",""],["ふつう","普通","n","Tàu thường (dừng mọi ga)","local (train)","ふつうで いきます。／Đi tàu thường.",""],["きゅうこう","急行","n","Tàu tốc hành","rapid","きゅうこうは とまりません。／Tàu tốc hành không dừng.",""],["とっきゅう","特急","n","Tàu tốc hành đặc biệt","express","とっきゅうで おおさかへ いきます。／Đi Osaka bằng tàu đặc biệt.",""],["つぎの","次の","ex","~ tiếp theo","next","つぎの でんしゃは なんじですか。／Chuyến tàu tiếp theo là mấy giờ?","Đi kèm danh từ."],["どういたしまして","","ex","Không có gì","You're welcome.","ありがとう。ーどういたしまして。／Cảm ơn. — Không có gì.",""],["～ばんせん","～番線","ctr","Đường ray số ~, sân ga số ~","platform ~","5ばんせんです。／Ở sân ga số 5.",""]],"ref":[["しゅくさいじつ","祝祭日","n","Ngày nghỉ lễ quốc gia","national holiday","5がつに しゅくさいじつが 3つ あります。／Tháng 5 có ba ngày nghỉ lễ.",""],["がんじつ","元日","n","Ngày mồng 1 Tết (1/1)","New Year's Day","がんじつに かぞくと じんじゃへ いきます。／Ngày mồng 1 Tết tôi đi đền với gia đình.","1 tháng 1"],["せいじんのひ","成人の日","n","Ngày Lễ thành nhân","Coming-of-Age Day","せいじんのひは 1がつの だい2げつようびです。／Lễ thành nhân là thứ Hai tuần thứ hai tháng 1.","Thứ Hai tuần 2 của tháng 1"],["けんこくきねんのひ","建国記念の日","n","Ngày Quốc khánh (kỷ niệm lập quốc)","National Foundation Day","けんこくきねんのひは 2がつ11にちです。／Ngày Quốc khánh là 11 tháng 2.","11/2"],["しゅんぶんのひ","春分の日","n","Ngày Xuân phân","Vernal Equinox Day","しゅんぶんのひは まいとし かわります。／Ngày Xuân phân mỗi năm một khác.","Khoảng 20/3"],["しょうわのひ","昭和の日","n","Ngày kỷ niệm Thiên hoàng Showa","Showa Day","しょうわのひは 4がつ29にちです。／Ngày Showa là 29 tháng 4.","29/4, mở đầu Tuần lễ vàng"],["けんぽうきねんび","憲法記念日","n","Ngày Kỷ niệm Hiến pháp","Constitution Memorial Day","けんぽうきねんびは 5がつ3かです。／Ngày Hiến pháp là mùng 3 tháng 5.","3/5"],["みどりのひ","みどりの日","n","Ngày Màu xanh","Greenery Day","みどりのひは 5がつ4かです。／Ngày Màu xanh là mùng 4 tháng 5.","4/5"],["こどものひ","こどもの日","n","Ngày Trẻ em","Children's Day","こどものひに こいのぼりを かざります。／Ngày Trẻ em người ta treo cờ cá chép.","5/5"],["うみのひ","海の日","n","Ngày Biển","Marine Day","うみのひに うみへ いきました。／Ngày Biển tôi đã đi biển.","Thứ Hai tuần 3 tháng 7"],["けいろうのひ","敬老の日","n","Ngày Kính lão","Respect for the Aged Day","けいろうのひに そふに でんわしました。／Ngày Kính lão tôi gọi điện cho ông.","Thứ Hai tuần 3 tháng 9"],["しゅうぶんのひ","秋分の日","n","Ngày Thu phân","Autumnal Equinox Day","しゅうぶんのひは やすみです。／Ngày Thu phân được nghỉ.","Khoảng 23/9"],["たいいくのひ","体育の日","n","Ngày Thể thao","Health and Sports Day","たいいくのひに うんどうかいが あります。／Ngày Thể thao có hội thao.","Thứ Hai tuần 2 tháng 10 (nay gọi là スポーツの日)"],["ぶんかのひ","文化の日","n","Ngày Văn hóa","Culture Day","ぶんかのひは 11がつ3かです。／Ngày Văn hóa là mùng 3 tháng 11.","3/11"],["きんろうかんしゃのひ","勤労感謝の日","n","Ngày Cảm tạ lao động","Labor Thanksgiving Day","きんろうかんしゃのひは 11がつ23にちです。／Ngày Cảm tạ lao động là 23 tháng 11.","23/11"],["てんのうたんじょうび","天皇誕生日","n","Sinh nhật Thiên hoàng","Emperor's Birthday","てんのうたんじょうびは やすみです。／Sinh nhật Thiên hoàng là ngày nghỉ.","Theo sách là 23/12 (từ 2020 là 23/2)"],["ゴールデンウィーク","","n","Tuần lễ vàng","Golden Week","ゴールデンウィークに ほっかいどうへ いきます。／Tuần lễ vàng tôi đi Hokkaidō.","Khoảng 29/4 – 5/5"],["ふりかえきゅうじつ","振替休日","n","Ngày nghỉ bù","substitute holiday","しゅくじつが にちようびなら、げつようびが ふりかえきゅうじつです。／Nếu ngày lễ rơi vào Chủ nhật thì thứ Hai được nghỉ bù.",""]],"refTitle":"Ngày nghỉ quốc gia","grammar":[{"title":"Nơi chốn へ 行きます／来ます／帰ります","form":"N (nơi chốn) へ いきます／きます／かえります","explain":"Với động từ di chuyển, trợ từ へ (đọc là “e”) chỉ hướng đi đến. いきます: đi; きます: đến (về phía người nói); かえります: về (nhà, nước mình).","examples":[{"s":"きょうとへ いきます。","t":"Tôi đi Kyōto."},{"s":"にほんへ きました。","t":"Tôi đã đến Nhật Bản."},{"s":"うちへ かえります。","t":"Tôi về nhà."}],"tip":"へ đọc là “e”, không đọc “he”."},{"title":"どこ(へ)も 行きません – phủ định hoàn toàn","form":"Từ để hỏi + (trợ từ) + も + V ません","explain":"Thêm も sau từ để hỏi rồi dùng động từ phủ định để phủ định toàn bộ: không đi đâu cả, không ăn gì cả, không ai đến cả.","examples":[{"s":"どこ[へ]も いきません。","t":"Tôi không đi đâu cả."},{"s":"なにも たべません。","t":"Tôi không ăn gì cả."},{"s":"だれも きませんでした。","t":"Không có ai đến cả."}],"tip":""},{"title":"Phương tiện で 行きます – đi bằng gì","form":"N (phương tiện) で いきます／きます／かえります · đi bộ: あるいて","explain":"で sau phương tiện giao thông chỉ cách thức di chuyển: “bằng”. Đi bộ thì nói あるいて, KHÔNG dùng で.","examples":[{"s":"でんしゃで いきます。","t":"Tôi đi bằng tàu điện."},{"s":"タクシーで きました。","t":"Tôi đã đến bằng taxi."},{"s":"えきから あるいて かえりました。","t":"Tôi đã đi bộ từ ga về nhà."}],"tip":"Sai: あるいてで いきます."},{"title":"Người と V – cùng với ai","form":"N (người/động vật) と V · một mình: ひとりで","explain":"と sau người nghĩa là “cùng với” – làm việc gì đó cùng ai. Làm một mình thì nói ひとりで (không dùng と).","examples":[{"s":"かぞくと にほんへ きました。","t":"Tôi đã đến Nhật cùng gia đình."},{"s":"ひとりで とうきょうへ いきます。","t":"Tôi đi Tōkyō một mình."}],"tip":""},{"title":"いつ – khi nào","form":"いつ + V か","explain":"Hỏi thời điểm nói chung. Ngoài なんじ, なんようび, なんがつなんにち (có に), dùng いつ – sau いつ KHÔNG thêm に.","examples":[{"s":"いつ にほんへ きましたか。……3がつ 25にちに きました。","t":"Bạn đến Nhật khi nào? – Tôi đến ngày 25 tháng 3."},{"s":"いつ ひろしまへ いきますか。……らいしゅう いきます。","t":"Khi nào bạn đi Hiroshima? – Tuần sau tôi đi."}],"tip":"Sai: いつに いきますか."},{"title":"～よ – đấy (thông báo)","form":"Câu + よ","explain":"よ đặt cuối câu để nhấn mạnh thông tin mà người nghe chưa biết, hoặc để nêu ý kiến, phán đoán của mình một cách chắc chắn: “… đấy”, “… cơ”.","examples":[{"s":"この でんしゃは こうしえんへ いきますか。……いいえ、いきません。つぎの「ふつう」ですよ。","t":"Tàu này có đi Kōshien không? – Không. Chuyến tàu thường tiếp theo mới đi cơ."},{"s":"ほっかいどうに うまが たくさん いますよ。","t":"Ở Hokkaidō có nhiều ngựa lắm đấy."}],"tip":"Dùng よ nhiều với người trên dễ nghe như dạy đời; ね thì mềm hơn."},{"title":"そうですね – ừ nhỉ","form":"そうですね","explain":"Thể hiện sự đồng tình, đồng cảm với điều người kia nói, khi mình cũng nghĩ thế hoặc cũng biết điều đó. Khác そうですか (Bài 2) – dùng khi tiếp nhận thông tin mới.","examples":[{"s":"あしたは にちようびですね。……あ、そうですね。","t":"Mai là Chủ nhật nhỉ. – À, ừ nhỉ."}],"tip":""}]},{"n":6,"title":"Bài 6","jp":"いっしょに行きませんか","sub":"Ăn uống, sinh hoạt · rủ rê ～ませんか","rows":[["たべます","食べます","v2","Ăn","eat","あさ パンを たべます。／Buổi sáng ăn bánh mì.","Nhóm II · thể từ điển: たべる · tân ngữ dùng を."],["のみます","飲みます","v1","Uống","drink","まいあさ コーヒーを のみます。／Sáng nào cũng uống cà phê.","Nhóm I · thể từ điển: のむ"],["すいます［たばこを～］","吸います","v1","Hút [thuốc]","smoke [a cigarette]","たばこを すいません。／Tôi không hút thuốc.","Nhóm I · thể từ điển: すう"],["みます","見ます","v2","Xem, nhìn","see, look at, watch","ばん テレビを みます。／Buổi tối xem ti vi.","Nhóm II · thể từ điển: みる"],["ききます","聞きます","v1","Nghe","hear, listen","おんがくを ききます。／Nghe nhạc.","Nhóm I · thể từ điển: きく · ở Bài 23 còn nghĩa “hỏi”."],["よみます","読みます","v1","Đọc","read","しんぶんを よみます。／Đọc báo.","Nhóm I · thể từ điển: よむ"],["かきます","書きます","v1","Viết, vẽ","write, draw, paint","てがみを かきます。／Viết thư.","Nhóm I · thể từ điển: かく · vẽ tranh cũng có thể viết 描きます."],["かいます","買います","v1","Mua","buy","デパートで くつを かいました。／Đã mua giày ở bách hoá.","Nhóm I · thể từ điển: かう"],["とります［しゃしんを～］","撮ります","v1","Chụp [ảnh]","take [a photograph]","こうえんで しゃしんを とります。／Chụp ảnh ở công viên.","Nhóm I · thể từ điển: とる"],["します","します","v3","Làm","do","テニスを します。／Chơi quần vợt.","Nhóm III · thể từ điển: する"],["あいます［ともだちに～］","会います","v1","Gặp [bạn]","meet [a friend]","えきで ともだちに あいます。／Gặp bạn ở ga.","Nhóm I · thể từ điển: あう · người gặp dùng に, không dùng を."],["ごはん","ご飯","n","Cơm, bữa ăn","a meal, cooked rice","いっしょに ごはんを たべませんか。／Cùng ăn cơm nhé?",""],["あさごはん","朝ごはん","n","Bữa sáng","breakfast","あさごはんを たべません。／Tôi không ăn sáng.",""],["ひるごはん","昼ごはん","n","Bữa trưa","lunch","しょくどうで ひるごはんを たべます。／Ăn trưa ở nhà ăn.",""],["ばんごはん","晩ごはん","n","Bữa tối","supper","かぞくと ばんごはんを たべます。／Ăn tối cùng gia đình.",""],["パン","","n","Bánh mì","bread","あさ パンを たべます。／Buổi sáng ăn bánh mì.",""],["たまご","卵","n","Trứng","egg","たまごを みっつ かいました。／Đã mua ba quả trứng.",""],["にく","肉","n","Thịt","meat","にくと やさいを たべます。／Ăn thịt và rau.",""],["さかな","魚","n","Cá","fish","さかなが すきです。／Tôi thích cá.",""],["やさい","野菜","n","Rau","vegetable","やさいを たくさん たべます。／Ăn nhiều rau.",""],["くだもの","果物","n","Hoa quả, trái cây","fruit","くだものを かいました。／Đã mua hoa quả.",""],["みず","水","n","Nước","water","みずを ください。／Cho tôi nước.","Nước nóng là おゆ."],["おちゃ","お茶","n","Trà, trà xanh","tea, green tea","おちゃを のみませんか。／Uống trà nhé?",""],["こうちゃ","紅茶","n","Hồng trà, trà đen","black tea","こうちゃに ミルクを いれます。／Cho sữa vào hồng trà.",""],["ぎゅうにゅう（ミルク）","牛乳","n","Sữa bò","milk","まいあさ ぎゅうにゅうを のみます。／Sáng nào cũng uống sữa.",""],["ジュース","","n","Nước hoa quả","juice","オレンジジュースを のみます。／Uống nước cam.",""],["ビール","","n","Bia","beer","ビールを のみましょう。／Uống bia nào.",""],["［お］さけ","［お］酒","n","Rượu, rượu sake","alcohol, Japanese rice wine","おさけは のみません。／Tôi không uống rượu.",""],["ビデオ","","n","Video","video","うちで ビデオを みます。／Xem video ở nhà.",""],["えいが","映画","n","Phim điện ảnh","movie","にちようびに えいがを みます。／Chủ nhật xem phim.",""],["ＣＤ","","n","Đĩa CD","CD, compact disc","CDを ききます。／Nghe đĩa CD.","Đọc シーディー."],["てがみ","手紙","n","Thư","letter","かぞくに てがみを かきます。／Viết thư cho gia đình.",""],["レポート","","n","Báo cáo","report","レポートを かきます。／Viết báo cáo.",""],["しゃしん","写真","n","Ảnh","photograph","しゃしんを とりましょう。／Chụp ảnh nào.",""],["みせ","店","n","Cửa hàng","store, shop","あの みせで かいました。／Đã mua ở cửa hàng kia.",""],["レストラン","","n","Nhà hàng","restaurant","レストランで ばんごはんを たべます。／Ăn tối ở nhà hàng.",""],["にわ","庭","n","Vườn","garden","にわで しゃしんを とります。／Chụp ảnh trong vườn.",""],["しゅくだい","宿題","n","Bài tập về nhà","homework","ばん しゅくだいを します。／Tối làm bài tập.","～をします: làm bài tập."],["テニス","","n","Quần vợt","tennis","ともだちと テニスを します。／Chơi quần vợt với bạn.","～をします: chơi quần vợt."],["サッカー","","n","Bóng đá","soccer, football","こうえんで サッカーを します。／Chơi bóng đá ở công viên.","～をします: chơi bóng đá."],["［お］はなみ","［お］花見","n","Ngắm hoa anh đào","cherry-blossom viewing","4がつに おはなみを します。／Tháng 4 đi ngắm hoa anh đào.","～をします."],["なに","何","q","Cái gì","what","なにを たべますか。／Bạn ăn gì?","Trước を, が dùng なに."],["いっしょに","一緒に","adv","Cùng nhau","together","いっしょに えいがを みませんか。／Cùng xem phim nhé?",""],["ちょっと","","adv","Một chút","a little while, a little bit","ちょっと まって ください。／Đợi một chút.",""],["いつも","","adv","Luôn luôn, thường","always, usually","いつも 7じに おきます。／Tôi luôn dậy lúc 7 giờ.",""],["ときどき","時々","adv","Thỉnh thoảng","sometimes","ときどき レストランで たべます。／Thỉnh thoảng ăn ở nhà hàng.",""],["それから","","cj","Sau đó","after that, and then","しゅくだいを します。それから テレビを みます。／Làm bài tập. Sau đó xem ti vi.",""],["ええ","","it","Vâng (thân mật)","yes","ええ、いいですよ。／Ừ, được thôi.","Mềm hơn はい."],["いいですね","","ex","Hay quá nhỉ, được đấy","That's good.","いっしょに いきませんか。ーいいですね。／Cùng đi nhé? — Hay đấy.","Đồng ý với lời rủ."],["わかりました","分かりました","ex","Tôi hiểu rồi","I see.","はい、わかりました。／Vâng, tôi hiểu rồi.",""],["なんですか","何ですか","ex","Có chuyện gì vậy?","Yes? (when called)","ミラーさん。ーはい、なんですか。／Anh Miller. — Vâng, có chuyện gì ạ?","Đáp lại khi được gọi."],["じゃ、また［あした］","","ex","Hẹn gặp lại [ngày mai]","See you [tomorrow].","じゃ、また あした。／Vậy hẹn mai gặp nhé.",""]],"ref":[["きゅうり","","n","Dưa chuột","cucumber","きゅうりを かいました。／Tôi đã mua dưa chuột.",""],["トマト","","n","Cà chua","tomato","トマトを たべます。／Tôi ăn cà chua.",""],["なす","","n","Cà tím","eggplant","なすは やさいです。／Cà là một loại rau.",""],["まめ","豆","n","Đậu","beans","まめを たべますか。／Bạn có ăn đậu không?",""],["キャベツ","","n","Bắp cải","cabbage","キャベツを かって ください。／Hãy mua bắp cải.",""],["ねぎ","","n","Hành (lá, hành boa-rô)","green onion","ねぎを いれます。／Cho hành vào.",""],["はくさい","白菜","n","Cải thảo, rau cải bẹ trắng","Chinese cabbage","はくさいで なべを つくります。／Tôi nấu lẩu bằng cải thảo.",""],["ほうれんそう","","n","Rau bina, cải bó xôi","spinach","ほうれんそうは からだに いいです。／Rau bina tốt cho cơ thể.",""],["レタス","","n","Rau diếp, xà lách","lettuce","サラダに レタスを いれます。／Cho xà lách vào món salad.",""],["じゃがいも","","n","Khoai tây","potato","じゃがいもと にくを かいます。／Tôi mua khoai tây và thịt.",""],["だいこん","大根","n","Củ cải trắng","daikon radish","だいこんは やすいです。／Củ cải rẻ.",""],["たまねぎ","","n","Củ hành tây","onion","たまねぎを きります。／Tôi thái hành tây.",""],["にんじん","","n","Cà rốt","carrot","にんじんが きらいです。／Tôi ghét cà rốt.",""],["いちご","","n","Dâu tây","strawberry","いちごを かいます。／Tôi mua dâu tây.",""],["もも","","n","Đào","peach","ももは あまいです。／Quả đào ngọt.",""],["すいか","","n","Dưa hấu","watermelon","なつは すいかを たべます。／Mùa hè tôi ăn dưa hấu.",""],["ぶどう","","n","Nho","grapes","ぶどうを たべます。／Tôi ăn nho.",""],["なし","","n","Lê","Japanese pear","なしを かいました。／Tôi đã mua lê.",""],["かき","","n","Hồng (quả)","persimmon","あきは かきが おいしいです。／Mùa thu quả hồng ngon.",""],["バナナ","","n","Chuối","banana","バナナを たべます。／Tôi ăn chuối.",""],["ぎゅうにく","牛肉","n","Thịt bò","beef","ぎゅうにくを かいます。／Tôi mua thịt bò.",""],["とりにく","とり肉","n","Thịt gà","chicken","とりにくを たべます。／Tôi ăn thịt gà.",""],["ぶたにく","豚肉","n","Thịt lợn","pork","ぶたにくを かいました。／Tôi đã mua thịt lợn.",""],["ソーセージ","","n","Xúc xích","sausage","あさ ソーセージを たべました。／Sáng nay tôi ăn xúc xích.",""],["ハム","","n","Giò, giăm bông","ham","ハムと パンを たべます。／Tôi ăn giăm bông và bánh mì.",""],["こめ","米","n","Gạo","rice (uncooked)","こめを かいます。／Tôi mua gạo.","Gạo là loại ngũ cốc Nhật tự cấp 100%"],["あじ","","n","Cá sòng","horse mackerel","あじを やきます。／Tôi nướng cá sòng.",""],["いわし","","n","Cá trích, cá xác-đin","sardine","いわしを かいます。／Tôi mua cá trích.",""],["さば","","n","Cá thu","mackerel","さばを たべました。／Tôi đã ăn cá thu.",""],["さんま","","n","Cá thu đao","Pacific saury","あきは さんまが おいしいです。／Mùa thu cá thu đao ngon.",""],["さけ","鮭","n","Cá hồi","salmon","さけを やきます。／Tôi nướng cá hồi.","Cùng cách đọc với さけ (rượu sake)"],["まぐろ","","n","Cá ngừ","tuna","まぐろの すしが すきです。／Tôi thích sushi cá ngừ.",""],["たい","","n","Cá tráp","sea bream","たいは たかいです。／Cá tráp đắt.",""],["たら","","n","Cá tuyết","cod","たらを かいます。／Tôi mua cá tuyết.",""],["えび","","n","Tôm","shrimp","えびを たべます。／Tôi ăn tôm.",""],["かに","","n","Cua","crab","かには おいしいです。／Cua ngon.",""],["いか","","n","Mực","squid","いかを たべますか。／Bạn có ăn mực không?",""],["たこ","","n","Bạch tuộc","octopus","たこやきを たべました。／Tôi đã ăn bánh bạch tuộc.",""],["かい","貝","n","Sò, ngao","shellfish","かいを たべません。／Tôi không ăn sò.",""]],"refTitle":"Thức ăn","grammar":[{"title":"N を V – tân ngữ trực tiếp","form":"N を V (ngoại động từ)","explain":"を (đọc “o”) đánh dấu tân ngữ trực tiếp – đối tượng chịu tác động của động từ: ăn cái gì, uống cái gì, đọc cái gì. Chữ を chỉ dùng làm trợ từ.","examples":[{"s":"ジュースを のみます。","t":"Tôi uống nước hoa quả."},{"s":"てがみを かきます。","t":"Tôi viết thư."}],"tip":""},{"title":"N を します – chơi, làm, tổ chức","form":"N を します","explain":"します đi với rất nhiều danh từ làm tân ngữ, nghĩa thay đổi theo danh từ: chơi thể thao/trò chơi (サッカーを します, トランプを します), tổ chức (パーティーを します, かいぎを します), làm (しゅくだいを します, しごとを します), gọi điện (でんわを します).","examples":[{"s":"サッカーを します。","t":"Tôi chơi bóng đá."},{"s":"パーティーを します。","t":"Tôi tổ chức tiệc."},{"s":"しゅくだいを します。","t":"Tôi làm bài tập."}],"tip":""},{"title":"何を しますか – làm gì","form":"(thời gian) なにを しますか","explain":"Hỏi người nghe làm gì (vào lúc nào đó).","examples":[{"s":"げつようび なにを しますか。……きょうとへ いきます。","t":"Thứ Hai bạn làm gì? – Tôi đi Kyōto."},{"s":"きのう なにを しましたか。……サッカーを しました。","t":"Hôm qua bạn đã làm gì? – Tôi đã chơi bóng đá."}],"tip":""},{"title":"なん và なに","form":"なん + (từ bắt đầu hàng た/だ/な, trợ số từ) · なに (các trường hợp khác)","explain":"Cùng nghĩa “cái gì”. Dùng なん khi đứng trước từ bắt đầu bằng hàng た, だ, な (なんですか, なんの, なんと) và trước trợ số từ (なんさい, なんじ). Các trường hợp còn lại dùng なに (なにを, なにが).\n\nなんで vừa hỏi “bằng gì” vừa hỏi “tại sao”; muốn rõ nghĩa “bằng phương tiện gì” có thể nói なにで.","examples":[{"s":"それは なんですか。","t":"Đó là cái gì?"},{"s":"テレーザちゃんは なんさいですか。","t":"Bé Teresa mấy tuổi?"},{"s":"なにを かいますか。","t":"Bạn mua gì?"},{"s":"なにで とうきょうへ いきますか。……しんかんせんで いきます。","t":"Bạn đi Tōkyō bằng gì? – Tôi đi bằng Shinkansen."}],"tip":""},{"title":"Nơi chốn で V – nơi diễn ra hành động","form":"N (nơi chốn) で V","explain":"で sau địa điểm chỉ nơi xảy ra hành động: “ở, tại”.","examples":[{"s":"えきで しんぶんを かいます。","t":"Tôi mua báo ở ga."},{"s":"としょかんで べんきょうします。","t":"Tôi học ở thư viện."}],"tip":"Nơi hành động diễn ra dùng で; nơi tồn tại (あります/います) dùng に (Bài 10)."},{"title":"V ませんか – mời rủ","form":"いっしょに V ませんか","explain":"Dùng để mời, rủ người nghe làm gì: “anh/chị có… cùng tôi không?”. Mang tính tôn trọng ý muốn của người nghe hơn ～ましょう.","examples":[{"s":"いっしょに きょうとへ いきませんか。……ええ、いいですね。","t":"Bạn có đi Kyōto cùng tôi không? – Vâng, hay quá."}],"tip":""},{"title":"V ましょう – cùng… nào","form":"V ましょう","explain":"Rủ người nghe cùng làm một cách tích cực, hoặc đáp lại lời mời một cách hưởng ứng: “chúng ta cùng… nào”.","examples":[{"s":"ちょっと やすみましょう。","t":"Chúng ta nghỉ một lát đi."},{"s":"いっしょに ひるごはんを たべませんか。……ええ、たべましょう。","t":"Ăn trưa cùng tôi không? – Được, cùng ăn nhé."}],"tip":""},{"title":"～か – à, thế à","form":"N ですか (xuống giọng)","explain":"Khi tiếp nhận thông tin mới, nhắc lại và thêm か (xuống giọng) để tỏ ý “à, ra vậy” – giống そうですか.","examples":[{"s":"にちようび きょうとへ いきました。……きょうとですか。いいですね。","t":"Chủ nhật tôi đi Kyōto. – Kyōto à? Hay quá nhỉ."}],"tip":""},{"title":"Phó từ tần suất – いつも・よく・ときどき・あまり・ぜんぜん · bổ sung N5","form":"いつも／よく／ときどき + V · あまり／ぜんぜん + V ません","explain":"Diễn tả mức độ thường xuyên, xếp từ nhiều đến ít: いつも (luôn luôn), よく (thường), ときどき (thỉnh thoảng), あまり～ません (ít khi), ぜんぜん～ません (không bao giờ). ほとんど～ません: hầu như không.","examples":[{"s":"いつも 7じに おきます。","t":"Tôi luôn dậy lúc 7 giờ."},{"s":"ときどき としょかんで べんきょうします。","t":"Thỉnh thoảng tôi học ở thư viện."},{"s":"おさけは ほとんど のみません。","t":"Tôi hầu như không uống rượu."}],"tip":""}]},{"n":7,"title":"Bài 7","jp":"ごめんください","sub":"Cho – nhận · dụng cụ で · gia đình","rows":[["きります","切ります","v1","Cắt","cut, slice","はさみで かみを きります。／Cắt giấy bằng kéo.","Nhóm I · thể từ điển: きる · dụng cụ dùng で."],["おくります","送ります","v1","Gửi","send","くにの かぞくに てがみを おくります。／Gửi thư cho gia đình ở quê.","Nhóm I · thể từ điển: おくる"],["あげます","あげます","v2","Cho, tặng","give","ともだちに プレゼントを あげます。／Tặng quà cho bạn.","Nhóm II · thể từ điển: あげる · người nhận dùng に."],["もらいます","もらいます","v1","Nhận","receive","ともだちに はなを もらいました。／Đã nhận hoa từ bạn.","Nhóm I · thể từ điển: もらう · người cho dùng に hoặc から."],["かします","貸します","v1","Cho mượn","lend","ともだちに かさを かしました。／Đã cho bạn mượn ô.","Nhóm I · thể từ điển: かす"],["かります","借ります","v2","Mượn","borrow","としょかんで ほんを かります。／Mượn sách ở thư viện.","Nhóm II · thể từ điển: かりる"],["おしえます","教えます","v2","Dạy","teach","わたしは にほんごを おしえます。／Tôi dạy tiếng Nhật.","Nhóm II · thể từ điển: おしえる"],["ならいます","習います","v1","Học (từ ai đó)","learn","せんせいに にほんごを ならいます。／Học tiếng Nhật từ thầy giáo.","Nhóm I · thể từ điển: ならう · khác べんきょうします: có người dạy."],["かけます［でんわを～］","かけます","v2","Gọi [điện thoại]","make [a telephone call]","ははに でんわを かけます。／Gọi điện cho mẹ.","Nhóm II · thể từ điển: かける"],["て","手","n","Tay","hand, arm","てを あらいます。／Rửa tay.",""],["はし","箸","n","Đũa","chopsticks","はしで ごはんを たべます。／Ăn cơm bằng đũa.","Đồng âm với はし (cầu, Bài 23) nhưng khác ngữ điệu."],["スプーン","","n","Thìa","spoon","スプーンで カレーを たべます。／Ăn cà ri bằng thìa.",""],["ナイフ","","n","Dao","knife","ナイフで パンを きります。／Cắt bánh mì bằng dao.",""],["フォーク","","n","Dĩa, nĩa","fork","フォークで たべます。／Ăn bằng nĩa.",""],["はさみ","","n","Cái kéo","scissors","はさみを かして ください。／Cho tôi mượn kéo.",""],["ファクス","","n","Máy fax","fax","ファクスで しりょうを おくります。／Gửi tài liệu bằng fax.",""],["ワープロ","","n","Máy đánh chữ","word processor","ワープロで てがみを かきます。／Viết thư bằng máy đánh chữ.",""],["パソコン","","n","Máy tính cá nhân","personal computer","パソコンで レポートを かきます。／Viết báo cáo bằng máy tính.",""],["パンチ","","n","Cái đục lỗ","punch","パンチで あなを あけます。／Đục lỗ bằng cái đục lỗ.",""],["ホッチキス","","n","Cái dập ghim","stapler","ホッチキスで とめます。／Dập ghim lại.",""],["セロテープ","","n","Băng dính trong","clear adhesive tape","セロテープで はります。／Dán bằng băng dính.",""],["けしゴム","消しゴム","n","Cục tẩy","eraser","けしゴムを かして ください。／Cho tôi mượn cục tẩy.",""],["かみ","紙","n","Giấy","paper","かみを 1まい ください。／Cho tôi một tờ giấy.","Đồng âm với かみ (tóc, Bài 16)."],["はな","花","n","Hoa","flower, blossom","ははに はなを あげました。／Đã tặng hoa cho mẹ.","Đồng âm với はな (mũi)."],["シャツ","","n","Áo sơ mi","shirt","あたらしい シャツを かいました。／Đã mua áo sơ mi mới.",""],["プレゼント","","n","Quà tặng","present, gift","たんじょうびの プレゼントです。／Đây là quà sinh nhật.",""],["にもつ","荷物","n","Hành lý, đồ đạc","baggage, parcel","にもつを おくります。／Gửi hành lý.",""],["おかね","お金","n","Tiền","money","ちちに おかねを もらいました。／Đã nhận tiền từ bố.",""],["きっぷ","切符","n","Vé (tàu, xe)","ticket","えきで きっぷを かいます。／Mua vé ở ga.",""],["クリスマス","","n","Giáng sinh","Christmas","クリスマスに プレゼントを あげます。／Tặng quà vào Giáng sinh.",""],["ちち","父","n","Bố (mình)","(my) father","ちちは ぎんこういんです。／Bố tôi là nhân viên ngân hàng.","Nói về bố mình với người khác."],["はは","母","n","Mẹ (mình)","(my) mother","ははに でんわを かけます。／Gọi điện cho mẹ.",""],["おとうさん","お父さん","n","Bố (người khác)","(someone else's) father","おとうさんは おげんきですか。／Bố bạn có khoẻ không?","Trong gia đình con cũng gọi bố là おとうさん."],["おかあさん","お母さん","n","Mẹ (người khác)","(someone else's) mother","おかあさんは なんさいですか。／Mẹ bạn bao nhiêu tuổi?",""],["もう","","adv","Đã, rồi","already","もう ひるごはんを たべましたか。／Bạn đã ăn trưa chưa?",""],["まだ","","adv","Chưa","not yet","いいえ、まだです。／Chưa, vẫn chưa.",""],["これから","","adv","Từ bây giờ, sắp","from now on, soon","これから たべます。／Bây giờ tôi ăn đây.",""],["［～、］すてきですね","［～、］素敵ですね","ex","[~] đẹp quá nhỉ","What a nice [~]!","その シャツ、すてきですね。／Cái áo đó đẹp quá nhỉ.",""],["ごめんください","","ex","Xin lỗi, có ai ở nhà không?","Excuse me. / Anybody home?","ごめんください。ーいらっしゃい。／Có ai ở nhà không ạ? — Mời vào.","Khách nói ở cửa khi đến thăm nhà."],["いらっしゃい","","ex","Mời vào, chào mừng","How nice of you to come.","いらっしゃい。どうぞ。／Chào mừng, mời vào.",""],["どうぞおあがりください","どうぞお上がりください","ex","Mời anh/chị vào nhà","Do come in.","どうぞ おあがり ください。／Mời anh vào nhà.","Nhà Nhật có bậc thềm nên dùng “lên” (上がる)."],["しつれいします","失礼します","ex","Xin phép (vào / về)","Thank you. / May I? (lit. I will be disturbing you)","しつれいします。／Tôi xin phép ạ.","Nói khi vào phòng, vào nhà người khác hoặc khi về."],["［～は］いかがですか","","ex","[~] thì sao ạ? (mời)","Would you like [~]?","コーヒーは いかがですか。／Anh dùng cà phê nhé?","Lịch sự hơn どうですか."],["いただきます","","ex","Mời cả nhà (nói trước khi ăn)","I accept. (said before eating)","いただきます。／Con xin phép ăn ạ.","Nói trước khi ăn hoặc khi nhận đồ ăn."],["りょこう","旅行","n","Du lịch, chuyến đi","trip, tour","らいげつ りょこうします。／Tháng sau tôi đi du lịch.","～します: đi du lịch."],["おみやげ","お土産","n","Quà lưu niệm","souvenir, present","きょうとの おみやげです。／Đây là quà Kyoto.","Quà mang về sau chuyến đi."]],"ref":[["そぼ","祖母","n","Bà (của mình)","(my) grandmother","そぼは 80さいです。／Bà tôi 80 tuổi.","Gọi bà người khác: おばあさん"],["そふ","祖父","n","Ông (của mình)","(my) grandfather","そふは げんきです。／Ông tôi khỏe.","Gọi ông người khác: おじいさん"],["そふぼ","祖父母","n","Ông bà","grandparents","そふぼは いなかに すんで います。／Ông bà tôi sống ở quê.",""],["ふうふ","夫婦","n","Vợ chồng","married couple","あの ふうふは なかが いいです。／Đôi vợ chồng kia rất hòa thuận.","Của người khác: ご夫婦"],["つま","妻","n","Vợ (của mình)","(my) wife","つまに はなを あげました。／Tôi đã tặng hoa cho vợ.","Vợ người khác: 奥さん"],["おっと","夫","n","Chồng (của mình)","(my) husband","おっとは かいしゃいんです。／Chồng tôi là nhân viên công ty.","Chồng người khác: ご主人"],["むすめ","娘","n","Con gái (của mình)","(my) daughter","むすめは 5さいです。／Con gái tôi 5 tuổi.","Của người khác: 娘さん"],["むすこ","息子","n","Con trai (của mình)","(my) son","むすこは だいがくせいです。／Con trai tôi là sinh viên.","Của người khác: 息子さん"],["こども","子ども","n","Con cái, trẻ con","child","こどもが ふたり います。／Tôi có hai con.","Của người khác: お子さん"],["ごりょうしん","ご両親","n","Bố mẹ (người khác)","(someone's) parents","ごりょうしんは おげんきですか。／Bố mẹ bạn có khỏe không?",""],["ごきょうだい","ご兄弟","n","Anh chị em (người khác)","(someone's) siblings","ごきょうだいは なんにんですか。／Bạn có mấy anh chị em?",""],["ごふうふ","ご夫婦","n","Vợ chồng (người khác)","(someone's) married couple","たなかさんごふうふは しんせつです。／Vợ chồng anh Tanaka tốt bụng.",""],["むすめさん","娘さん","n","Con gái (người khác)","(someone's) daughter","むすめさんは おいくつですか。／Con gái anh bao nhiêu tuổi?",""],["むすこさん","息子さん","n","Con trai (người khác)","(someone's) son","むすこさんは なんさいですか。／Con trai chị mấy tuổi?",""],["おこさん","お子さん","n","Con (người khác)","(someone's) child","おこさんは なんにんですか。／Anh có mấy cháu?",""]],"refTitle":"Gia đình","grammar":[{"title":"Công cụ で V – bằng","form":"N (công cụ, phương tiện, ngôn ngữ) で V","explain":"で chỉ dụng cụ, phương tiện, cách thức để làm việc gì: ăn bằng đũa, viết bằng tiếng Nhật.","examples":[{"s":"はしで たべます。","t":"Tôi ăn bằng đũa."},{"s":"にほんごで レポートを かきます。","t":"Tôi viết báo cáo bằng tiếng Nhật."}],"tip":""},{"title":"「Từ/Câu」は ～語で 何ですか – nói thế nào","form":"「X」は ～ごで なんですか","explain":"Hỏi một từ, một câu nói bằng ngôn ngữ khác là gì.","examples":[{"s":"「ありがとう」は えいごで なんですか。……「Thank you」です。","t":"“Arigatō” tiếng Anh nói thế nào? – Là “Thank you”."},{"s":"「Thank you」は にほんごで なんですか。……「ありがとう」です。","t":"“Thank you” tiếng Nhật là gì? – Là “arigatō”."}],"tip":""},{"title":"Người に N を あげます – cho, tặng","form":"N1 (người nhận) に N2 を あげます／かします／おしえます","explain":"Các động từ cho đi đồ vật, thông tin (あげます: tặng, かします: cho mượn, おしえます: dạy) cần người nhận; người nhận đánh dấu bằng に.","examples":[{"s":"きむらさんに はなを あげました。","t":"Tôi đã tặng hoa cho chị Kimura."},{"s":"イーさんに ほんを かしました。","t":"Tôi cho chị Lee mượn sách."},{"s":"やまださんに えいごを おしえます。","t":"Tôi dạy tiếng Anh cho ông Yamada."}],"tip":"あげます không dùng khi người khác cho MÌNH (dùng くれます – Bài 24)."},{"title":"Người に N を もらいます – nhận","form":"N1 (người cho) に／から N2 を もらいます／かります／ならいます","explain":"Các động từ nhận (もらいます: nhận, かります: mượn, ならいます: học) dùng に hoặc から sau người đưa. Nếu bên đưa là tổ chức (công ty, trường, ngân hàng) thì chỉ dùng から.","examples":[{"s":"やまださんに はなを もらいました。","t":"Tôi đã nhận hoa từ ông Yamada."},{"s":"カリナさんに CDを かりました。","t":"Tôi mượn đĩa CD của chị Karina."},{"s":"ぎんこうから おかねを かりました。","t":"Tôi vay tiền ngân hàng."}],"tip":""},{"title":"もう V ました – đã… rồi","form":"もう V ました · trả lời phủ định: いいえ、まだです","explain":"もう nghĩa là “đã, rồi”, đi với quá khứ để nói việc đã xong tại thời điểm hiện tại. Khi chưa làm, trả lời いいえ、まだです (hoặc まだ V ていません – Bài 31), KHÔNG dùng V ませんでした (vì nghĩa là đã không làm).","examples":[{"s":"もう にもつを おくりましたか。……はい、もう おくりました。","t":"Bạn gửi đồ chưa? – Rồi, tôi gửi rồi."},{"s":"……いいえ、まだです。","t":"– Chưa, vẫn chưa."}],"tip":"Sai: いいえ、おくりませんでした (khi ý là “chưa gửi”)."},{"title":"Lược bỏ trợ từ trong hội thoại","form":"N (は／を) …","explain":"Trong hội thoại thân mật, khi quan hệ giữa các thành phần đã rõ, trợ từ は, を thường được lược đi.","examples":[{"s":"この スプーン[は]、すてきですね。","t":"Cái thìa này đẹp nhỉ."},{"s":"コーヒー[を]、もう いっぱい いかがですか。","t":"Anh dùng thêm một cốc cà phê nhé?"}],"tip":""}]},{"n":8,"title":"Bài 8","jp":"そろそろ失礼します","sub":"Tính từ い / な · thăm nhà người Nhật","rows":[["ハンサム［な］","","ana","Đẹp trai","handsome","かれは ハンサムです。／Anh ấy đẹp trai.","Tính từ đuôi な."],["きれい［な］","","ana","Đẹp; sạch","beautiful, clean","この へやは きれいです。／Căn phòng này sạch đẹp.","Tính từ đuôi な dù kết thúc bằng い. Phủ định: きれいじゃありません."],["しずか［な］","静か［な］","ana","Yên tĩnh","quiet","としょかんは しずかです。／Thư viện yên tĩnh.","Tính từ đuôi な."],["にぎやか［な］","賑やか［な］","ana","Náo nhiệt","lively","この まちは にぎやかです。／Thị trấn này náo nhiệt.","Tính từ đuôi な."],["ゆうめい［な］","有名［な］","ana","Nổi tiếng","famous","ふじさんは ゆうめいな やまです。／Núi Phú Sĩ là ngọn núi nổi tiếng.","Tính từ đuôi な."],["しんせつ［な］","親切［な］","ana","Tốt bụng, tử tế","kind","せんせいは しんせつです。／Thầy giáo tốt bụng.","Tính từ đuôi な; không dùng cho người nhà mình."],["げんき［な］","元気［な］","ana","Khoẻ, khoẻ khoắn","healthy, sound, cheerful","そふは げんきです。／Ông tôi vẫn khoẻ.","Tính từ đuôi な."],["ひま［な］","暇［な］","ana","Rảnh rỗi","free (time)","あしたは ひまです。／Ngày mai tôi rảnh.","Tính từ đuôi な."],["べんり［な］","便利［な］","ana","Tiện lợi","convenient","この パソコンは べんりです。／Máy tính này tiện lợi.","Tính từ đuôi な."],["すてき［な］","素敵［な］","ana","Đẹp, tuyệt vời","fine, nice, wonderful","すてきな ふくですね。／Bộ quần áo đẹp quá nhỉ.","Tính từ đuôi な."],["おおきい","大きい","ai","To, lớn","big, large","おおきい いえですね。／Nhà to nhỉ.","Tính từ đuôi い."],["ちいさい","小さい","ai","Nhỏ, bé","small, little","ちいさい かばんです。／Là cái túi nhỏ.","Tính từ đuôi い."],["あたらしい","新しい","ai","Mới","new","あたらしい くるまを かいました。／Đã mua xe mới.","Tính từ đuôi い."],["ふるい","古い","ai","Cũ","old (not of age)","この たてものは ふるいです。／Toà nhà này cũ.","Không dùng cho tuổi người (người già: としを とった)."],["いい（よい）","良い","ai","Tốt","good","いい てんきですね。／Trời đẹp nhỉ.","Phủ định: よくないです (không nói いくない)."],["わるい","悪い","ai","Xấu, tồi","bad","てんきが わるいです。／Thời tiết xấu.","Tính từ đuôi い."],["あつい","暑い／熱い","ai","Nóng","hot","きょうは あついですね。／Hôm nay nóng nhỉ.","暑い: trời nóng · 熱い: đồ vật nóng. (厚い là “dày”, đồng âm.)"],["さむい","寒い","ai","Lạnh (thời tiết)","cold (temperature)","ふゆは さむいです。／Mùa đông lạnh.","Lạnh khi chạm, uống dùng つめたい."],["つめたい","冷たい","ai","Lạnh, buốt (khi chạm)","cold (to the touch)","つめたい みずを ください。／Cho tôi nước lạnh.",""],["むずかしい","難しい","ai","Khó","difficult","かんじは むずかしいです。／Chữ Hán khó.",""],["やさしい","易しい","ai","Dễ","easy","この しゅくだいは やさしいです。／Bài tập này dễ.","Nghĩa “hiền” viết 優しい."],["たかい","高い","ai","Đắt; cao","expensive, tall, high","この とけいは たかいです。／Đồng hồ này đắt.","Trái nghĩa: やすい (rẻ), ひくい (thấp)."],["やすい","安い","ai","Rẻ","inexpensive","この みせは やすいです。／Cửa hàng này rẻ.",""],["ひくい","低い","ai","Thấp","low","この いすは ひくいです。／Cái ghế này thấp.",""],["おもしろい","面白い","ai","Thú vị, hay","interesting","この ほんは おもしろいです。／Quyển sách này hay.",""],["おいしい","美味しい","ai","Ngon","delicious, tasty","この ラーメンは おいしいです。／Mì ramen này ngon.",""],["いそがしい","忙しい","ai","Bận","busy","しごとが いそがしいです。／Công việc bận.",""],["たのしい","楽しい","ai","Vui","enjoyable","りょこうは たのしかったです。／Chuyến du lịch rất vui.",""],["しろい","白い","ai","Trắng","white","しろい シャツを かいました。／Đã mua áo sơ mi trắng.",""],["くろい","黒い","ai","Đen","black","くろい かばんは わたしのです。／Cái túi đen là của tôi.",""],["あかい","赤い","ai","Đỏ","red","あかい はなが すきです。／Thích hoa màu đỏ.",""],["あおい","青い","ai","Xanh dương","blue","そらが あおいです。／Bầu trời xanh.","Đèn giao thông xanh cũng gọi là あお."],["さくら","桜","n","Hoa anh đào","cherry (blossom)","さくらが きれいです。／Hoa anh đào đẹp.",""],["やま","山","n","Núi","mountain","ふじさんは たかい やまです。／Phú Sĩ là ngọn núi cao.",""],["まち","町","n","Thị trấn, thành phố","town, city","しずかな まちです。／Là thị trấn yên tĩnh.",""],["たべもの","食べ物","n","Đồ ăn","food","にほんの たべものは おいしいです。／Đồ ăn Nhật ngon.",""],["くるま","車","n","Xe ô tô","car, vehicle","あたらしい くるまですね。／Xe mới nhỉ.",""],["ところ","所","n","Nơi, chỗ","place","ここは いい ところですね。／Đây là nơi đẹp nhỉ.",""],["りょう","寮","n","Ký túc xá","dormitory","わたしは りょうに すんでいます。／Tôi sống ở ký túc xá.",""],["べんきょう","勉強","n","Việc học","study","べんきょうは どうですか。／Việc học thế nào?",""],["せいかつ","生活","n","Cuộc sống, sinh hoạt","life","にほんの せいかつは たのしいです。／Cuộc sống ở Nhật vui.",""],["［お］しごと","［お］仕事","n","Công việc","work, business","おしごとは どうですか。／Công việc của anh thế nào?","しごとを します: làm việc."],["どう","","q","Thế nào","how","にほんの せいかつは どうですか。／Cuộc sống ở Nhật thế nào?",""],["どんな～","","q","~ như thế nào","what kind of ~","どんな まちですか。／Là thị trấn như thế nào?","Luôn đi kèm danh từ."],["どれ","","q","Cái nào (trong 3 thứ trở lên)","which one (of three or more)","あなたの かさは どれですか。／Ô của bạn là cái nào?","Chọn trong hai thứ: どちら."],["とても","","adv","Rất","very","とても おいしいです。／Rất ngon.","Dùng với câu khẳng định."],["あまり","","adv","Không… lắm","not so (with negatives)","あまり さむくないです。／Không lạnh lắm.","Luôn đi với phủ định."],["そして","","cj","Và, thêm nữa","and (connecting sentences)","この へやは ひろいです。そして あかるいです。／Phòng này rộng. Và sáng nữa.","Nối hai câu cùng chiều."],["～が、～","","cj","~ nhưng ~","~, but ~","にほんごは むずかしいですが、おもしろいです。／Tiếng Nhật khó nhưng thú vị.",""],["おげんきですか","お元気ですか","ex","Bạn có khoẻ không?","How are you?","おひさしぶりです。おげんきですか。／Lâu rồi không gặp. Bạn khoẻ không?","Dùng khi lâu ngày gặp lại."],["そうですね","","ex","Để xem nào…","Well, let me see. (pausing)","にほんの せいかつは どうですか。ーそうですね…たのしいです。／Cuộc sống ở Nhật thế nào? — Để xem… vui ạ.","Ngập ngừng suy nghĩ trước khi trả lời."],["にほんのせいかつになれましたか","日本の生活に慣れましたか","ex","Bạn đã quen với cuộc sống ở Nhật chưa?","Have you got used to life in Japan?","ーええ、もう なれました。／Vâng, quen rồi ạ.",""],["［～、］もういっぱいいかがですか","［～、］もう一杯いかがですか","ex","Thêm một chén/ly [~] nữa nhé?","Won't you have another cup of [~]?","おちゃ、もう いっぱい いかがですか。／Thêm một chén trà nữa nhé?",""],["いいえ、けっこうです","","ex","Không, cảm ơn (đủ rồi)","No, thank you.","もう いっぱい いかがですか。ーいいえ、けっこうです。／Thêm ly nữa nhé? — Thôi, đủ rồi ạ.","Từ chối lịch sự khi được mời thêm."],["もう～です［ね］","","ex","Đã ~ rồi [nhỉ]","It's already ~ [, isn't it?]","もう 9じですね。／Đã 9 giờ rồi nhỉ.",""],["そろそろしつれいします","そろそろ失礼します","ex","Đã đến lúc tôi phải về rồi","It's almost time to leave now.","あ、もう 9じですね。そろそろ しつれいします。／Ồ, 9 giờ rồi. Tôi xin phép về.",""],["またいらっしゃってください","","ex","Lần sau lại đến chơi nhé","Please come again.","また いらっしゃって ください。／Lần sau lại đến chơi nhé.","Chủ nhà nói khi tiễn khách."]],"ref":[["いろ","色","n","Màu, màu sắc","color","どんな いろが すきですか。／Bạn thích màu gì?",""],["しろ","白","n","Màu trắng","white","しろの シャツを かいました。／Tôi đã mua áo sơ mi màu trắng.","Tính từ: 白い"],["くろ","黒","n","Màu đen","black","くろが すきです。／Tôi thích màu đen.","Tính từ: 黒い"],["あか","赤","n","Màu đỏ","red","あかの ペンで かいて ください。／Hãy viết bằng bút đỏ.","Tính từ: 赤い"],["あお","青","n","Màu xanh da trời","blue","あおの セーターを かいます。／Tôi mua áo len màu xanh.","Tính từ: 青い · người Nhật cũng gọi đèn xanh giao thông là 青"],["むらさき","紫","n","Màu tím","purple","むらさきの はなです。／Đây là bông hoa màu tím.","Không có dạng tính từ い"],["きいろ","黄色","n","Màu vàng","yellow","きいろの かさです。／Cái ô màu vàng.","Tính từ: 黄色い"],["きいろい","黄色い","ai","Vàng","yellow","きいろい バナナを かいました。／Tôi mua chuối vàng.",""],["ちゃいろ","茶色","n","Màu nâu","brown","ちゃいろの くつを はきます。／Tôi đi giày màu nâu.","Tính từ: 茶色い"],["ちゃいろい","茶色い","ai","Nâu","brown","ちゃいろい いぬが います。／Có một con chó màu nâu.",""],["ピンク","","n","Màu hồng","pink","ピンクの スカートが かわいいです。／Chiếc váy màu hồng dễ thương.","Dùng ピンクの + danh từ"],["オレンジ","","n","Màu da cam","orange","オレンジの Tシャツです。／Áo phông màu cam.",""],["グレー","","n","Màu xám","gray","グレーの スーツを きます。／Tôi mặc bộ vest màu xám.",""],["ベージュ","","n","Màu be","beige","ベージュの コートです。／Áo khoác màu be.",""],["にがい","苦い","ai","Đắng","bitter","くすりは にがいです。／Thuốc đắng.",""],["しおからい","塩辛い","ai","Mặn","salty","この スープは しおからいです。／Món súp này mặn.",""],["すっぱい","酸っぱい","ai","Chua","sour","レモンは すっぱいです。／Chanh chua.",""],["こい","濃い","ai","Đậm, đặc","strong, thick","この コーヒーは こいです。／Cà phê này đậm.",""],["うすい","薄い","ai","Nhạt, loãng","weak, light","みそしるが うすいです。／Súp miso nhạt.","Còn nghĩa: mỏng"]],"refTitle":"Màu & vị","grammar":[{"title":"Tính từ đuôi い và đuôi な","form":"Tính từ い: たかい、おいしい… · Tính từ な: しんせつ[な]、しずか[な]…","explain":"Tiếng Nhật có hai loại tính từ, chia khác nhau: tính từ đuôi い (kết thúc bằng い: たかい, あたらしい) và tính từ đuôi な (cần な khi đứng trước danh từ: しずかな まち). Tính từ có thể làm vị ngữ (N は Adj です) hoặc bổ nghĩa cho danh từ.","examples":[{"s":"ふじさんは たかいです。","t":"Núi Phú Sĩ cao."},{"s":"ワットせんせいは しんせつです。","t":"Thầy Watt tốt bụng."}],"tip":"きれい và ゆうめい là tính từ な dù kết thúc bằng âm い."},{"title":"N は Adj です – câu tính từ & phủ định","form":"N は Adjな(bỏ な) です／じゃ ありません · N は Adjい です／Adj(bỏ い) くないです","explain":"Câu khẳng định: tính từ な bỏ な rồi thêm です; tính từ い giữ nguyên い + です.\n\nPhủ định: tính từ な → ～じゃ（では）ありません; tính từ い → bỏ い thêm くないです. Đặc biệt: いい → よくないです.\n\nCâu hỏi thêm か; trả lời bằng chính tính từ, không dùng そうです/ちがいます.","examples":[{"s":"あそこは しずかじゃ ありません。","t":"Chỗ kia không yên tĩnh."},{"s":"この ほんは おもしろくないです。","t":"Quyển sách này không hay."},{"s":"ペキンは さむいですか。……はい、さむいです。","t":"Bắc Kinh có lạnh không? – Có, lạnh."},{"s":"ならこうえんは にぎやかですか。……いいえ、にぎやかじゃ ありません。","t":"Công viên Nara có náo nhiệt không? – Không, không náo nhiệt."}],"tip":"Sai: いくないです. Đúng: よくないです."},{"title":"Adj + N – tính từ bổ nghĩa danh từ","form":"Adjな な + N · Adjい + N","explain":"Tính từ đứng trước danh từ để bổ nghĩa. Tính từ な phải giữ な; tính từ い giữ nguyên.","examples":[{"s":"ワットせんせいは しんせつな せんせいです。","t":"Thầy Watt là thầy giáo tốt bụng."},{"s":"ふじさんは たかい やまです。","t":"Núi Phú Sĩ là núi cao."}],"tip":"Sai: しずか まち / たかいな やま."},{"title":"～が、～ – nhưng","form":"Câu 1 が、Câu 2","explain":"が nối hai mệnh đề trái ngược nhau: “… nhưng …”. Trong câu tính từ cùng chủ ngữ, nếu vế trước khen thì vế sau chê (và ngược lại).","examples":[{"s":"にほんの たべものは おいしいですが、たかいです。","t":"Đồ ăn Nhật ngon nhưng đắt."},{"s":"しごとは いそがしいですが、おもしろいです。","t":"Công việc bận nhưng thú vị."}],"tip":""},{"title":"とても／あまり – rất / không… lắm","form":"とても + Adj (khẳng định) · あまり + Adj (phủ định)","explain":"Phó từ chỉ mức độ, đặt trước tính từ. とても = rất, đi với câu khẳng định. あまり = không… lắm, chỉ đi với câu phủ định.","examples":[{"s":"ペキンは とても さむいです。","t":"Bắc Kinh rất lạnh."},{"s":"これは とても ゆうめいな えいがです。","t":"Đây là bộ phim rất nổi tiếng."},{"s":"シャンハイは あまり さむくないです。","t":"Thượng Hải không lạnh lắm."}],"tip":"Sai: あまり さむいです."},{"title":"N は どうですか – thế nào","form":"N は どうですか","explain":"Hỏi cảm tưởng, ý kiến, ấn tượng của người nghe về một việc đã trải qua, một nơi đã đến, một người đã gặp.","examples":[{"s":"にほんの せいかつは どうですか。……たのしいです。","t":"Cuộc sống ở Nhật thế nào? – Vui ạ."}],"tip":""},{"title":"N1 は どんな N2 ですか – như thế nào","form":"N1 は どんな N2 ですか","explain":"どんな hỏi tính chất, trạng thái của người hay vật; luôn đi kèm danh từ phía sau.","examples":[{"s":"ならは どんな まちですか。……ふるい まちです。","t":"Nara là thành phố thế nào? – Là thành phố cổ."}],"tip":""},{"title":"そうですね – để tôi nghĩ xem","form":"そうですね……","explain":"Ngoài nghĩa đồng tình (Bài 5), そうですね còn dùng khi người nói đang suy nghĩ để trả lời: “Ừm…, để xem…”.","examples":[{"s":"おしごとは どうですか。……そうですね。いそがしいですが、おもしろいです。","t":"Công việc của anh thế nào? – À, vâng. Bận nhưng thú vị."}],"tip":""}]},{"n":9,"title":"Bài 9","jp":"残念です","sub":"Thích, giỏi, hiểu · lý do ～から","rows":[["わかります［が］","分かります","v1","Hiểu, biết","understand","わたしは にほんごが わかります。／Tôi hiểu tiếng Nhật.","Nhóm I · thể từ điển: わかる · đối tượng dùng が."],["あります［が］","あります","v1","Có (sở hữu)","have","わたしは くるまが あります。／Tôi có xe ô tô.","Nhóm I · thể từ điển: ある · đồ vật dùng が."],["すき［な］","好き［な］","ana","Thích","like","わたしは おんがくが すきです。／Tôi thích âm nhạc.","Đối tượng dùng が: ～がすきです."],["きらい［な］","嫌い［な］","ana","Ghét, không thích","dislike","わたしは やさいが きらいです。／Tôi ghét rau.","Đối tượng dùng が. Tính từ đuôi な."],["じょうず［な］","上手［な］","ana","Giỏi","good at","ミラーさんは りょうりが じょうずです。／Anh Miller nấu ăn giỏi.","Không dùng để tự khen mình (dùng とくい)."],["へた［な］","下手［な］","ana","Kém, dở","poor at","わたしは うたが へたです。／Tôi hát dở.",""],["りょうり","料理","n","Món ăn, nấu ăn","dish, cooking","にほんりょうりが すきです。／Tôi thích món Nhật.","～をします: nấu ăn."],["のみもの","飲み物","n","Đồ uống","drinks","どんな のみものが すきですか。／Bạn thích đồ uống gì?",""],["スポーツ","","n","Thể thao","sport","どんな スポーツが すきですか。／Bạn thích môn thể thao nào?","～をします: chơi thể thao."],["やきゅう","野球","n","Bóng chày","baseball","やきゅうを します。／Chơi bóng chày.",""],["ダンス","","n","Khiêu vũ, nhảy","dance","ダンスが じょうずですね。／Nhảy giỏi nhỉ.","～をします: nhảy."],["おんがく","音楽","n","Âm nhạc","music","どんな おんがくが すきですか。／Bạn thích loại nhạc nào?",""],["うた","歌","n","Bài hát","song","にほんの うたが すきです。／Tôi thích bài hát Nhật.",""],["クラシック","","n","Nhạc cổ điển","classical music","クラシックを よく ききます。／Hay nghe nhạc cổ điển.",""],["ジャズ","","n","Nhạc jazz","jazz","ジャズが すきです。／Tôi thích nhạc jazz.",""],["コンサート","","n","Buổi hoà nhạc","concert","コンサートの チケットが あります。／Tôi có vé hoà nhạc.",""],["カラオケ","","n","Karaoke","karaoke","カラオケへ いきませんか。／Đi karaoke nhé?",""],["かぶき","歌舞伎","n","Kịch Kabuki","Kabuki (traditional Japanese drama)","かぶきを みた ことが ありますか。／Bạn đã xem Kabuki chưa?",""],["え","絵","n","Tranh, bức vẽ","picture, drawing","えを かきます。／Vẽ tranh.",""],["じ","字","n","Chữ","letter, character","きれいな じですね。／Chữ đẹp nhỉ.",""],["かんじ","漢字","n","Chữ Hán","Chinese characters","かんじが すこし わかります。／Tôi hiểu một chút chữ Hán.",""],["ひらがな","","n","Chữ Hiragana","Hiragana script","ひらがなで かいて ください。／Hãy viết bằng Hiragana.",""],["かたかな","","n","Chữ Katakana","Katakana script","なまえを かたかなで かきます。／Viết tên bằng Katakana.",""],["ローマじ","ローマ字","n","Chữ La-tinh (Romaji)","the Roman alphabet","ローマじで かいても いいですか。／Viết bằng Romaji có được không?",""],["こまかいおかね","細かいお金","n","Tiền lẻ","small change","こまかい おかねが ありません。／Tôi không có tiền lẻ.",""],["チケット","","n","Vé (xem phim, hoà nhạc)","ticket","コンサートの チケットを かいました。／Đã mua vé hoà nhạc.","Vé tàu xe thường dùng きっぷ."],["じかん","時間","n","Thời gian","time","じかんが ありません。／Không có thời gian.",""],["ようじ","用事","n","Việc bận, việc riêng","something to do, errand","きょうは ようじが あります。／Hôm nay tôi có việc.","Lý do từ chối khéo."],["やくそく","約束","n","Cuộc hẹn, lời hứa","appointment, promise","ともだちと やくそくが あります。／Tôi có hẹn với bạn.","～をします: hứa, hẹn."],["ごしゅじん","ご主人","n","Chồng (người khác)","(someone else's) husband","ごしゅじんは おげんきですか。／Chồng chị khoẻ không?",""],["おっと／しゅじん","夫／主人","n","Chồng (mình)","(my) husband","おっとは かいしゃいんです。／Chồng tôi là nhân viên công ty.",""],["おくさん","奥さん","n","Vợ (người khác)","(someone else's) wife","おくさんは にほんじんですか。／Vợ anh là người Nhật à?",""],["つま／かない","妻／家内","n","Vợ (mình)","(my) wife","つまは りょうりが じょうずです。／Vợ tôi nấu ăn giỏi.",""],["こども","子供","n","Con, trẻ con","child","こどもが ふたり います。／Tôi có hai đứa con.",""],["よく","","adv","Rõ, tốt, nhiều","well, much","にほんごが よく わかります。／Tôi hiểu tiếng Nhật tốt.","Ở Bài 22 còn nghĩa “thường xuyên”."],["だいたい","","adv","Đại khái, hầu hết","mostly, roughly","だいたい わかります。／Tôi hiểu đại khái.",""],["たくさん","","adv","Nhiều","many, much","おかねが たくさん あります。／Có nhiều tiền.",""],["すこし","少し","adv","Một ít, một chút","a little, a few","にほんごが すこし わかります。／Tôi hiểu một chút tiếng Nhật.",""],["ぜんぜん","全然","adv","Hoàn toàn (không)","not at all (with negatives)","フランスごが ぜんぜん わかりません。／Tôi hoàn toàn không hiểu tiếng Pháp.","Đi với phủ định."],["はやく","早く／速く","adv","Sớm, nhanh","early, quickly, fast","はやく かえります。／Về sớm.",""],["～から","","cj","Vì ~","because ~","じかんが ありませんから、いきません。／Vì không có thời gian nên không đi.","Đặt sau vế lý do."],["どうして","","q","Tại sao","why","どうして きのう やすみましたか。／Tại sao hôm qua bạn nghỉ?",""],["ざんねんです［ね］","残念です［ね］","ex","Tiếc quá [nhỉ]","I'm sorry (to hear that). / That's a pity.","いけませんか。ざんねんですね。／Không đi được à? Tiếc nhỉ.",""],["すみません","すみません","ex","Xin lỗi","I am sorry.","すみません、いけません。／Xin lỗi, tôi không đi được.",""],["もしもし","","it","A lô","hello (on the phone)","もしもし、ミラーです。／A lô, tôi là Miller đây.","Chỉ dùng khi gọi điện."],["ああ","","it","À, ồ","oh","ああ、そうですか。／À, ra vậy.",""],["いっしょにいかがですか","一緒にいかがですか","ex","Cùng đi với chúng tôi nhé?","Won't you join me (us)?","あした コンサートへ いきます。いっしょに いかがですか。／Mai tôi đi hoà nhạc. Đi cùng nhé?","Lời mời lịch sự."],["［～は］ちょっと…","","ex","[~] thì hơi… (khó)","[~] is a bit difficult.","あしたは ちょっと…。／Ngày mai thì hơi…","Từ chối khéo, bỏ lửng câu."],["だめですか","駄目ですか","ex","Không được à?","So you cannot (come)?","あしたは だめですか。／Mai không được à?",""],["またこんどおねがいします","また今度お願いします","ex","Hẹn lần sau nhé","Please ask me again some other time.","すみません。また こんど おねがいします。／Xin lỗi, hẹn lần sau nhé.","Từ chối khéo, giữ thể diện cho người mời."]],"ref":[["ポップス","","n","Nhạc pop","pop music","ポップスを よく ききます。／Tôi hay nghe nhạc pop.",""],["ロック","","n","Nhạc rock","rock music","ロックが すきです。／Tôi thích nhạc rock.",""],["ラテン","","n","Nhạc Latin","Latin music","ラテンの おんがくで おどります。／Tôi nhảy theo nhạc Latin.",""],["みんよう","民謡","n","Dân ca","folk song","にほんの みんようを ならいました。／Tôi đã học dân ca Nhật.",""],["えんか","演歌","n","Enka (thể loại ballad truyền thống Nhật)","enka (Japanese ballad)","そふは えんかが すきです。／Ông tôi thích nhạc enka.",""],["ミュージカル","","n","Ca kịch, nhạc kịch","musical","ミュージカルを みに いきます。／Tôi đi xem nhạc kịch.",""],["オペラ","","n","Ô-pê-ra","opera","オペラは あまり わかりません。／Tôi không hiểu ô-pê-ra lắm.",""],["エスエフ","SF","n","Phim khoa học viễn tưởng","science fiction","SFの えいがが すきです。／Tôi thích phim khoa học viễn tưởng.",""],["ホラー","","n","Phim kinh dị","horror","ホラーは こわいです。／Phim kinh dị thì đáng sợ.",""],["アニメ","","n","Phim hoạt hình","anime","にほんの アニメが すきです。／Tôi thích anime Nhật.",""],["ドキュメンタリー","","n","Phim tài liệu","documentary","ドキュメンタリーを みました。／Tôi đã xem phim tài liệu.",""],["れんあい","恋愛","n","Phim tình yêu; tình yêu","romance","れんあいえいがは あまり みません。／Tôi ít xem phim tình cảm.",""],["ミステリー","","n","Phim ly kỳ, bí ẩn","mystery","ミステリーの ほんを よみます。／Tôi đọc sách trinh thám.",""],["ぶんげい","文芸","n","Phim văn nghệ (chuyển thể văn học)","literary film","ぶんげいえいがは すこし むずかしいです。／Phim văn nghệ hơi khó hiểu.",""],["せんそう","戦争","n","Phim chiến tranh; chiến tranh","war","せんそうの えいがは かなしいです。／Phim chiến tranh buồn.",""],["アクション","","n","Phim hành động","action","アクションえいがが すきです。／Tôi thích phim hành động.",""],["きげき","喜劇","n","Phim hài, hài kịch","comedy","きげきを みて わらいました。／Tôi xem phim hài và đã cười.",""],["ソフトボール","","n","Bóng mềm (softball)","softball","がっこうで ソフトボールを します。／Tôi chơi bóng mềm ở trường.","Môn tựa như bóng chày"],["ラグビー","","n","Bóng bầu dục","rugby","ラグビーの しあいを みました。／Tôi đã xem trận bóng bầu dục.",""],["バレーボール","","n","Bóng chuyền","volleyball","バレーボールが じょうずです。／Tôi chơi bóng chuyền giỏi.",""],["バスケットボール","","n","Bóng rổ","basketball","バスケットボールを します。／Tôi chơi bóng rổ.",""],["ボウリング","","n","Bowling","bowling","ともだちと ボウリングに いきます。／Tôi đi chơi bowling với bạn.",""],["スケート","","n","Trượt băng","skating","スケートが へたです。／Tôi trượt băng kém.",""],["たっきゅう","卓球","n","Bóng bàn","table tennis","ひるやすみに たっきゅうを します。／Giờ nghỉ trưa tôi chơi bóng bàn.","Còn gọi ピンポン"],["ピンポン","","n","Bóng bàn (ping-pong)","ping-pong","ピンポンが できますか。／Bạn chơi bóng bàn được không?",""],["じゅうどう","柔道","n","Võ Judo","judo","じゅうどうを ならって います。／Tôi đang học judo.",""],["けんどう","剣道","n","Kiếm đạo (Kendo)","kendo","けんどうは にほんの スポーツです。／Kiếm đạo là môn thể thao của Nhật.",""],["すいえい","水泳","n","Bơi lội","swimming","しゅみは すいえいです。／Sở thích của tôi là bơi lội.",""]],"refTitle":"Âm nhạc, thể thao & điện ảnh","grammar":[{"title":"N が あります／わかります／好きです／上手です","form":"N が あります／わかります／すきです／きらいです／じょうずです／へたです","explain":"Một số động từ và tính từ đánh dấu đối tượng bằng が (không phải を): あります (có), わかります (hiểu), すき (thích), きらい (ghét), じょうず (giỏi), へた (kém).","examples":[{"s":"わたしは イタリアりょうりが すきです。","t":"Tôi thích món Ý."},{"s":"わたしは にほんごが わかります。","t":"Tôi hiểu tiếng Nhật."},{"s":"わたしは くるまが あります。","t":"Tôi có ô tô."}],"tip":"Sai: にほんごを わかります. Đúng: にほんごが わかります."},{"title":"どんな N – loại nào","form":"どんな N が すきですか · trả lời bằng tên cụ thể","explain":"Ngoài hỏi tính chất (Bài 8), câu hỏi どんな còn có thể trả lời bằng cách nêu ra một tên gọi cụ thể.","examples":[{"s":"どんな スポーツが すきですか。……サッカーが すきです。","t":"Bạn thích môn thể thao nào? – Tôi thích bóng đá."}],"tip":""},{"title":"よく／だいたい／たくさん／少し／あまり／全然","form":"Phó từ mức độ + わかります · Phó từ số lượng + あります","explain":"Đặt trước động từ để bổ nghĩa. Mức độ (khẳng định): よく (rõ, tốt), だいたい (đại khái), すこし (một chút); (phủ định): あまり (không… lắm), ぜんぜん (hoàn toàn không). Số lượng: たくさん (nhiều), すこし (ít); phủ định: あまり, ぜんぜん.\n\nすこし, ぜんぜん, あまり cũng dùng trước tính từ.","examples":[{"s":"えいごが よく わかります。","t":"Tôi hiểu tiếng Anh tốt."},{"s":"えいごが あまり わかりません。","t":"Tôi không hiểu tiếng Anh lắm."},{"s":"おかねが ぜんぜん ありません。","t":"Tôi không có đồng nào cả."},{"s":"ここは すこし さむいです。","t":"Ở đây hơi lạnh."}],"tip":"ぜんぜん và あまり chỉ đi với dạng phủ định."},{"title":"～から、～ – vì… nên","form":"Câu 1 (lý do) から、Câu 2 · Câu から です","explain":"から đặt sau vế nêu lý do. Cũng có thể nêu kết quả trước rồi thêm lý do + から ở sau.","examples":[{"s":"じかんが ありませんから、しんぶんを よみません。","t":"Vì không có thời gian nên tôi không đọc báo."},{"s":"まいあさ しんぶんを よみますか。……いいえ、よみません。じかんが ありませんから。","t":"Sáng nào bạn cũng đọc báo à? – Không, tôi không đọc. Vì không có thời gian."}],"tip":""},{"title":"どうして – tại sao","form":"どうして ～か · trả lời: ～から","explain":"Hỏi lý do; câu trả lời kết thúc bằng から. Hỏi lại lý do cho điều người kia vừa nói có thể dùng gọn どうしてですか.","examples":[{"s":"どうして あさ しんぶんを よみませんか。……じかんが ありませんから。","t":"Tại sao bạn không đọc báo buổi sáng? – Vì tôi không có thời gian."},{"s":"きょうは はやく かえります。……どうしてですか。……こどもの たんじょうびですから。","t":"Hôm nay tôi về sớm. – Sao vậy? – Vì hôm nay là sinh nhật con tôi."}],"tip":""}]},{"n":10,"title":"Bài 10","jp":"ナンプラー、ありますか","sub":"あります / います · vị trí","rows":[["います［が］","","v2","Có, ở (người, động vật)","exist, be (animate things)","こうえんに こどもが います。／Có trẻ con ở công viên.","Nhóm II · thể từ điển: いる · dùng cho người và động vật."],["あります［が］","","v1","Có, ở (đồ vật)","exist, be (inanimate things)","つくえの うえに ほんが あります。／Trên bàn có quyển sách.","Nhóm I · thể từ điển: ある · dùng cho đồ vật, cây cối."],["いろいろ［な］","色々［な］","ana","Nhiều loại, đủ thứ","various","いろいろな くにの ひとが います。／Có người từ nhiều nước.",""],["おとこのひと","男の人","n","Người đàn ông","man","あの おとこのひとは だれですか。／Người đàn ông kia là ai?",""],["おんなのひと","女の人","n","Người phụ nữ","woman","おんなのひとが います。／Có một người phụ nữ.",""],["おとこのこ","男の子","n","Cậu bé","boy","おとこのこが ふたり います。／Có hai cậu bé.",""],["おんなのこ","女の子","n","Cô bé","girl","おんなのこが あそんで います。／Cô bé đang chơi.",""],["いぬ","犬","n","Con chó","dog","にわに いぬが います。／Trong vườn có con chó.",""],["ねこ","猫","n","Con mèo","cat","いすの うえに ねこが います。／Trên ghế có con mèo.",""],["き","木","n","Cây","tree","こうえんに おおきい きが あります。／Ở công viên có cái cây to.",""],["もの","物","n","Đồ vật","thing","はこの なかに なにが ありますか。ーいろいろな ものが あります。／Trong hộp có gì? — Có nhiều đồ.",""],["フィルム","","n","Phim (máy ảnh)","film","カメラの フィルムを かいます。／Mua phim máy ảnh.",""],["でんち","電池","n","Pin","battery","でんちが ありません。／Hết pin rồi.",""],["はこ","箱","n","Hộp","box","はこの なかに なにが ありますか。／Trong hộp có gì?",""],["スイッチ","","n","Công tắc","switch","スイッチは ドアの よこに あります。／Công tắc ở cạnh cửa.",""],["れいぞうこ","冷蔵庫","n","Tủ lạnh","refrigerator","れいぞうこに ビールが あります。／Trong tủ lạnh có bia.",""],["テーブル","","n","Cái bàn","table","テーブルの うえに はなが あります。／Trên bàn có hoa.",""],["ベッド","","n","Giường","bed","ベッドの したに ねこが います。／Dưới giường có con mèo.",""],["たな","棚","n","Giá, kệ","shelf","たなの うえに はこが あります。／Trên kệ có cái hộp.",""],["ドア","","n","Cửa","door","ドアの まえに ひとが います。／Trước cửa có người.",""],["まど","窓","n","Cửa sổ","window","まどを あけて ください。／Hãy mở cửa sổ.",""],["ポスト","","n","Hòm thư","mailbox, postbox","えきの まえに ポストが あります。／Trước ga có hòm thư.",""],["ビル","","n","Toà nhà","building","あの ビルの 3かいに います。／Ở tầng 3 toà nhà kia.",""],["こうえん","公園","n","Công viên","park","こうえんに こどもが たくさん います。／Ở công viên có nhiều trẻ con.",""],["きっさてん","喫茶店","n","Quán cà phê","coffee shop","きっさてんで ともだちと はなします。／Nói chuyện với bạn ở quán cà phê.",""],["ほんや","本屋","n","Hiệu sách","bookstore","えきの ちかくに ほんやが あります。／Gần ga có hiệu sách.",""],["～や","～屋","sf","Cửa hàng ~","~ store","パンやで パンを かいます。／Mua bánh mì ở tiệm bánh.",""],["のりば","乗り場","n","Bến, chỗ lên xe","a place to catch taxis, trains, etc.","タクシーのりばは どこですか。／Bến taxi ở đâu?",""],["けん","県","n","Tỉnh","prefecture","ならけんに すんで います。／Tôi sống ở tỉnh Nara.",""],["うえ","上","n","Trên","on, above, over","つくえの うえに ほんが あります。／Trên bàn có sách.","Vị trí: N の うえ."],["した","下","n","Dưới","under, below","いすの したに ねこが います。／Dưới ghế có con mèo.",""],["まえ","前","n","Trước","front, before","えきの まえで まちます。／Đợi ở trước ga.",""],["うしろ","後ろ","n","Sau, đằng sau","back, behind","ドアの うしろに います。／Ở đằng sau cửa.",""],["みぎ","右","n","Bên phải","right [side]","ぎんこうの みぎに ほんやが あります。／Bên phải ngân hàng có hiệu sách.",""],["ひだり","左","n","Bên trái","left [side]","えきの ひだりに こうえんが あります。／Bên trái ga có công viên.",""],["なか","中","n","Trong","in, inside","はこの なかに なにも ありません。／Trong hộp không có gì.",""],["そと","外","n","Ngoài","outside","そとに だれが いますか。／Ai ở bên ngoài vậy?",""],["となり","隣","n","Bên cạnh (sát bên)","next, next door","ぎんこうの となりは ゆうびんきょくです。／Bên cạnh ngân hàng là bưu điện.","Dùng cho hai thứ cùng loại đứng sát nhau."],["ちかく","近く","n","Gần, vùng gần","near, vicinity","えきの ちかくに すんで います。／Tôi sống gần ga.",""],["あいだ","間","n","Giữa","between, among","ぎんこうと ほんやの あいだに あります。／Ở giữa ngân hàng và hiệu sách.","A と B の あいだ."],["～や～［など］","","pt","~ và ~ [vân vân]","~, ~, and so on","はこの なかに てがみや しゃしんなどが あります。／Trong hộp có thư, ảnh, v.v.","Liệt kê không đầy đủ (khác と: đầy đủ)."],["いちばん～","一番～","adv","~ nhất","the most ~","いちばん うえの たなです。／Là kệ trên cùng.",""],["～だんめ","～段目","ctr","Ngăn thứ ~, tầng kệ thứ ~","the ~th shelf","うえから 3だんめに あります。／Ở ngăn thứ 3 tính từ trên xuống.",""],["［どうも］すみません","","ex","Cảm ơn (vì đã làm phiền)","Thank you.","どうも すみません。／Cảm ơn anh nhiều.","Cảm ơn kèm ý áy náy vì làm phiền."],["チリソース","","n","Tương ớt","chilli sauce","チリソースは ありますか。／Có tương ớt không?",""],["おく","奥","n","Phía trong cùng","the back","みせの おくに あります。／Ở phía trong cùng của cửa hàng.",""],["スパイスコーナー","","n","Quầy gia vị","spice corner","スパイスコーナーは おくです。／Quầy gia vị ở trong cùng.",""]],"ref":[["げんかん","玄関","n","Cửa ra vào, sảnh vào nhà","entrance","げんかんで くつを ぬぎます。／Cởi giày ở cửa ra vào.","Người Nhật cởi giày ở 玄関"],["ふろば","ふろ場","n","Phòng tắm","bathroom (bath)","ふろばは あそこです。／Phòng tắm ở đằng kia.",""],["せんめんじょ","洗面所","n","Bồn rửa, chỗ rửa mặt","washroom","せんめんじょで てを あらいます。／Rửa tay ở bồn rửa.",""],["だいどころ","台所","n","Bếp","kitchen","はは は だいどころに います。／Mẹ ở trong bếp.",""],["いま","居間","n","Phòng khách, phòng sinh hoạt chung","living room","いまで テレビを みます。／Xem tivi ở phòng khách.",""],["しんしつ","寝室","n","Phòng ngủ","bedroom","しんしつに ベッドが あります。／Trong phòng ngủ có giường.",""],["ろうか","廊下","n","Hành lang","hallway","ろうかを はしらないで ください。／Đừng chạy ở hành lang.",""],["ベランダ","","n","Ban công","balcony","ベランダに はなが あります。／Trên ban công có hoa.",""],["ゆぶね","湯船","n","Bồn tắm","bathtub","ゆぶねの なかで せっけんを つかいません。／Không dùng xà phòng trong bồn tắm.","Tắm sạch trước khi vào bồn; ngâm xong để nước lại cho người sau"]],"refTitle":"Trong nhà","grammar":[{"title":"N が あります／います – có (tồn tại)","form":"N が あります (đồ vật, cây cối) · N が います (người, động vật)","explain":"Diễn tả sự tồn tại. あります cho vật không tự chuyển động (đồ vật, cây, nhà cửa); います cho người, động vật. Đối tượng tồn tại đánh dấu bằng が.","examples":[{"s":"コンピューターが あります。","t":"Có máy tính."},{"s":"さくらが あります。","t":"Có cây anh đào."},{"s":"おとこの ひとが います。","t":"Có người đàn ông."},{"s":"いぬが います。","t":"Có con chó."}],"tip":""},{"title":"Nơi chốn に N が あります／います","form":"N1 (nơi chốn) に N2 が あります／います","explain":"Nói ở một nơi nào đó có cái gì, có ai. Nơi tồn tại đánh dấu bằng に. Hỏi vật dùng なにが, hỏi người dùng だれが (sau từ để hỏi luôn là が).","examples":[{"s":"わたしの へやに つくえが あります。","t":"Trong phòng tôi có cái bàn."},{"s":"じむしょに ミラーさんが います。","t":"Ở văn phòng có anh Miller."},{"s":"ちかに なにが ありますか。……レストランが あります。","t":"Dưới tầng hầm có gì? – Có nhà hàng."},{"s":"うけつけに だれが いますか。……きむらさんが います。","t":"Ở quầy tiếp tân có ai? – Có chị Kimura."}],"tip":"Sai: なには ありますか. Đúng: なにが ありますか."},{"title":"N は nơi chốn に あります／います – ở đâu","form":"N は N (nơi chốn) に あります／います · = N は nơi chốn です","explain":"Khi vật/người đã được cả hai biết tới, đưa nó lên làm chủ đề với は rồi nói nó ở đâu. Có thể thay bằng mẫu N は nơi chốn です (Bài 3).","examples":[{"s":"とうきょうディズニーランドは ちばけんに あります。","t":"Tokyo Disneyland ở tỉnh Chiba."},{"s":"ミラーさんは どこに いますか。……じむしょに います。","t":"Anh Miller ở đâu? – Ở văn phòng."},{"s":"とうきょうディズニーランドは どこですか。……ちばけんです。","t":"Tokyo Disneyland ở đâu? – Ở tỉnh Chiba."}],"tip":""},{"title":"N1 の 上／下／中… – vị trí","form":"N1 の うえ／した／まえ／うしろ／みぎ／ひだり／なか／そと／となり／ちかく／あいだ","explain":"Các từ vị trí đứng sau N1 + の: trên, dưới, trước, sau, phải, trái, trong, ngoài, bên cạnh, gần, giữa. Cụm này hoạt động như danh từ chỉ nơi chốn, nên có thể thêm で để chỉ nơi diễn ra hành động.","examples":[{"s":"つくえの うえに しゃしんが あります。","t":"Trên bàn có bức ảnh."},{"s":"ゆうびんきょくは ぎんこうの となりに あります。","t":"Bưu điện ở bên cạnh ngân hàng."},{"s":"ほんやは はなやと スーパーの あいだに あります。","t":"Hiệu sách ở giữa hàng hoa và siêu thị."},{"s":"えきの ちかくで ともだちに あいました。","t":"Tôi gặp bạn ở gần ga."}],"tip":""},{"title":"N1 や N2 (など) – liệt kê tiêu biểu","form":"N1 や N2 (など)","explain":"と liệt kê đầy đủ tất cả; や chỉ liệt kê vài thứ tiêu biểu, ngụ ý còn nữa. Thêm など ở cuối để nói rõ còn những thứ khác.","examples":[{"s":"はこの なかに てがみや しゃしんが あります。","t":"Trong hộp có thư, ảnh (và còn thứ khác)."},{"s":"はこの なかに てがみや しゃしんなどが あります。","t":"Trong hộp có những thứ như thư, ảnh…"}],"tip":""},{"title":"アジアストアですか – xác nhận lại khi hỏi đường","form":"N ですか。(câu trả lời)","explain":"Trong hội thoại thực tế, trước khi trả lời người Nhật hay nhắc lại điều người kia hỏi để xác nhận: “Siêu thị Asia à?”.","examples":[{"s":"すみません。アジアストアは どこですか。……アジアストアですか。あの ビルの なかです。","t":"Xin lỗi, siêu thị Asia ở đâu? – Siêu thị Asia ấy à? Ở trong tòa nhà kia."}],"tip":""}]},{"n":11,"title":"Bài 11","jp":"これ、お願いします","sub":"Đếm đồ vật, người · bưu điện","rows":[["います［こどもが～］","","v2","Có [con]","have [a child]","わたしは こどもが ふたり います。／Tôi có hai đứa con.","Nhóm II · thể từ điển: いる"],["います［にほんに～］","","v2","Ở [Nhật Bản]","stay, be [in Japan]","1ねん にほんに います。／Tôi ở Nhật 1 năm.","Nhóm II · thể từ điển: いる"],["かかります","掛かります","v1","Mất, tốn (thời gian, tiền)","take (time or money)","うちから えきまで 10ぷん かかります。／Từ nhà đến ga mất 10 phút.","Nhóm I · thể từ điển: かかる"],["やすみます［かいしゃを～］","休みます","v1","Nghỉ [làm]","take a day off [work]","きのう かいしゃを やすみました。／Hôm qua tôi nghỉ làm.","Nhóm I · thể từ điển: やすむ"],["ひとつ","一つ","num","Một cái","one (thing)","りんごを ひとつ ください。／Cho tôi một quả táo.","Cách đếm đồ vật kiểu Nhật (1–10)."],["ふたつ","二つ","num","Hai cái","two (things)","たまごを ふたつ かいました。／Đã mua hai quả trứng.",""],["みっつ","三つ","num","Ba cái","three (things)","みかんを みっつ たべました。／Đã ăn ba quả quýt.",""],["よっつ","四つ","num","Bốn cái","four (things)","いすが よっつ あります。／Có bốn cái ghế.",""],["いつつ","五つ","num","Năm cái","five (things)","ケーキを いつつ ください。／Cho tôi năm cái bánh.",""],["むっつ","六つ","num","Sáu cái","six (things)","はこが むっつ あります。／Có sáu cái hộp.",""],["ななつ","七つ","num","Bảy cái","seven (things)","ななつ かいました。／Đã mua bảy cái.",""],["やっつ","八つ","num","Tám cái","eight (things)","やっつ ください。／Cho tôi tám cái.",""],["ここのつ","九つ","num","Chín cái","nine (things)","ここのつ あります。／Có chín cái.",""],["とお","十","num","Mười cái","ten (things)","とお ください。／Cho tôi mười cái.","Từ 11 trở lên dùng số thường: じゅういち…"],["いくつ","幾つ","q","Mấy cái, bao nhiêu cái","how many","りんごを いくつ かいましたか。／Bạn đã mua mấy quả táo?","Cũng dùng hỏi tuổi trẻ nhỏ."],["ひとり","一人","ctr","Một người","one person","ひとりで にほんへ きました。／Tôi đến Nhật một mình.","Ngoại lệ đọc: ひとり, ふたり."],["ふたり","二人","ctr","Hai người","two people","きょうだいが ふたり います。／Tôi có hai anh chị em.",""],["～にん","～人","ctr","~ người","~ people","クラスに がくせいが 20にん います。／Lớp có 20 học sinh.","Từ 3 người: さんにん, よにん (4)."],["～だい","～台","ctr","~ chiếc (máy móc, xe)","counter for machines, cars, etc.","くるまが 2だい あります。／Có hai chiếc ô tô.",""],["～まい","～枚","ctr","~ tờ, ~ tấm (vật mỏng)","counter for paper, stamps, etc.","80えんの きってを 5まい ください。／Cho tôi 5 con tem 80 yên.","Dùng cho giấy, áo sơ mi, đĩa…"],["～かい","～回","ctr","~ lần","~ times","1しゅうかんに 2かい プールへ いきます。／Một tuần đi bể bơi 2 lần.",""],["りんご","","n","Quả táo","apple","りんごを ひとつ たべます。／Ăn một quả táo.",""],["みかん","蜜柑","n","Quả quýt","mandarin orange","みかんを いつつ かいました。／Đã mua năm quả quýt.",""],["サンドイッチ","","n","Bánh mì kẹp","sandwich","サンドイッチを ふたつ ください。／Cho tôi hai bánh mì kẹp.",""],["カレー［ライス］","","n","[Cơm] cà ri","curry [and rice]","カレーライスを ひとつ ください。／Cho tôi một đĩa cơm cà ri.",""],["アイスクリーム","","n","Kem","ice cream","アイスクリームを たべませんか。／Ăn kem nhé?",""],["きって","切手","n","Tem","postage stamp","きってを 5まい かいました。／Đã mua 5 con tem.",""],["はがき","葉書","n","Bưu thiếp","postcard","はがきを 2まい ください。／Cho tôi 2 tấm bưu thiếp.",""],["ふうとう","封筒","n","Phong bì","envelope","ふうとうに てがみを いれます。／Cho thư vào phong bì.",""],["そくたつ","速達","n","Chuyển phát nhanh","special delivery","そくたつで おねがいします。／Gửi chuyển phát nhanh giúp tôi.",""],["かきとめ","書留","n","Thư bảo đảm","registered mail","かきとめで おくります。／Gửi thư bảo đảm.",""],["エアメール（こうくうびん）","航空便","n","Thư hàng không","airmail","エアメールで いくらですか。／Gửi đường hàng không bao nhiêu tiền?",""],["ふなびん","船便","n","Gửi đường biển","sea mail","ふなびんで 2かげつぐらい かかります。／Đường biển mất khoảng 2 tháng.",""],["りょうしん","両親","n","Bố mẹ","parents","りょうしんは くにに います。／Bố mẹ tôi ở quê nhà.",""],["きょうだい","兄弟","n","Anh chị em","brothers and sisters","きょうだいが なんにん いますか。／Bạn có mấy anh chị em?",""],["あに","兄","n","Anh trai (mình)","(my) elder brother","あには ぎんこうで はたらいて います。／Anh trai tôi làm ở ngân hàng.",""],["おにいさん","お兄さん","n","Anh trai (người khác)","(someone else's) elder brother","おにいさんは なんさいですか。／Anh trai bạn bao nhiêu tuổi?",""],["あね","姉","n","Chị gái (mình)","(my) elder sister","あねが ひとり います。／Tôi có một chị gái.",""],["おねえさん","お姉さん","n","Chị gái (người khác)","(someone else's) elder sister","おねえさんは どこに いますか。／Chị bạn đang ở đâu?",""],["おとうと","弟","n","Em trai (mình)","(my) younger brother","おとうとは だいがくせいです。／Em trai tôi là sinh viên.",""],["おとうとさん","弟さん","n","Em trai (người khác)","(someone else's) younger brother","おとうとさんは おげんきですか。／Em trai bạn khoẻ không?",""],["いもうと","妹","n","Em gái (mình)","(my) younger sister","いもうとが ふたり います。／Tôi có hai em gái.",""],["いもうとさん","妹さん","n","Em gái (người khác)","(someone else's) younger sister","いもうとさんは なんさいですか。／Em gái bạn mấy tuổi?",""],["がいこく","外国","n","Nước ngoài","foreign country","がいこくへ いった ことが ありますか。／Bạn đã đi nước ngoài chưa?",""],["～じかん","～時間","sf","~ tiếng (giờ đồng hồ)","~ hours","まいにち 8じかん はたらきます。／Mỗi ngày làm việc 8 tiếng.","Khác ～じ (lúc ~ giờ)."],["～しゅうかん","～週間","sf","~ tuần","~ weeks","2しゅうかん やすみます。／Nghỉ 2 tuần.",""],["～かげつ","～か月","sf","~ tháng","~ months","3かげつ にほんごを べんきょうしました。／Đã học tiếng Nhật 3 tháng.","Khác ～がつ (tháng ~ trong năm)."],["～ねん","～年","sf","~ năm","~ years","2ねん にほんに います。／Tôi ở Nhật 2 năm.",""],["～ぐらい","","sf","Khoảng ~","about ~","えきまで 10ぷんぐらい かかります。／Đến ga mất khoảng 10 phút.","Dùng với lượng; với giờ cụ thể dùng ～ごろ."],["どのくらい","","q","Bao lâu, bao nhiêu","how long, how much","とうきょうから おおさかまで どのくらい かかりますか。／Từ Tokyo đến Osaka mất bao lâu?",""],["ぜんぶで","全部で","adv","Tổng cộng","in total","ぜんぶで 500えんです。／Tổng cộng 500 yên.",""],["みんな","皆","n","Mọi người, tất cả","all, everything, everyone","みんなで しゃしんを とりましょう。／Cả nhà cùng chụp ảnh nào.",""],["～だけ","","pt","Chỉ ~","only ~","やすみは にちようびだけです。／Ngày nghỉ chỉ có chủ nhật.",""],["いらっしゃいませ","","ex","Xin mời quý khách","Welcome. / May I help you?","いらっしゃいませ。なんめいさまですか。／Xin chào quý khách, mấy vị ạ?","Nhân viên chào khách vào cửa hàng."],["いい［お］てんきですね","いい［お］天気ですね","ex","Trời đẹp nhỉ","Nice weather, isn't it?","いい おてんきですね。ーええ、そうですね。／Trời đẹp nhỉ. — Vâng, đúng vậy.","Câu chào xã giao."],["おでかけですか","お出かけですか","ex","Anh/chị đi ra ngoài đấy à?","Are you going out?","おでかけですか。ーええ、ちょっと ゆうびんきょくまで。／Đi đâu đấy? — Vâng, ra bưu điện chút.","Hỏi xã giao, không cần trả lời cụ thể."],["ちょっと～まで","一寸～まで","ex","Tôi đi ~ một chút","I'm just going to ~.","ちょっと ぎんこうまで。／Tôi ra ngân hàng chút.",""],["いっていらっしゃい","行っていらっしゃい","ex","Anh/chị đi nhé (rồi về)","So long. (lit. Go and come back.)","いって いらっしゃい。きを つけて。／Đi nhé, cẩn thận.","Người ở nhà nói với người ra đi."],["いってまいります","行ってまいります","ex","Tôi đi đây (rồi về)","So long. (lit. I'm going and coming back.)","いって まいります。ーいって いらっしゃい。／Tôi đi đây. — Đi nhé.","Lịch sự hơn いってきます."],["それから","","cj","Ngoài ra, thêm nữa","and, furthermore","きってを 5まい、それから はがきを 2まい ください。／Cho 5 tem, thêm 2 bưu thiếp.",""]],"ref":[["メニュー","","n","Thực đơn","menu","メニューを みせて ください。／Cho tôi xem thực đơn.",""],["ランチ","","n","Cơm trưa (suất)","lunch special","ランチは 800えんです。／Suất trưa giá 800 yên.",""],["てんどん","天どん","n","Cơm tôm chiên tẩm bột","tempura rice bowl","てんどんを ひとつ ください。／Cho tôi một bát cơm tempura.",""],["おやこどん","親子どん","n","Cơm với thịt gà và trứng","chicken and egg rice bowl","おやこどんは やすくて おいしいです。／Oyakodon rẻ và ngon.","Nghĩa đen: bát \"mẹ con\" (gà và trứng)"],["ぎゅうどん","牛どん","n","Cơm thịt bò","beef rice bowl","ぎゅうどんを ふたつ ください。／Cho tôi hai bát cơm bò.",""],["やきにく","焼き肉","n","Thịt nướng","grilled meat","こんばん やきにくを たべませんか。／Tối nay đi ăn thịt nướng không?",""],["やさいいため","野菜いため","n","Rau xào","stir-fried vegetables","やさいいためを つくりました。／Tôi đã làm món rau xào.",""],["つけもの","漬物","n","Dưa muối","pickles","ごはんと つけものを たべます。／Tôi ăn cơm với dưa muối.",""],["みそしる","みそ汁","n","Súp miso","miso soup","まいあさ みそしるを のみます。／Sáng nào tôi cũng ăn súp miso.",""],["おにぎり","","n","Cơm nắm","rice ball","コンビニで おにぎりを かいます。／Tôi mua cơm nắm ở cửa hàng tiện lợi.",""],["すし","","n","Sushi","sushi","すしを たべに いきます。／Tôi đi ăn sushi.",""],["うどん","","n","Mì udon (làm từ bột lúa mạch)","udon noodles","あたたかい うどんを たべます。／Tôi ăn mì udon nóng.",""],["そば","","n","Mì soba (làm từ bột kiều mạch)","soba noodles","ひるごはんに そばを たべました。／Bữa trưa tôi ăn mì soba.",""],["ラーメン","","n","Mì Tàu, ramen","ramen","ラーメンが だいすきです。／Tôi rất thích ramen.",""],["やきそば","焼きそば","n","Mì xào với rau và thịt","fried noodles","おまつりで やきそばを たべました。／Tôi ăn mì xào ở lễ hội.",""],["おこのみやき","お好み焼き","n","Okonomiyaki (bánh xèo kiểu Nhật)","okonomiyaki","おおさかで おこのみやきを たべました。／Tôi ăn okonomiyaki ở Osaka.","Gồm bắp cải, trứng, thịt lợn…"],["カレーライス","","n","Cơm cà ri","curry rice","カレーライスを ください。／Cho tôi cơm cà ri.",""],["ハンバーグ","","n","Thịt băm viên rán, hambagu","hamburger steak","こどもは ハンバーグが すきです。／Trẻ con thích hambagu.",""],["コロッケ","","n","Khoai tây bọc bột chiên","croquette","コロッケを みっつ ください。／Cho tôi ba cái croquette.",""],["えびフライ","","n","Tôm chiên","fried shrimp","えびフライていしょくに します。／Tôi chọn suất tôm chiên.",""],["フライドチキン","","n","Thịt gà chiên","fried chicken","フライドチキンを たべます。／Tôi ăn gà rán.",""],["サラダ","","n","Sa-lát","salad","サラダを たべます。／Tôi ăn salad.",""],["スープ","","n","Súp","soup","スープは あついです。／Súp nóng.",""],["スパゲッティ","","n","Mì Ý, spaghetti","spaghetti","スパゲッティを つくります。／Tôi nấu mì Ý.",""],["ピザ","","n","Bánh pi-za","pizza","ピザを ちゅうもんしましょう。／Mình gọi pizza đi.",""],["ハンバーガー","","n","Bánh hăm-bơ-gơ","hamburger","ハンバーガーを ふたつ ください。／Cho tôi hai cái hamburger.",""],["トースト","","n","Bánh mì nướng","toast","トーストと コーヒーを ください。／Cho tôi bánh mì nướng và cà phê.",""],["ココア","","n","Ca-cao","cocoa","あたたかい ココアを のみます。／Tôi uống ca-cao nóng.",""],["コーラ","","n","Cô-ca cô-la","cola","コーラを のみますか。／Bạn uống cola không?",""]],"refTitle":"Thực đơn","grammar":[{"title":"Cách đếm số lượng & trợ số từ","form":"ひとつ、ふたつ…とお (1–10) · số + 人／台／枚／回／分／時間／日／週間／か月／年","explain":"Đếm đồ vật nói chung từ 1 đến 10 dùng ひとつ, ふたつ… とお; từ 11 trở lên đọc số bình thường.\n\nĐếm theo loại dùng trợ số từ đặt sau số: ～にん (người; 1 người ひとり, 2 người ふたり, 4 người よにん), ～だい (máy móc, xe cộ), ～まい (vật mỏng, dẹt: giấy, áo, đĩa, tem), ～かい (lần), ～ふん/ぷん (phút), ～じかん (tiếng), ～にち (ngày), ～しゅうかん (tuần), ～かげつ (tháng), ～ねん (năm).","examples":[{"s":"りんごを よっつ かいました。","t":"Tôi đã mua 4 quả táo."},{"s":"きってを 5まい ください。","t":"Cho tôi 5 con tem."},{"s":"くるまが 2だい あります。","t":"Có 2 chiếc ô tô."}],"tip":"1 ngày (khoảng thời gian) là いちにち, không đọc ついたち (mồng 1)."},{"title":"Vị trí số lượng từ trong câu","form":"N を／が + số lượng + V","explain":"Số lượng (số + trợ số từ) thường đứng ngay sau cụm “danh từ + trợ từ”, trước động từ. Riêng số lượng chỉ thời gian thì vị trí tự do hơn.","examples":[{"s":"がいこくじんの がくせいが ふたり います。","t":"Có hai sinh viên nước ngoài."},{"s":"くにで 2かげつ にほんごを べんきょうしました。","t":"Tôi đã học tiếng Nhật 2 tháng ở trong nước."}],"tip":"Sai: ふたつの りんごを かいました (không tự nhiên). Tự nhiên: りんごを ふたつ かいました."},{"title":"Hỏi số lượng – いくつ／なん + trợ số từ／どのくらい","form":"いくつ · なん + trợ số từ · どのくらい · số + ぐらい","explain":"Đếm bằng ひとつ, ふたつ… thì hỏi いくつ. Đếm bằng trợ số từ thì hỏi なん + trợ số từ (なんにん, なんまい, なんじかん). Hỏi độ dài thời gian dùng どのくらい. Thêm ぐらい sau số để nói “khoảng”.","examples":[{"s":"みかんを いくつ かいましたか。……やっつ かいました。","t":"Bạn mua mấy quả quýt? – Tôi mua 8 quả."},{"s":"この かいしゃに がいこくじんが なんにん いますか。……5にん います。","t":"Ở công ty này có mấy người nước ngoài? – Có 5 người."},{"s":"どのくらい にほんごを べんきょうしましたか。……3ねん べんきょうしました。","t":"Bạn đã học tiếng Nhật bao lâu? – Tôi đã học 3 năm."},{"s":"がっこうに せんせいが 30にんぐらい います。","t":"Ở trường có khoảng 30 giáo viên."}],"tip":""},{"title":"Khoảng thời gian に ～回 V – tần suất","form":"Khoảng thời gian に + số lần + V","explain":"Nói tần suất: trong một khoảng thời gian làm bao nhiêu lần.","examples":[{"s":"1かげつに 2かい えいがを みます。","t":"Một tháng tôi xem phim 2 lần."},{"s":"1しゅうかんに 3かい プールで およぎます。","t":"Một tuần tôi bơi 3 lần."}],"tip":""},{"title":"Số lượng / N だけ – chỉ","form":"Số lượng + だけ · N + だけ","explain":"だけ đặt sau số lượng hoặc danh từ: “chỉ, không hơn, không có gì khác”.","examples":[{"s":"パワーでんきに がいこくじんの しゃいんが ひとりだけ います。","t":"Công ty Power chỉ có một nhân viên người nước ngoài."},{"s":"やすみは にちようびだけです。","t":"Ngày nghỉ của tôi chỉ có Chủ nhật thôi."}],"tip":""}]},{"n":12,"title":"Bài 12","jp":"祇園祭はどうでしたか","sub":"Quá khứ tính từ · so sánh","rows":[["かんたん［な］","簡単［な］","ana","Đơn giản, dễ","easy, simple","この もんだいは かんたんです。／Câu hỏi này đơn giản.","Tính từ đuôi な."],["ちかい","近い","ai","Gần","near","えきは ちかいです。／Nhà ga gần.",""],["とおい","遠い","ai","Xa","far","がっこうは とおいです。／Trường xa.",""],["はやい","速い／早い","ai","Nhanh; sớm","fast, early","しんかんせんは はやいです。／Tàu Shinkansen nhanh.","速い: tốc độ · 早い: thời gian."],["おそい","遅い","ai","Chậm; muộn","slow, late","バスは おそいです。／Xe buýt chậm.",""],["おおい［ひとが～］","多い［人が～］","ai","Nhiều [người]","many [people], much","とうきょうは ひとが おおいです。／Tokyo đông người.","Không đặt trực tiếp trước danh từ (おおくの ひと)."],["すくない［ひとが～］","少ない［人が～］","ai","Ít [người]","few [people], a little","この まちは ひとが すくないです。／Thị trấn này ít người.",""],["あたたかい","暖かい／温かい","ai","Ấm áp","warm","はるは あたたかいです。／Mùa xuân ấm áp.","暖かい: thời tiết · 温かい: đồ vật, tấm lòng."],["すずしい","涼しい","ai","Mát mẻ","cool","あきは すずしいです。／Mùa thu mát mẻ.",""],["あまい","甘い","ai","Ngọt","sweet","この ケーキは あまいです。／Bánh này ngọt.",""],["からい","辛い","ai","Cay; mặn","hot (taste), spicy","タイりょうりは からいです。／Món Thái cay.",""],["おもい","重い","ai","Nặng","heavy","この にもつは おもいです。／Hành lý này nặng.",""],["かるい","軽い","ai","Nhẹ","light","この かばんは かるいです。／Cái cặp này nhẹ.",""],["いい［コーヒーが～］","","ai","Chọn, thích [cà phê] hơn","prefer [coffee]","コーヒーと こうちゃと どちらが いいですか。ーコーヒーが いいです。／Cà phê hay hồng trà? — Cho tôi cà phê.","Dùng khi chọn lựa."],["きせつ","季節","n","Mùa","season","どの きせつが いちばん すきですか。／Bạn thích mùa nào nhất?",""],["はる","春","n","Mùa xuân","spring","はるは さくらが きれいです。／Mùa xuân hoa anh đào đẹp.",""],["なつ","夏","n","Mùa hè","summer","にほんの なつは あついです。／Mùa hè ở Nhật nóng.",""],["あき","秋","n","Mùa thu","autumn, fall","あきは もみじが きれいです。／Mùa thu lá đỏ đẹp.",""],["ふゆ","冬","n","Mùa đông","winter","ふゆは ゆきが ふります。／Mùa đông có tuyết rơi.",""],["てんき","天気","n","Thời tiết","weather","きのうの てんきは どうでしたか。／Thời tiết hôm qua thế nào?",""],["あめ","雨","n","Mưa","rain, rainy","きのうは あめでした。／Hôm qua trời mưa.","Đồng âm あめ (kẹo, 飴) khác ngữ điệu."],["ゆき","雪","n","Tuyết","snow, snowy","ゆきが たくさん ふりました。／Tuyết rơi nhiều.",""],["くもり","曇り","n","Trời nhiều mây, âm u","cloudy","あしたは くもりです。／Ngày mai trời âm u.",""],["ホテル","","n","Khách sạn","hotel","ホテルは えきから ちかいです。／Khách sạn gần ga.",""],["くうこう","空港","n","Sân bay","airport","くうこうまで バスで いきます。／Đi xe buýt đến sân bay.",""],["うみ","海","n","Biển","sea, ocean","なつ うみへ いきました。／Mùa hè đã đi biển.",""],["せかい","世界","n","Thế giới","world","せかいで いちばん たかい やまは どこですか。／Núi cao nhất thế giới ở đâu?",""],["パーティー","","n","Bữa tiệc","party","パーティーは たのしかったです。／Bữa tiệc rất vui.","～をします: tổ chức tiệc."],["［お］まつり","［お］祭り","n","Lễ hội","festival","きょうとの おまつりは にぎやかでした。／Lễ hội Kyoto rất náo nhiệt.",""],["しけん","試験","n","Kỳ thi, bài thi","examination","しけんは むずかしかったです。／Bài thi khó.",""],["すきやき","すき焼き","n","Sukiyaki (lẩu bò)","sukiyaki (beef and vegetable hot pot)","すきやきは おいしかったです。／Món sukiyaki ngon.",""],["さしみ","刺身","n","Sashimi (gỏi cá sống)","sashimi (sliced raw fish)","さしみが すきですか。／Bạn thích sashimi không?",""],["［お］すし","［お］寿司","n","Sushi","sushi (vinegared rice with raw fish)","すしを たべに いきましょう。／Đi ăn sushi nào.",""],["てんぷら","天ぷら","n","Tempura (đồ chiên tẩm bột)","tempura (seafood and vegetables fried in batter)","てんぷらと すしと どちらが すきですか。／Thích tempura hay sushi hơn?",""],["いけばな","生け花","n","Nghệ thuật cắm hoa","flower arrangement","いけばなを ならって います。／Tôi đang học cắm hoa.","～をします: cắm hoa."],["もみじ","紅葉","n","Lá đỏ, cây phong","maple, red leaves of autumn","もみじを みに いきます。／Đi ngắm lá đỏ.",""],["どちら","","q","Cái nào (trong hai)","which one (of two)","コーヒーと こうちゃと どちらが すきですか。／Thích cà phê hay hồng trà?",""],["どちらも","","adv","Cả hai","both","どちらも すきです。／Thích cả hai.",""],["ずっと","","adv","Hơn hẳn","by far","この ほうが ずっと べんりです。／Cái này tiện hơn hẳn.","Bài 24/25: “suốt”."],["はじめて","初めて","adv","Lần đầu tiên","for the first time","はじめて すしを たべました。／Lần đầu tiên ăn sushi.",""],["ただいま","","ex","Tôi đã về đây","I'm home.","ただいま。ーおかえりなさい。／Con về rồi. — Con về đấy à.",""],["おかえりなさい","お帰りなさい","ex","Anh/chị đã về đấy à","Welcome home.","おかえりなさい。つかれましたか。／Về rồi à. Mệt không?","Đáp lại ただいま."],["すごいですね","凄いですね","ex","Ghê quá nhỉ, giỏi quá","That's amazing.","ひとが おおいですね。すごいですね。／Đông người nhỉ. Ghê thật.",""],["でも","","cj","Nhưng","but","たのしかったです。でも つかれました。／Vui lắm. Nhưng mệt.","Đầu câu."],["つかれました","疲れました","ex","Tôi mệt rồi","I'm tired.","ああ、つかれました。／Ôi, mệt quá.",""]],"ref":[["まつり","祭り","n","Lễ hội","festival","なつに まつりが あります。／Mùa hè có lễ hội.",""],["めいしょ","名所","n","Địa danh nổi tiếng, danh lam","famous place","きょうとは めいしょが おおいです。／Kyōto có nhiều danh lam.",""],["きんかくじ","金閣寺","n","Chùa Vàng (Kinkaku-ji, Kyōto)","Kinkakuji (Golden Pavilion)","きんかくじは きょうとに あります。／Chùa Vàng ở Kyōto.","Tên chính thức: 鹿苑寺 (Rokuon-ji)"],["ふじさん","富士山","n","Núi Phú Sĩ","Mt. Fuji","ふじさんは にほんで いちばん たかい やまです。／Núi Phú Sĩ là núi cao nhất Nhật Bản.",""],["とうしょうぐう","東照宮","n","Đền Tōshōgū (Nikkō)","Toshogu Shrine","にっこうの とうしょうぐうへ いきました。／Tôi đã đến đền Tōshōgū ở Nikkō.",""],["こうきょ","皇居","n","Hoàng cung (Tōkyō)","Imperial Palace","こうきょは とうきょうに あります。／Hoàng cung ở Tōkyō.",""],["ひめじじょう","姫路城","n","Thành Himeji","Himeji Castle","ひめじじょうは しろくて きれいです。／Thành Himeji trắng và đẹp.",""],["げんばくドーム","原爆ドーム","n","Mái vòm bom nguyên tử (Hiroshima)","Atomic Bomb Dome","ひろしまで げんばくドームを みました。／Tôi đã xem Mái vòm bom nguyên tử ở Hiroshima.",""],["とうだいじ","東大寺","n","Chùa Tōdai-ji (Nara)","Todaiji Temple","ならの とうだいじに だいぶつが あります。／Ở chùa Tōdai-ji, Nara có tượng Đại Phật.",""],["だいぶつ","大仏","n","Tượng Phật lớn, Đại Phật","Great Buddha","だいぶつは とても おおきいです。／Tượng Đại Phật rất lớn.",""],["ぎおんまつり","祇園祭","n","Lễ hội Gion (Kyōto)","Gion Festival","ぎおんまつりは 7がつに あります。／Lễ hội Gion diễn ra vào tháng 7.",""],["てんじんまつり","天神祭","n","Lễ hội Tenjin (Ōsaka)","Tenjin Festival","てんじんまつりで ふねを みました。／Tôi xem thuyền ở lễ hội Tenjin.",""],["かんだまつり","神田祭","n","Lễ hội Kanda (Tōkyō)","Kanda Festival","かんだまつりは とうきょうの まつりです。／Lễ hội Kanda là lễ hội của Tōkyō.",""]],"refTitle":"Lễ hội và địa danh","grammar":[{"title":"Quá khứ của câu danh từ và tính từ な","form":"N／Adjな でした · N／Adjな じゃ（では）ありませんでした","explain":"Quá khứ của です là でした; phủ định quá khứ là じゃ（では）ありませんでした. Áp dụng cho câu danh từ và câu tính từ な.","examples":[{"s":"きのうは あめでした。","t":"Hôm qua trời mưa."},{"s":"きのうの しけんは かんたんじゃ ありませんでした。","t":"Bài thi hôm qua không dễ."}],"tip":""},{"title":"Quá khứ của tính từ い","form":"Adj(bỏ い) かったです · Adj(bỏ い) くなかったです","explain":"Tính từ い chia quá khứ bằng cách bỏ い thêm かったです; phủ định quá khứ bỏ い thêm くなかったです. Đặc biệt: いい → よかったです / よくなかったです.","examples":[{"s":"きのうは あつかったです。","t":"Hôm qua trời nóng."},{"s":"きのうの パーティーは あまり たのしくなかったです。","t":"Bữa tiệc hôm qua không vui lắm."}],"tip":"Sai: あついでした. Đúng: あつかったです."},{"title":"N1 は N2 より Adj です – so sánh hơn","form":"N1 は N2 より Adj です","explain":"Lấy N2 làm chuẩn để nói N1 có tính chất hơn: “N1 … hơn N2”.","examples":[{"s":"この くるまは あの くるまより おおきいです。","t":"Chiếc ô tô này lớn hơn chiếc kia."},{"s":"ベトナムは にほんより あついです。","t":"Việt Nam nóng hơn Nhật Bản."}],"tip":""},{"title":"N1 と N2 と どちらが Adj ですか – cái nào hơn","form":"N1 と N2 と どちらが Adj ですか · ……N1／N2 の ほうが Adj です","explain":"So sánh hai đối tượng (vật, người, nơi chốn, thời gian…) đều dùng どちら. Trả lời: N の ほうが ～です.","examples":[{"s":"サッカーと やきゅうと どちらが おもしろいですか。……サッカーの ほうが おもしろいです。","t":"Bóng đá và bóng chày, môn nào thú vị hơn? – Bóng đá thú vị hơn."},{"s":"ミラーさんと サントスさんと どちらが テニスが じょうずですか。","t":"Anh Miller và anh Santos, ai chơi quần vợt giỏi hơn?"},{"s":"はると あきと どちらが すきですか。","t":"Mùa xuân và mùa thu, bạn thích mùa nào hơn?"}],"tip":""},{"title":"N1 [の 中]で なに／どこ／だれ／いつ が いちばん Adj ですか","form":"N1 [の なか]で なに／どこ／だれ／いつ が いちばん Adj ですか · ……N2 が いちばん Adj です","explain":"で chỉ phạm vi so sánh; いちばん = nhất. Từ để hỏi chọn theo đối tượng (vật: なに, nơi: どこ, người: だれ, thời gian: いつ) và luôn đi với が.","examples":[{"s":"にほんりょうり[の なか]で なにが いちばん おいしいですか。……てんぷらが いちばん おいしいです。","t":"Trong các món Nhật, món nào ngon nhất? – Tempura ngon nhất."},{"s":"かぞくで だれが いちばん せが たかいですか。……おとうとが いちばん せが たかいです。","t":"Trong gia đình bạn ai cao nhất? – Em trai tôi cao nhất."},{"s":"1ねんで いつが いちばん さむいですか。……2がつが いちばん さむいです。","t":"Trong một năm, khi nào lạnh nhất? – Tháng 2 lạnh nhất."}],"tip":""},{"title":"Adj の – の thay cho danh từ","form":"Adj + の (= Adj + N đã nhắc)","explain":"Giống “N1 の” ở Bài 2, の sau tính từ thay cho danh từ đã xuất hiện trước: “cái …”.","examples":[{"s":"カリナさんの かばんは どれですか。……あの あかくて、おおきいのです。","t":"Cặp của chị Karina là cái nào? – Là cái màu đỏ, to kia."},{"s":"もっと やすいのは ありませんか。","t":"Có cái nào rẻ hơn không?"}],"tip":""}]},{"n":13,"title":"Bài 13","jp":"別々にお願いします","sub":"ほしい · ～たい · mục đích ～に行きます","rows":[["あそびます","遊びます","v1","Chơi","enjoy oneself, play","こうえんで こどもと あそびます。／Chơi với con ở công viên.","Nhóm I · thể từ điển: あそぶ · không dùng cho thể thao."],["およぎます","泳ぎます","v1","Bơi","swim","うみで およぎます。／Bơi ở biển.","Nhóm I · thể từ điển: およぐ"],["むかえます","迎えます","v2","Đón","go to meet, welcome","くうこうへ ともだちを むかえに いきます。／Đi đón bạn ở sân bay.","Nhóm II · thể từ điển: むかえる"],["つかれます","疲れます","v2","Mệt","get tired","しごとで つかれました。／Mệt vì công việc.","Nhóm II · thể từ điển: つかれる · thường dùng つかれました/つかれています."],["だします［てがみを～］","出します","v1","Gửi [thư]","send [a letter]","ゆうびんきょくで てがみを だします。／Gửi thư ở bưu điện.","Nhóm I · thể từ điển: だす"],["はいります［きっさてんに～］","入ります","v1","Vào [quán cà phê]","enter [a coffee shop]","きっさてんに はいります。／Vào quán cà phê.","Nhóm I · thể từ điển: はいる · nơi vào dùng に."],["でます［きっさてんを～］","出ます","v2","Ra khỏi [quán cà phê]","go out [of a coffee shop]","7じに うちを でます。／7 giờ ra khỏi nhà.","Nhóm II · thể từ điển: でる · nơi rời khỏi dùng を."],["けっこんします","結婚します","v3","Kết hôn","marry, get married","らいねん けっこんします。／Năm sau tôi kết hôn.","Nhóm III · người kết hôn cùng dùng と."],["かいものします","買い物します","v3","Mua sắm","do shopping","デパートへ かいものに いきます。／Đi bách hoá mua sắm.","Nhóm III"],["しょくじします","食事します","v3","Dùng bữa","have a meal, dine","ともだちと しょくじします。／Dùng bữa với bạn.","Nhóm III"],["さんぽします［こうえんを～］","散歩します","v3","Đi dạo [ở công viên]","take a walk [in a park]","まいあさ こうえんを さんぽします。／Sáng nào cũng đi dạo công viên.","Nhóm III · nơi đi qua dùng を."],["たいへん［な］","大変［な］","ana","Vất vả, khó khăn","hard, tough, awful","しごとは たいへんです。／Công việc vất vả.","Tính từ đuôi な."],["ほしい","欲しい","ai","Muốn (có cái gì)","want (something)","わたしは くるまが ほしいです。／Tôi muốn có ô tô.","Đối tượng dùng が; chỉ cho mong muốn của mình (hỏi người nghe)."],["さびしい","寂しい","ai","Buồn, cô đơn","lonely","ひとりで さびしいです。／Một mình buồn quá.",""],["ひろい","広い","ai","Rộng","wide, spacious","この へやは ひろいです。／Phòng này rộng.",""],["せまい","狭い","ai","Chật, hẹp","narrow, small (room, etc.)","わたしの へやは せまいです。／Phòng tôi chật.",""],["しやくしょ","市役所","n","Văn phòng hành chính thành phố","municipal office, city hall","しやくしょへ とうろくに いきます。／Đi lên toà thị chính để đăng ký.",""],["プール","","n","Bể bơi","swimming pool","プールで およぎます。／Bơi ở bể bơi.",""],["かわ","川","n","Sông","river","かわで さかなを つります。／Câu cá ở sông.",""],["けいざい","経済","n","Kinh tế","economy","にほんの けいざいを べんきょうします。／Học kinh tế Nhật Bản.",""],["びじゅつ","美術","n","Mỹ thuật","fine arts","びじゅつを べんきょうしに きました。／Đến để học mỹ thuật.",""],["つり","釣り","n","Câu cá","fishing","かわへ つりに いきます。／Đi câu cá ở sông.","～をします: câu cá."],["スキー","","n","Trượt tuyết","skiing","ほっかいどうへ スキーに いきます。／Đi Hokkaido trượt tuyết.","～をします: trượt tuyết."],["かいぎ","会議","n","Cuộc họp","meeting, conference","あした かいぎが あります。／Ngày mai có cuộc họp.","～をします: tổ chức họp."],["とうろく","登録","n","Đăng ký","registration","がいこくじんとうろくを します。／Đăng ký người nước ngoài.","～をします: đăng ký."],["しゅうまつ","週末","n","Cuối tuần","weekend","しゅうまつは なにを しますか。／Cuối tuần bạn làm gì?",""],["～ごろ","","sf","Khoảng ~ (thời điểm)","about (time)","7じごろ かえります。／Khoảng 7 giờ về.","Với lượng thời gian dùng ～ぐらい."],["なにか","何か","pr","Cái gì đó","something","なにか のみたいです。／Tôi muốn uống gì đó.",""],["どこか","","pr","Đâu đó","somewhere, some place","ふゆやすみは どこか いきましたか。／Nghỉ đông có đi đâu không?","Trợ từ へ có thể lược."],["おなかがすきました","お腹が空きました","ex","Tôi đói rồi","I'm hungry.","おなかが すきましたね。なにか たべましょう。／Đói rồi nhỉ. Ăn gì đi.",""],["おなかがいっぱいです","お腹が一杯です","ex","Tôi no rồi","I'm full.","もう おなかが いっぱいです。／Tôi no rồi.",""],["のどがかわきました","喉が渇きました","ex","Tôi khát rồi","I'm thirsty.","のどが かわきました。みずを ください。／Khát quá, cho tôi nước.",""],["そうですね","","ex","Đúng vậy nhỉ","I agree with you.","さむいですね。ーそうですね。／Lạnh nhỉ. — Đúng thế.","Đồng tình."],["そうしましょう","","ex","Làm vậy đi","Let's do that.","ひるごはんを たべに いきましょうか。ーええ、そうしましょう。／Đi ăn trưa nhé? — Ừ, đi thôi.","Đồng ý với đề nghị (PDF ghi nhầm そうましょう)."],["ごちゅうもんは？","ご注文は？","ex","Quý khách gọi món gì ạ?","May I take your order?","いらっしゃいませ。ごちゅうもんは？／Xin chào, quý khách gọi gì ạ?",""],["ていしょく","定食","n","Suất ăn định sẵn, cơm suất","set meal","てんぷらていしょくを ください。／Cho tôi suất tempura.",""],["ぎゅうどん","牛丼","n","Cơm thịt bò","bowl of rice topped with beef","ぎゅうどんを ひとつ ください。／Cho một bát cơm bò.",""],["［しょうしょう］おまちください","［少々］お待ちください","ex","Xin vui lòng đợi [một chút]","Please wait [a moment].","しょうしょう おまち ください。／Xin quý khách đợi một chút.","Kính ngữ, nhân viên dùng với khách."],["べつべつに","別々に","adv","Riêng ra, riêng rẽ","separately","べつべつに おねがいします。／Cho chúng tôi tính tiền riêng.",""]],"ref":[["はくぶつかん","博物館","n","Bảo tàng","museum","はくぶつかんへ いきました。／Tôi đã đi bảo tàng.",""],["えいがかん","映画館","n","Rạp chiếu phim","movie theater","えいがかんは えきの ちかくです。／Rạp chiếu phim gần ga.",""],["どうぶつえん","動物園","n","Vườn bách thú","zoo","こどもと どうぶつえんへ いきます。／Tôi đi sở thú với con.",""],["しょくぶつえん","植物園","n","Vườn bách thảo","botanical garden","しょくぶつえんで はなを みました。／Tôi xem hoa ở vườn bách thảo.",""],["おてら","お寺","n","Chùa","temple","ならには ふるい おてらが おおいです。／Ở Nara có nhiều chùa cổ.",""],["きょうかい","教会","n","Nhà thờ","church","にちようびに きょうかいへ いきます。／Chủ nhật tôi đi nhà thờ.",""],["モスク","","n","Đền thờ đạo Hồi","mosque","モスクは どこに ありますか。／Đền thờ đạo Hồi ở đâu?",""],["たいいくかん","体育館","n","Nhà thi đấu, nhà tập thể thao","gymnasium","たいいくかんで バスケットボールを します。／Tôi chơi bóng rổ ở nhà thi đấu.",""],["にゅうこくかんりきょく","入国管理局","n","Cục xuất nhập cảnh","immigration bureau","にゅうこくかんりきょくで ビザの てつづきを します。／Tôi làm thủ tục visa ở Cục xuất nhập cảnh.",""],["こうばん","交番","n","Bốt cảnh sát","police box","みちが わからない とき、こうばんで ききます。／Khi không biết đường, tôi hỏi ở bốt cảnh sát.",""],["ちゅうがっこう","中学校","n","Trường THCS","junior high school","ちゅうがっこうは 3ねんかんです。／Trung học cơ sở học 3 năm.",""],["しょうがっこう","小学校","n","Trường tiểu học","elementary school","むすこは しょうがっこうに いって います。／Con trai tôi đang học tiểu học.",""],["ようちえん","幼稚園","n","Trường mẫu giáo","kindergarten","むすめは ようちえんに かよって います。／Con gái tôi đi mẫu giáo.",""],["にくや","肉屋","n","Cửa hàng thịt","butcher shop","にくやで ぎゅうにくを かいます。／Tôi mua thịt bò ở cửa hàng thịt.",""],["パンや","パン屋","n","Cửa hàng bánh mì","bakery","パンやは あさ 7じから あいて います。／Tiệm bánh mì mở từ 7 giờ sáng.",""],["さかなや","魚屋","n","Cửa hàng cá","fish shop","さかなやで さかなを かいました。／Tôi đã mua cá ở cửa hàng cá.",""],["さかや","酒屋","n","Cửa hàng rượu","liquor store","さかやで ビールを かいます。／Tôi mua bia ở cửa hàng rượu.",""],["やおや","八百屋","n","Cửa hàng rau","greengrocer","やおやで やさいを かいます。／Tôi mua rau ở cửa hàng rau.",""],["コンビニ","","n","Cửa hàng tiện lợi","convenience store","コンビニは 24じかん あいて います。／Cửa hàng tiện lợi mở cửa 24 giờ.",""]],"refTitle":"Trong khu phố","grammar":[{"title":"N が 欲しいです – muốn có","form":"(わたしは) N が ほしいです","explain":"ほしい là tính từ い, diễn tả mong muốn có một thứ gì đó; đối tượng dùng が. Chia như tính từ い: ほしくないです.","examples":[{"s":"わたしは ともだちが ほしいです。","t":"Tôi muốn có bạn."},{"s":"いま なにが いちばん ほしいですか。……くるまが ほしいです。","t":"Bây giờ bạn muốn có gì nhất? – Tôi muốn có ô tô."},{"s":"こどもが ほしいですか。……いいえ、ほしくないです。","t":"Bạn có muốn có con không? – Không, tôi không muốn."}],"tip":"Không dùng ほしい/たい để nói mong muốn của người thứ ba, cũng không dùng để mời: thay vì コーヒーが ほしいですか, hãy nói コーヒーは いかがですか."},{"title":"V (thể ます) たいです – muốn làm","form":"V(bỏ ます) たいです","explain":"Bỏ ます, thêm たいです để nói mình muốn làm gì. Tân ngữ có thể dùng を hoặc が. たい chia như tính từ い: ～たくないです (không muốn).","examples":[{"s":"わたしは おきなわへ いきたいです。","t":"Tôi muốn đi Okinawa."},{"s":"わたしは てんぷらを（が） たべたいです。","t":"Tôi muốn ăn tempura."},{"s":"おなかが いたいですから、なにも たべたくないです。","t":"Vì đau bụng nên tôi không muốn ăn gì."}],"tip":"“Thể ます” = phần động từ trước ます: かいます → かい, たべます → たべ."},{"title":"Nơi chốn へ V(thể ます)／N に 行きます – đi để làm gì","form":"N (nơi chốn) へ V(bỏ ます) に いきます／きます／かえります · N (hành động) に いきます","explain":"に sau thể ます chỉ mục đích của việc đi/đến/về. Với động từ dạng “N します” (かいもの, べんきょう) có thể nói N に いきます. Danh từ là sự kiện (lễ hội, hòa nhạc) + に cũng chỉ mục đích (đi xem, đi dự).","examples":[{"s":"こうべへ インドりょうりを たべに いきます。","t":"Tôi đi Kobe để ăn món Ấn Độ."},{"s":"こうべへ かいものに いきます。","t":"Tôi đi Kobe mua sắm."},{"s":"にほんへ びじゅつの べんきょうに きました。","t":"Tôi đến Nhật để học mỹ thuật."},{"s":"あした きょうとの おまつりに いきます。","t":"Mai tôi đi Kyōto xem lễ hội."}],"tip":""},{"title":"どこか／何か – đâu đó, cái gì đó","form":"どこか (へ) · なにか (を)","explain":"どこか = đâu đó, nơi nào đó; なにか = cái gì đó. Có thể lược へ, を phía sau.","examples":[{"s":"ふゆやすみは どこか[へ] いきましたか。……はい。ほっかいどうへ スキーに いきました。","t":"Nghỉ đông bạn có đi đâu không? – Có, tôi đi Hokkaidō trượt tuyết."},{"s":"のどが かわきましたから、なにか[を] のみたいです。","t":"Tôi khát nên muốn uống cái gì đó."}],"tip":""},{"title":"ご～ – tiền tố kính trọng","form":"ご + N (gốc Hán)","explain":"ご giống お, đặt trước danh từ để tỏ kính trọng, thường dùng với từ gốc Hán: ごちゅうもん (món anh/chị gọi).","examples":[{"s":"ごちゅうもんは？","t":"Anh/chị dùng món gì ạ?"},{"s":"ごかぞくは なんにんですか。","t":"Gia đình anh/chị có mấy người ạ?"}],"tip":""},{"title":"だれでも／なんでも／いつでも／どこでも – bất cứ · bổ sung N5","form":"Từ để hỏi + でも + câu khẳng định","explain":"Từ để hỏi + でも: “bất cứ ai / cái gì / lúc nào / ở đâu” (đều được). Khác từ để hỏi + も + phủ định (Bài 5) và từ để hỏi + か (Bài 13).","examples":[{"s":"いつでも あそびに きて ください。","t":"Lúc nào cũng được, hãy đến chơi nhé."},{"s":"わたしは なんでも たべます。","t":"Tôi ăn được mọi thứ."},{"s":"この しごとは だれでも できます。","t":"Công việc này ai cũng làm được."}],"tip":""}]},{"n":14,"title":"Bài 14","jp":"みどり町までお願いします","sub":"Thể て · nhờ vả ～てください","rows":[["つけます","点けます","v2","Bật","turn on","でんきを つけます。／Bật điện.","Nhóm II · thể từ điển: つける"],["けします","消します","v1","Tắt","turn off","でんきを けして ください。／Hãy tắt điện.","Nhóm I · thể từ điển: けす · còn nghĩa “xoá”."],["あけます","開けます","v2","Mở","open","まどを あけましょうか。／Tôi mở cửa sổ nhé?","Nhóm II · thể từ điển: あける"],["しめます","閉めます","v2","Đóng","close, shut","ドアを しめて ください。／Hãy đóng cửa.","Nhóm II · thể từ điển: しめる"],["いそぎます","急ぎます","v1","Vội, gấp","hurry","いそいで ください。／Hãy nhanh lên.","Nhóm I · thể từ điển: いそぐ · thể て: いそいで."],["まちます","待ちます","v1","Đợi","wait","ちょっと まって ください。／Đợi một chút.","Nhóm I · thể từ điển: まつ · thể て: まって."],["とめます","止めます","v2","Dừng, đỗ (xe)","stop, park","ここに くるまを とめないで ください。／Đừng đỗ xe ở đây.","Nhóm II · thể từ điển: とめる"],["まがります［みぎへ～］","曲がります","v1","Rẽ [phải]","turn [to the right]","つぎの かどを みぎへ まがって ください。／Rẽ phải ở góc tiếp theo.","Nhóm I · thể từ điển: まがる"],["もちます","持ちます","v1","Cầm, mang","hold, carry","にもつを もちましょうか。／Tôi cầm đồ giúp nhé?","Nhóm I · thể từ điển: もつ"],["とります","取ります","v1","Lấy","take, pass","しおを とって ください。／Lấy giúp tôi lọ muối.","Nhóm I · thể từ điển: とる"],["てつだいます","手伝います","v1","Giúp (việc)","help (with a task)","てつだいましょうか。／Tôi giúp nhé?","Nhóm I · thể từ điển: てつだう"],["よびます","呼びます","v1","Gọi","call","タクシーを よんで ください。／Gọi taxi giúp tôi.","Nhóm I · thể từ điển: よぶ · thể て: よんで."],["はなします","話します","v1","Nói chuyện","speak, talk","ゆっくり はなして ください。／Hãy nói chậm.","Nhóm I · thể từ điển: はなす"],["みせます","見せます","v2","Cho xem","show","パスポートを みせて ください。／Cho xem hộ chiếu.","Nhóm II · thể từ điển: みせる"],["おしえます［じゅうしょを～］","教えます","v2","Cho biết [địa chỉ]","tell [an address]","じゅうしょを おしえて ください。／Cho tôi biết địa chỉ.","Nhóm II · thể từ điển: おしえる"],["はじめます","始めます","v2","Bắt đầu","start, begin","かいぎを はじめましょう。／Bắt đầu họp thôi.","Nhóm II · thể từ điển: はじめる"],["ふります［あめが～］","降ります","v1","Rơi [mưa]","rain, fall","あめが ふって います。／Trời đang mưa.","Nhóm I · thể từ điển: ふる"],["コピーします","","v3","Sao chụp, photocopy","copy","この しりょうを コピーして ください。／Photo tài liệu này giúp tôi.","Nhóm III"],["エアコン","","n","Điều hoà","air conditioner","エアコンを つけましょうか。／Bật điều hoà nhé?",""],["パスポート","","n","Hộ chiếu","passport","パスポートを わすれました。／Tôi quên hộ chiếu.",""],["なまえ","名前","n","Tên","name","ここに なまえを かいて ください。／Hãy viết tên vào đây.",""],["じゅうしょ","住所","n","Địa chỉ","address","じゅうしょを かいて ください。／Hãy viết địa chỉ.",""],["ちず","地図","n","Bản đồ","map","ちずを かいて ください。／Hãy vẽ bản đồ giúp tôi.",""],["しお","塩","n","Muối","salt","しおを とって ください。／Lấy giúp lọ muối.",""],["さとう","砂糖","n","Đường","sugar","コーヒーに さとうを いれますか。／Có cho đường vào cà phê không?",""],["よみかた","読み方","n","Cách đọc","how to read","この かんじの よみかたを おしえて ください。／Hãy chỉ tôi cách đọc chữ Hán này.",""],["～かた","～方","sf","Cách ~","how to ~, way of ~ing","つかいかたを おしえて ください。／Hãy chỉ cách dùng.","Gốc động từ thể ます + かた."],["ゆっくり","","adv","Chậm rãi, thong thả","slowly, leisurely","もう すこし ゆっくり はなして ください。／Hãy nói chậm hơn chút.",""],["すぐ","直ぐ","adv","Ngay lập tức","immediately","すぐ きて ください。／Hãy đến ngay.",""],["また","又","adv","Lại, lần nữa","again","また きて ください。／Lại đến nhé.",""],["あとで","後で","adv","Sau, lát nữa","later","あとで でんわします。／Lát nữa tôi gọi.",""],["もうすこし","もう少し","adv","Thêm một chút nữa","a little more","もう すこし まって ください。／Hãy đợi thêm chút.",""],["もう～","","adv","Thêm ~","~ more, another ~","もう いちど いって ください。／Hãy nói lại lần nữa.","Khác もう (đã) ở Bài 7."],["いいですよ","","ex","Được thôi, được ạ","Sure. / Certainly.","てつだいましょうか。ーいいですよ。／Giúp nhé? — Được.","Hoặc chấp nhận lời nhờ."],["さあ","","it","Nào","right (encouraging some action)","さあ、いきましょう。／Nào, đi thôi.",""],["あれ？","","it","Ơ? Ủa?","Oh! (in surprise or wonder)","あれ？ かぎが ありません。／Ơ? Không thấy chìa khoá.",""],["しんごうをみぎへまがってください","信号を右へ曲がってください","ex","Hãy rẽ phải ở đèn tín hiệu","Turn right at the signal.","つぎの しんごうを みぎへ まがって ください。／Hãy rẽ phải ở đèn tiếp theo.","Nói với tài xế taxi."],["まっすぐ","真っ直ぐ","adv","Thẳng","straight","まっすぐ いって ください。／Hãy đi thẳng.",""],["これでおねがいします","これでお願いします","ex","Tính tiền bằng cái này nhé","I'd like to pay with this.","1まんえんで おねがいします。／Tôi trả bằng tờ 10.000 yên.","PDF ghi sai chữ Hán 寝 → đúng là 願."],["おつり","お釣り","n","Tiền thừa, tiền thối lại","change","はい、おつりです。／Vâng, tiền thừa đây ạ.",""]],"ref":[["きっぷうりば","切符売り場","n","Chỗ bán vé","ticket office","きっぷうりばは どこですか。／Chỗ bán vé ở đâu?",""],["じどうけんばいき","自動券売機","n","Máy bán vé tự động","ticket machine","じどうけんばいきで きっぷを かいます。／Tôi mua vé ở máy bán vé tự động.",""],["せいさんき","精算機","n","Máy thanh toán tiền vé còn thiếu","fare adjustment machine","せいさんきで おかねを はらって ください。／Hãy trả tiền ở máy thanh toán.",""],["かいさつぐち","改札口","n","Cửa soát vé","ticket gate","かいさつぐちで まって います。／Tôi đợi ở cửa soát vé.",""],["でぐち","出口","n","Cửa ra","exit","でぐちは あちらです。／Cửa ra ở phía kia.",""],["いりぐち","入口","n","Cửa vào","entrance","いりぐちは こちらです。／Cửa vào ở phía này.",""],["ひがしぐち","東口","n","Cửa Đông","east exit","ひがしぐちで あいましょう。／Chúng ta gặp nhau ở cửa Đông nhé.",""],["にしぐち","西口","n","Cửa Tây","west exit","にしぐちを でて ください。／Hãy ra cửa Tây.",""],["みなみぐち","南口","n","Cửa Nam","south exit","みなみぐちの まえに バスていが あります。／Trước cửa Nam có bến xe buýt.",""],["きたぐち","北口","n","Cửa Bắc","north exit","きたぐちは どちらですか。／Cửa Bắc ở phía nào?",""],["ちゅうおうぐち","中央口","n","Cửa Trung tâm","central exit","ちゅうおうぐちで まって います。／Tôi đợi ở cửa Trung tâm.",""],["ホーム","","n","Sân ga","platform","3ばんせんの ホームで まって ください。／Hãy đợi ở sân ga số 3.","Đầy đủ: プラットホーム"],["ばいてん","売店","n","Quầy bán hàng, ki-ốt","kiosk","ばいてんで しんぶんを かいます。／Tôi mua báo ở ki-ốt.",""],["コインロッカー","","n","Tủ đồ thuê bằng tiền xu","coin locker","にもつを コインロッカーに いれます。／Tôi để hành lý vào tủ gửi đồ.",""],["タクシーのりば","タクシー乗り場","n","Điểm lên xe tắc-xi","taxi stand","タクシーのりばは えきの まえです。／Điểm lên taxi ở trước ga.",""],["バスターミナル","","n","Bến xe buýt","bus terminal","バスターミナルから バスに のります。／Tôi lên xe buýt ở bến.",""],["バスてい","バス停","n","Điểm lên xuống xe buýt","bus stop","バスていで バスを まちます。／Tôi đợi xe buýt ở điểm dừng.",""],["かいそく","快速","n","(Tàu) nhanh","rapid train","かいそくに のりましょう。／Mình lên tàu nhanh đi.",""],["じゅんきゅう","準急","n","(Tàu) bán tốc hành","semi-express","じゅんきゅうは つぎの えきに とまりますか。／Tàu bán tốc hành có dừng ở ga sau không?",""],["～はつ","～発","sf","Xuất phát từ ～ / lúc ～","departing from","9じはつの でんしゃに のります。／Tôi lên chuyến tàu khởi hành lúc 9 giờ.",""],["～ちゃく","～着","sf","Đến ～ / lúc ～","arriving at","10じちゃくです。／Đến nơi lúc 10 giờ.",""],["～いき","～行き","sf","Đi ～ (hướng đến)","bound for","とうきょういきの でんしゃは なんばんせんですか。／Tàu đi Tōkyō ở đường ray số mấy?","Đọc ゆき hoặc いき"],["ていきけん","定期券","n","Vé tháng","commuter pass","ていきけんで かいしゃへ いきます。／Tôi đi làm bằng vé tháng.",""],["かいすうけん","回数券","n","Vé tập (giảm giá khi đi nhiều)","coupon tickets","かいすうけんは すこし やすいです。／Vé tập rẻ hơn một chút.",""],["かたみち","片道","n","Một chiều","one way","かたみちの きっぷを ください。／Cho tôi vé một chiều.",""],["おうふく","往復","n","Khứ hồi, đi và về","round trip","おうふくで いくらですか。／Khứ hồi bao nhiêu tiền?",""]],"refTitle":"Ga","grammar":[{"title":"Các nhóm động từ","form":"Nhóm I: ～い・ます (かきます) · Nhóm II: ～え・ます (たべます; vài từ ～い・ます: みます) · Nhóm III: します, N + します, きます","explain":"Động từ tiếng Nhật biến đổi đuôi để ghép với các mẫu câu, nên cần biết động từ thuộc nhóm nào.\n\nNhóm I: âm ngay trước ます thuộc hàng い (か**き**ます, の**み**ます). Nhóm II: hầu hết có âm trước ます thuộc hàng え (た**べ**ます, み**せ**ます), một số ít thuộc hàng い (みます, おきます, かります). Nhóm III: します, các động từ “danh từ + します” (べんきょうします) và きます.","examples":[{"s":"かきます (nhóm I) → かいて","t":"viết"},{"s":"たべます (nhóm II) → たべて","t":"ăn"},{"s":"きます (nhóm III) → きて","t":"đến"}],"tip":"Động từ nhóm II có đuôi hàng い phải học thuộc: みます, おきます, あびます, できます, かります, たります, おります, います…"},{"title":"Thể て của động từ","form":"Nhóm I: い・ち・り→って · み・び・に→んで · き→いて · ぎ→いで · し→して · Nhóm II: bỏ ます + て · Nhóm III: して／きて","explain":"Thể て là dạng kết thúc bằng て/で, dùng trong rất nhiều mẫu câu.\n\nNhóm I đổi theo âm trước ます: かいます→かって, まちます→まって, かえります→かえって; のみます→のんで, よびます→よんで, しにます→しんで; かきます→かいて; いそぎます→いそいで; かします→かして. Ngoại lệ: いきます→いって.\n\nNhóm II: bỏ ます thêm て (たべます→たべて, みます→みて). Nhóm III: します→して, きます→きて.","examples":[{"s":"まって ください。","t":"Xin hãy đợi."},{"s":"ほんを よんで います。","t":"Tôi đang đọc sách."},{"s":"ここに なまえを かいて ください。","t":"Hãy viết tên vào đây."}],"tip":"Sai: いきます → いいて. Đúng: いって."},{"title":"V て ください – hãy, xin hãy","form":"V て ください","explain":"Dùng để nhờ vả, chỉ thị hoặc khuyến khích người nghe làm gì. Khi nhờ vả nên thêm すみませんが ở đầu cho lịch sự.","examples":[{"s":"すみませんが、この かんじの よみかたを おしえて ください。","t":"Xin lỗi, hãy chỉ cho tôi cách đọc chữ Hán này. (nhờ vả)"},{"s":"ボールペンで なまえを かいて ください。","t":"Hãy viết tên bằng bút bi. (chỉ thị)"},{"s":"どうぞ たくさん たべて ください。","t":"Xin mời ăn nhiều vào nhé. (khuyến khích)"}],"tip":""},{"title":"V て います – đang làm","form":"V て います","explain":"Diễn tả hành động đang diễn ra tại thời điểm nói. Phủ định: ～て いません.","examples":[{"s":"ミラーさんは いま でんわを かけて います。","t":"Anh Miller đang gọi điện thoại."},{"s":"いま あめが ふって いますか。……はい、ふって います。","t":"Trời đang mưa à? – Vâng, đang mưa."}],"tip":""},{"title":"V (thể ます) ましょうか – để tôi… nhé","form":"V(bỏ ます) ましょうか","explain":"Người nói đề nghị làm giúp người nghe việc gì: “Tôi… giúp anh nhé?”. Nhận: ええ、お願いします; từ chối lịch sự: いいえ、けっこうです.","examples":[{"s":"かさを かしましょうか。……すみません。おねがいします。","t":"Tôi cho anh mượn ô nhé? – Cảm ơn anh. Nhờ anh."},{"s":"にもつを もちましょうか。……いいえ、けっこうです。","t":"Tôi mang hành lý giúp chị nhé? – Không, tôi tự mang được ạ."},{"s":"あしたも きましょうか。……ええ、10じに きて ください。","t":"Mai tôi lại đến nhé? – Vâng, mai anh đến lúc 10 giờ nhé."}],"tip":""},{"title":"N が V – miêu tả hiện tượng","form":"N が V","explain":"Khi miêu tả nguyên vẹn một hiện tượng nhìn thấy, nghe thấy, hoặc truyền đạt khách quan một sự việc, chủ ngữ đánh dấu bằng が.","examples":[{"s":"あめが ふって います。","t":"Trời đang mưa."},{"s":"ミラーさんが いませんね。","t":"Anh Miller không có ở đây nhỉ."}],"tip":""},{"title":"すみませんが – mở đầu lời nhờ","form":"すみませんが、～ · しつれいですが、～","explain":"が ở đây không mang nghĩa đối lập “nhưng” mà để mở đầu câu nhẹ nhàng khi nhờ vả, hỏi thông tin.","examples":[{"s":"すみませんが、しおを とって ください。","t":"Xin lỗi, anh lấy giúp tôi lọ muối."},{"s":"しつれいですが、おなまえは？","t":"Xin lỗi, anh tên gì ạ?"}],"tip":""}]},{"n":15,"title":"Bài 15","jp":"ご家族は？","sub":"～てもいいです · ～ています (trạng thái)","rows":[["たちます","立ちます","v1","Đứng","stand up","たって ください。／Hãy đứng lên.","Nhóm I · thể từ điển: たつ"],["すわります","座ります","v1","Ngồi","sit down","ここに すわっても いいですか。／Ngồi đây được không?","Nhóm I · thể từ điển: すわる"],["つかいます","使います","v1","Sử dụng","use","この パソコンを つかっても いいですか。／Dùng máy tính này được không?","Nhóm I · thể từ điển: つかう"],["おきます","置きます","v1","Đặt, để","put","ここに にもつを おかないで ください。／Đừng để hành lý ở đây.","Nhóm I · thể từ điển: おく"],["つくります","作ります／造ります","v1","Làm, chế tạo","make, produce","この こうじょうで くるまを つくって います。／Nhà máy này sản xuất ô tô.","Nhóm I · thể từ điển: つくる"],["うります","売ります","v1","Bán","sell","あの みせで くつを うって います。／Cửa hàng kia có bán giày.","Nhóm I · thể từ điển: うる"],["しります","知ります","v1","Biết","get to know","かれの でんわばんごうを しって いますか。／Bạn có biết số điện thoại anh ấy không?","Nhóm I · thể từ điển: しる · phủ định: しりません (không phải しっていません)."],["すみます","住みます","v1","Sống, cư trú","live","おおさかに すみます。／Sống ở Osaka.","Nhóm I · thể từ điển: すむ · thường dùng すんでいます."],["けんきゅうします","研究します","v3","Nghiên cứu","do research","だいがくで けいざいを けんきゅうして います。／Đang nghiên cứu kinh tế ở đại học.","Nhóm III"],["しっています","知っています","v1","Biết (đang biết)","know","ミラーさんを しって いますか。ーはい、しって います。／Bạn biết anh Miller không? — Có.","Trả lời không biết: しりません."],["すんでいます［おおさかに～］","住んでいます","v1","Đang sống [ở Osaka]","live [in Osaka]","わたしは おおさかに すんで います。／Tôi đang sống ở Osaka.",""],["しりょう","資料","n","Tài liệu","materials, data","しりょうを もらっても いいですか。／Tôi lấy tài liệu được không?",""],["カタログ","","n","Ca-ta-lô","catalog","カタログを みせて ください。／Cho xem ca-ta-lô.",""],["じこくひょう","時刻表","n","Bảng giờ tàu chạy","timetable","じこくひょうを もらっても いいですか。／Tôi lấy bảng giờ tàu được không?",""],["ふく","服","n","Quần áo","clothes","あたらしい ふくを かいました。／Đã mua quần áo mới.",""],["せいひん","製品","n","Sản phẩm","products","この かいしゃの せいひんは いいです。／Sản phẩm của công ty này tốt.",""],["ソフト","","n","Phần mềm","software","コンピューターの ソフトを つくって います。／Đang làm phần mềm máy tính.",""],["せんもん","専門","n","Chuyên môn","speciality, field of study","せんもんは なんですか。／Chuyên ngành của bạn là gì?",""],["はいしゃ","歯医者","n","Nha sĩ; phòng khám nha khoa","dentist, dentist's","はいしゃへ いきます。／Đi nha sĩ.",""],["とこや","床屋","n","Hiệu cắt tóc nam","barber, barber's","とこやで かみを きります。／Cắt tóc ở tiệm cắt tóc.",""],["プレイガイド","","n","Đại lý bán vé (kịch, hoà nhạc)","(theatre) ticket agency","プレイガイドで チケットを かいます。／Mua vé ở đại lý vé.",""],["どくしん","独身","n","Độc thân","single, unmarried","わたしは どくしんです。／Tôi độc thân.",""],["とくに","特に","adv","Đặc biệt là","especially","スポーツが すきです。とくに サッカーが すきです。／Thích thể thao, đặc biệt là bóng đá.",""],["おもいだします","思い出します","v1","Nhớ lại","remember, recollect","かぞくを おもいだします。／Nhớ đến gia đình.","Nhóm I · thể từ điển: おもいだす"],["ごかぞく","ご家族","n","Gia đình (người khác)","your family","ごかぞくは どこに いますか。／Gia đình bạn ở đâu?",""],["いらっしゃいます","","v1","Có, ở (kính ngữ của います)","be (honorific of います)","せんせいは いらっしゃいますか。／Thầy giáo có ở đây không ạ?","Tôn kính ngữ · thể ます đặc biệt (gốc いらっしゃる)."],["こうこう","高校","n","Trường cấp 3","senior high school","おとうとは こうこうせいです。／Em trai tôi là học sinh cấp 3.","Viết tắt của こうとうがっこう."]],"ref":[["しょくぎょう","職業","n","Nghề nghiệp","occupation","しょくぎょうは なんですか。／Nghề nghiệp của bạn là gì?",""],["こうむいん","公務員","n","Công chức","civil servant","ちちは こうむいんです。／Bố tôi là công chức.",""],["えきいん","駅員","n","Nhân viên nhà ga","station staff","えきいんに みちを ききました。／Tôi đã hỏi đường nhân viên nhà ga.",""],["ゆうびんきょくいん","郵便局員","n","Nhân viên bưu điện","post office worker","ゆうびんきょくいんに にもつを わたします。／Tôi đưa hàng cho nhân viên bưu điện.",""],["てんいん","店員","n","Nhân viên cửa hàng","shop clerk","てんいんに ききましょう。／Hỏi nhân viên cửa hàng đi.",""],["ちょうりし","調理師","n","Đầu bếp","cook, chef","あには ちょうりしです。／Anh tôi là đầu bếp.",""],["りようし","理容師","n","Thợ cắt tóc (nam)","barber","りようしに かみを きって もらいます。／Tôi nhờ thợ cắt tóc.",""],["びようし","美容師","n","Thợ làm tóc, mỹ viện gia","hairdresser","あねは びようしです。／Chị tôi là thợ làm tóc.",""],["べんごし","弁護士","n","Luật sư","lawyer","べんごしに そうだんしました。／Tôi đã hỏi ý kiến luật sư.",""],["かんごし","看護師","n","Y tá, điều dưỡng","nurse","かんごしは びょういんで はたらいて います。／Y tá làm việc ở bệnh viện.",""],["うんてんしゅ","運転手","n","Tài xế","driver","タクシーの うんてんしゅです。／Tôi là tài xế taxi.",""],["けいさつかん","警察官","n","Cảnh sát","police officer","けいさつかんに ききました。／Tôi đã hỏi cảnh sát.",""],["がいこうかん","外交官","n","Nhà ngoại giao","diplomat","かれは がいこうかんです。／Anh ấy là nhà ngoại giao.",""],["せいじか","政治家","n","Chính khách, nhà chính trị","politician","せいじかに なりたいです。／Tôi muốn trở thành chính khách.",""],["がか","画家","n","Họa sĩ","painter","ゆうめいな がかの えを みました。／Tôi đã xem tranh của họa sĩ nổi tiếng.",""],["さっか","作家","n","Nhà văn","writer","すきな さっかは だれですか。／Nhà văn bạn thích là ai?",""],["おんがくか","音楽家","n","Nhạc sĩ","musician","おんがくかの ともだちが います。／Tôi có bạn là nhạc sĩ.",""],["けんちくか","建築家","n","Kiến trúc sư","architect","この たてものは ゆうめいな けんちくかが つくりました。／Tòa nhà này do kiến trúc sư nổi tiếng xây.",""],["デザイナー","","n","Nhà thiết kế","designer","デザイナーの しごとは おもしろいです。／Công việc nhà thiết kế thú vị.",""],["ジャーナリスト","","n","Nhà báo","journalist","ジャーナリストに なりたいです。／Tôi muốn trở thành nhà báo.",""],["かしゅ","歌手","n","Ca sĩ","singer","すきな かしゅは だれですか。／Ca sĩ bạn thích là ai?",""],["はいゆう","俳優","n","Diễn viên","actor","あの はいゆうは にんきが あります。／Diễn viên đó rất được yêu thích.",""],["スポーツせんしゅ","スポーツ選手","n","Vận động viên","athlete","スポーツせんしゅに なりたいです。／Tôi muốn trở thành vận động viên.",""]],"refTitle":"Nghề nghiệp","grammar":[{"title":"V て も いいですか – có được không","form":"V て も いいですか · trả lời: ええ、いいですよ／すみません、ちょっと……","explain":"Xin phép làm việc gì. Đồng ý: ええ、[V ても] いいですよ. Từ chối nhẹ nhàng: すみません、ちょっと…… (kèm lý do). Từ chối dứt khoát kiểu cấm: いいえ、いけません.","examples":[{"s":"しゃしんを とっても いいですか。","t":"Tôi chụp ảnh có được không?"},{"s":"ここで たばこを すっても いいですか。……すみません、ちょっと……。のどが いたいですから。","t":"Tôi hút thuốc ở đây được không? – Xin lỗi, không được đâu ạ. Tôi đang đau họng."}],"tip":""},{"title":"V て は いけません – không được","form":"V て は いけません","explain":"Diễn tả sự cấm đoán: “không được làm…”. Không dùng để nói với người trên.","examples":[{"s":"ここで たばこを すっては いけません。きんえんですから。","t":"Không được hút thuốc ở đây. Vì đây là khu cấm hút thuốc."},{"s":"ここに はいっては いけません。","t":"Không được vào đây."}],"tip":"Với cấp trên nên nói tránh: すみません、ここは きんえんなんです."},{"title":"V て います – trạng thái, thói quen, nghề nghiệp","form":"V て います","explain":"Ngoài “đang làm” (Bài 14), ～ています còn diễn tả: ① trạng thái là kết quả của hành động (đã kết hôn, đang sống ở, biết, có); ② hành động lặp lại lâu dài, nghề nghiệp, tình cảnh.\n\nしって います phủ định là しりません (không phải しって いません). もって います vừa là “đang cầm” vừa là “có”.","examples":[{"s":"わたしは けっこんして います。","t":"Tôi đã lập gia đình."},{"s":"わたしは おおさかに すんで います。","t":"Tôi sống ở Ōsaka."},{"s":"しやくしょの でんわばんごうを しって いますか。……いいえ、しりません。","t":"Bạn có biết số điện thoại văn phòng thành phố không? – Không, tôi không biết."},{"s":"IMCは コンピューターソフトを つくって います。","t":"Công ty IMC sản xuất phần mềm máy tính."},{"s":"いもうとは だいがくで べんきょうして います。","t":"Em gái tôi đang học đại học."}],"tip":"Sai: しって いません. Đúng: しりません."},{"title":"N に V – điểm đến của hành động","form":"N (nơi chốn) に はいります／すわります／のります／のぼります／つきます","explain":"Với các động từ như vào, ngồi, lên (xe), leo, đến…, に chỉ nơi mà chủ thể có mặt sau khi làm hành động.","examples":[{"s":"ここに はいっては いけません。","t":"Không được vào đây."},{"s":"ここに すわっても いいですか。","t":"Tôi ngồi đây được không?"},{"s":"きょうとえきから 16ばんの バスに のって ください。","t":"Hãy lên xe buýt số 16 từ ga Kyōto."}],"tip":""},{"title":"N1 に N2 を V – đặt vật vào đâu","form":"N1 (nơi chốn) に N2 を おきます／とめます／かきます…","explain":"に chỉ chỗ mà N2 có mặt sau khi hành động kết thúc: đỗ xe ở đâu, viết vào đâu.","examples":[{"s":"ここに くるまを とめて ください。","t":"Hãy đỗ xe ở đây."},{"s":"ここに じゅうしょを かいて ください。","t":"Hãy viết địa chỉ vào đây."}],"tip":""}]},{"n":16,"title":"Bài 16","jp":"使い方を教えてください","sub":"Nối câu bằng thể て · cơ thể · ATM","rows":[["のります［でんしゃに～］","乗ります","v1","Lên, đi [tàu]","ride, get on [a train]","えきで でんしゃに のります。／Lên tàu ở ga.","Nhóm I · thể từ điển: のる · phương tiện dùng に."],["おります［でんしゃを～］","降ります","v2","Xuống [tàu]","get off [a train]","つぎの えきで でんしゃを おります。／Xuống tàu ở ga tiếp theo.","Nhóm II · thể từ điển: おりる · dùng を."],["のりかえます","乗り換えます","v2","Đổi tàu, chuyển xe","change (trains, etc.)","うめだで ちかてつに のりかえます。／Chuyển sang tàu điện ngầm ở Umeda.","Nhóm II · thể từ điển: のりかえる"],["あびます［シャワーを～］","浴びます","v2","Tắm [vòi sen]","take [a shower]","あさ シャワーを あびます。／Sáng tắm vòi sen.","Nhóm II · thể từ điển: あびる"],["いれます","入れます","v2","Cho vào, bỏ vào","put in, insert","カードを いれて ください。／Hãy đưa thẻ vào.","Nhóm II · thể từ điển: いれる"],["だします","出します","v1","Lấy ra, rút (tiền)","take out, withdraw","ぎんこうで おかねを だします。／Rút tiền ở ngân hàng.","Nhóm I · thể từ điển: だす"],["はいります［だいがくに～］","入ります","v1","Vào [đại học]","enter [university]","らいねん だいがくに はいります。／Năm sau vào đại học.","Nhóm I · thể từ điển: はいる"],["でます［だいがくを～］","出ます","v2","Tốt nghiệp [đại học]","graduate from [university]","だいがくを でてから、かいしゃに はいりました。／Tốt nghiệp đại học xong thì vào công ty.","Nhóm II · thể từ điển: でる"],["やめます［かいしゃを～］","辞めます","v2","Bỏ, nghỉ [việc công ty]","quit [a company], stop, give up","かいしゃを やめました。／Đã nghỉ việc ở công ty.","Nhóm II · thể từ điển: やめる"],["おします","押します","v1","Bấm, ấn","press, push","この ボタンを おして ください。／Hãy bấm nút này.","Nhóm I · thể từ điển: おす"],["わかい","若い","ai","Trẻ","young","せんせいは わかいです。／Thầy giáo trẻ.",""],["ながい","長い","ai","Dài","long","かのじょは かみが ながいです。／Cô ấy tóc dài.",""],["みじかい","短い","ai","Ngắn","short","なつやすみは みじかいです。／Kỳ nghỉ hè ngắn.",""],["あかるい","明るい","ai","Sáng; vui tươi","bright, light","この へやは あかるいです。／Phòng này sáng sủa.",""],["くらい","暗い","ai","Tối; u ám","dark","そとは もう くらいです。／Bên ngoài đã tối.",""],["せがたかい","背が高い","ai","Cao (người)","tall (person)","ミラーさんは せが たかいです。／Anh Miller cao.","Thấp: せが ひくい."],["あたまがいい","頭がいい","ai","Thông minh","clever, smart","かれは あたまが いいです。／Anh ấy thông minh.",""],["からだ","体","n","Cơ thể","body","からだに きを つけて ください。／Hãy giữ gìn sức khoẻ.",""],["あたま","頭","n","Đầu","head","あたまが いたいです。／Tôi đau đầu.",""],["かみ","髪","n","Tóc","hair","かみを きりました。／Đã cắt tóc.",""],["かお","顔","n","Mặt","face","かおを あらいます。／Rửa mặt.",""],["め","目","n","Mắt","eye","マリアさんは めが おおきいです。／Chị Maria mắt to.",""],["みみ","耳","n","Tai","ear","うさぎは みみが ながいです。／Thỏ tai dài.",""],["くち","口","n","Miệng","mouth","くちを あけて ください。／Hãy há miệng.",""],["は","歯","n","Răng","tooth","まいばん はを みがきます。／Tối nào cũng đánh răng.",""],["おなか","お腹","n","Bụng","stomach","おなかが いたいです。／Tôi đau bụng.",""],["あし","足","n","Chân","leg, foot","ぞうは あしが ふといです。／Voi chân to.",""],["サービス","","n","Dịch vụ","service","この ホテルは サービスが いいです。／Khách sạn này dịch vụ tốt.",""],["ジョギング","","n","Chạy bộ","jogging","まいあさ ジョギングを します。／Sáng nào cũng chạy bộ.","～をします: chạy bộ."],["シャワー","","n","Vòi hoa sen","shower","シャワーを あびてから ねます。／Tắm xong thì ngủ.",""],["みどり","緑","n","Màu xanh lá; cây xanh","green, greenery","この まちは みどりが おおいです。／Thành phố này nhiều cây xanh.",""],["［お］てら","［お］寺","n","Chùa","Buddhist temple","きょうとには おてらが たくさん あります。／Kyoto có nhiều chùa.",""],["じんじゃ","神社","n","Đền thờ Thần đạo","Shinto shrine","おしょうがつに じんじゃへ いきます。／Tết đi đền.",""],["りゅうがくせい","留学生","n","Du học sinh","foreign student","わたしは りゅうがくせいです。／Tôi là du học sinh.",""],["～ばん","～番","sf","Số ~","number ~","1ばんの バスに のって ください。／Hãy đi xe buýt số 1.",""],["どうやって","","q","Làm thế nào, bằng cách nào","in what way, how","だいがくまで どうやって いきますか。／Đến trường đại học đi thế nào?",""],["どの～","","q","~ nào (trong 3 thứ trở lên)","which ~ (of three or more)","どの ひとが ミラーさんですか。／Người nào là anh Miller?","Luôn đi kèm danh từ."],["［いいえ、］まだまだです","","ex","[Không,] tôi còn kém lắm","[No,] I still have a long way to go.","にほんごが じょうずですね。ーいいえ、まだまだです。／Tiếng Nhật giỏi nhỉ. — Không, tôi còn kém lắm.","Khiêm tốn khi được khen."],["おひきだしですか","お引き出しですか","ex","Quý khách rút tiền phải không?","Are you making a withdrawal?","おひきだしですか。ーはい。／Quý khách rút tiền ạ? — Vâng.","Màn hình ATM."],["まず","先ず","adv","Trước hết, đầu tiên","first of all","まず カードを いれて ください。／Trước tiên hãy đưa thẻ vào.",""],["キャッシュカード","","n","Thẻ rút tiền","cash card","キャッシュカードを わすれました。／Tôi quên thẻ ATM.",""],["あんしょうばんごう","暗証番号","n","Mã số bí mật (PIN)","PIN","あんしょうばんごうを おして ください。／Hãy bấm mã PIN.",""],["つぎに","次に","adv","Tiếp theo","next","つぎに きんがくを おして ください。／Tiếp theo hãy bấm số tiền.",""],["きんがく","金額","n","Số tiền","amount of money","きんがくを かくにんして ください。／Hãy xác nhận số tiền.",""],["かくにん","確認","n","Xác nhận","confirmation","かくにんの ボタンを おします。／Bấm nút xác nhận.","～します: xác nhận."],["ボタン","","n","Nút bấm","button","あおい ボタンを おして ください。／Hãy bấm nút xanh.",""]],"ref":[["おあずけいれ","お預け入れ","n","Gửi tiền vào tài khoản","deposit","おあずけいれの ボタンを おします。／Ấn nút gửi tiền.","Thường đọc kèm お: おあずけいれ"],["おふりこみ","お振り込み","n","Chuyển tiền vào tài khoản người khác","bank transfer","やちんを ふりこみます。／Tôi chuyển khoản tiền nhà.",""],["おふりかえ","お振り替え","n","Chuyển khoản (giữa các tài khoản)","account transfer","ふりかえの てつづきを します。／Tôi làm thủ tục chuyển khoản.",""],["おひきだし","お引き出し","n","Rút tiền","withdrawal","おひきだしを おして ください。／Hãy ấn nút rút tiền.",""],["つうちょうきにゅう","通帳記入","n","Ghi sao kê vào sổ","passbook update","つうちょうきにゅうを します。／Tôi in sao kê vào sổ.",""],["ざんだかしょうかい","残高照会","n","Kiểm tra số dư","balance inquiry","ざんだかしょうかいで おかねを かくにんします。／Tôi kiểm tra số dư.",""],["つうちょう","通帳","n","Sổ ngân hàng","bankbook","つうちょうを わすれました。／Tôi quên sổ ngân hàng.",""]],"refTitle":"Cách sử dụng máy rút tiền tự động","grammar":[{"title":"Nối câu bằng thể て","form":"V1 て、V2 て、V3 · Adjい→くて · Adjな／N→で","explain":"Thể て nối nhiều câu thành một. Với động từ: các hành động liên tiếp theo đúng thứ tự xảy ra; thì của cả câu do động từ cuối quyết định.\n\nTính từ い: bỏ い thêm くて (いい → よくて). Tính từ な và danh từ: thêm で.\n\nKhi nối tính từ cùng chủ ngữ, hai tính chất phải cùng chiều đánh giá; trái chiều thì dùng が (Bài 8).","examples":[{"s":"あさ ジョギングを して、シャワーを あびて、かいしゃへ いきます。","t":"Buổi sáng tôi chạy bộ, tắm rồi đến công ty."},{"s":"ミラーさんは わかくて、げんきです。","t":"Anh Miller trẻ và khỏe mạnh."},{"s":"ならは しずかで、きれいな まちです。","t":"Nara là thành phố yên tĩnh và đẹp."},{"s":"カリナさんは インドネシアじんで、ふじだいがくの りゅうがくせいです。","t":"Chị Karina là người Indonesia và là lưu học sinh Đại học Fuji."}],"tip":"Sai: この へやは せまくて、きれいです. Đúng: せまいですが、きれいです."},{"title":"V1 て から、V2 – sau khi","form":"V1 て から、V2","explain":"V2 diễn ra sau khi V1 kết thúc; V1 thường là bước chuẩn bị cho V2. Thì của câu do V2 quyết định. Chủ ngữ của mệnh đề ～てから dùng が.","examples":[{"s":"おかねを いれてから、ボタンを おして ください。","t":"Sau khi cho tiền vào thì ấn nút."},{"s":"もう ひるごはんを たべましたか。……この しごとが おわってから、たべます。","t":"Anh ăn trưa chưa? – Làm xong việc này tôi mới ăn."}],"tip":""},{"title":"N1 は N2 が Adj – N1 có N2 thế nào","form":"N1 は N2 が Adj です","explain":"Miêu tả N1 (chủ đề) có đặc điểm “N2 thì Adj”: Osaka – đồ ăn ngon; chị Maria – tóc dài.","examples":[{"s":"おおさかは たべものが おいしいです。","t":"Ōsaka đồ ăn ngon."},{"s":"ドイツの フランケンは ワインが ゆうめいです。","t":"Vùng Franken của Đức nổi tiếng về rượu vang."},{"s":"マリアさんは かみが ながいです。","t":"Chị Maria tóc dài."}],"tip":""},{"title":"N を V – rời khỏi, xuống","form":"N を でます／おります","explain":"Với các động từ でます (ra khỏi), おります (xuống xe), を chỉ điểm xuất phát, nơi rời khỏi.","examples":[{"s":"7じに うちを でます。","t":"7 giờ tôi ra khỏi nhà."},{"s":"うめだで でんしゃを おりました。","t":"Tôi đã xuống tàu ở Umeda."}],"tip":"Lên xe dùng に (バスに のります); xuống xe dùng を (バスを おります)."},{"title":"どうやって – bằng cách nào","form":"どうやって V か","explain":"Hỏi đường đi hoặc cách làm một việc. Trả lời thường dùng thể て nối các bước.","examples":[{"s":"だいがくまで どうやって いきますか。……きょうとえきから 16ばんの バスに のって、だいがくまえで おります。","t":"Đến trường đi bằng cách nào? – Từ ga Kyōto lên xe buýt số 16, rồi xuống ở bến Daigaku-mae."}],"tip":""},{"title":"どれ／どの N – cái nào","form":"どれ · どの + N","explain":"Hỏi để xác định một đối tượng trong nhóm từ ba trở lên. どれ đứng một mình; muốn bổ nghĩa danh từ thì dùng どの + N.","examples":[{"s":"ミラーさんの かさは どれですか。……あの あおい かさです。","t":"Ô của anh Miller là cái nào? – Là cái ô màu xanh kia."},{"s":"サントスさんは どの ひとですか。……あの せが たかくて、かみが くろい ひとです。","t":"Anh Santos là người nào? – Là người cao, tóc đen kia."}],"tip":"Chọn giữa hai thứ dùng どちら (Bài 12)."},{"title":"Liên từ nối câu – そして・それから・でも・しかし・だから · bổ sung N5","form":"Câu 1。そして／それから／でも／しかし／だから、Câu 2。","explain":"Đứng đầu câu thứ hai để nối với câu trước. そして: và, rồi; それから: sau đó, ngoài ra; でも: nhưng (khẩu ngữ); しかし: tuy nhiên (trang trọng); だから: vì vậy (khẩu ngữ, thể lịch sự hơn là ですから).","examples":[{"s":"きのう デパートへ いきました。それから、えいがを みました。","t":"Hôm qua tôi đi bách hóa. Sau đó tôi xem phim."},{"s":"この みせは やすいです。でも、あまり おいしくないです。","t":"Quán này rẻ. Nhưng không ngon lắm."},{"s":"あしたは しけんです。だから、こんばんは べんきょうします。","t":"Mai thi. Vì vậy tối nay tôi học."}],"tip":""}]},{"n":17,"title":"Bài 17","jp":"どうしましたか","sub":"Thể ない · ～なければなりません · bệnh tật","rows":[["おぼえます","覚えます","v2","Nhớ, ghi nhớ","memorise","かんじを おぼえます。／Học thuộc chữ Hán.","Nhóm II · thể từ điển: おぼえる"],["わすれます","忘れます","v2","Quên","forget","かさを わすれないで ください。／Đừng quên ô.","Nhóm II · thể từ điển: わすれる"],["なくします","無くします","v1","Làm mất","lose","さいふを なくしました。／Tôi làm mất ví.","Nhóm I · thể từ điển: なくす · 亡くします: mất (người thân qua đời)."],["だします［レポートを～］","出します","v1","Nộp [báo cáo]","hand in [a report]","あしたまでに レポートを ださなければ なりません。／Phải nộp báo cáo trước ngày mai.","Nhóm I · thể từ điển: だす"],["はらいます","払います","v1","Trả (tiền)","pay","カードで はらっても いいですか。／Trả bằng thẻ được không?","Nhóm I · thể từ điển: はらう"],["かえします","返します","v1","Trả lại","give back, return","としょかんに ほんを かえします。／Trả sách cho thư viện.","Nhóm I · thể từ điển: かえす"],["でかけます","出かけます","v2","Ra ngoài","go out","にちようびは でかけません。／Chủ nhật tôi không ra ngoài.","Nhóm II · thể từ điển: でかける"],["ぬぎます","脱ぎます","v1","Cởi (quần áo, giày)","take off (clothes, shoes)","ここで くつを ぬいで ください。／Hãy cởi giày ở đây.","Nhóm I · thể từ điển: ぬぐ"],["もっていきます","持って行きます","v1","Mang đi","take (something)","かさを もって いきます。／Mang ô đi.","Nhóm I · vật dùng を. (PDF ghi sai: 持って行ます)"],["もってきます","持って来ます","v3","Mang đến","bring (something)","あした しゃしんを もって きます。／Mai tôi mang ảnh đến.","Nhóm III (くる) · PDF ghi sai chữ 木."],["しんぱいします","心配します","v3","Lo lắng","worry","しんぱいしないで ください。／Đừng lo lắng.","Nhóm III"],["ざんぎょうします","残業します","v3","Làm thêm giờ","work overtime","きょうは ざんぎょうしなければ なりません。／Hôm nay phải làm thêm giờ.","Nhóm III"],["しゅっちょうします","出張します","v3","Đi công tác","go on a business trip","らいしゅう おおさかへ しゅっちょうします。／Tuần sau đi công tác Osaka.","Nhóm III"],["のみます［くすりを～］","飲みます","v1","Uống [thuốc]","take [medicine]","1にち 3かい くすりを のんで ください。／Uống thuốc ngày 3 lần.","Nhóm I · tiếng Nhật dùng “uống” cho thuốc."],["はいります［おふろに～］","入ります","v1","Tắm [bồn]","take [a bath]","まいばん おふろに はいります。／Tối nào cũng tắm bồn.","Nhóm I · dùng に."],["たいせつ［な］","大切［な］","ana","Quan trọng, quý giá","important, precious","これは たいせつな しゃしんです。／Đây là bức ảnh quý giá.","Tính từ đuôi な."],["だいじょうぶ［な］","大丈夫［な］","ana","Không sao, ổn","all right","だいじょうぶですか。ーはい、だいじょうぶです。／Có sao không? — Không sao.",""],["あぶない","危ない","ai","Nguy hiểm","dangerous","あぶないですから、さわらないで ください。／Nguy hiểm nên đừng chạm vào.",""],["もんだい","問題","n","Câu hỏi, vấn đề","question, problem, trouble","この もんだいは むずかしいです。／Câu hỏi này khó.",""],["こたえ","答え","n","Câu trả lời, đáp án","answer","こたえを かいて ください。／Hãy viết câu trả lời.",""],["きんえん","禁煙","n","Cấm hút thuốc","no smoking","ここは きんえんです。／Ở đây cấm hút thuốc.",""],["［けんこう］ほけんしょう","［健康］保険証","n","Thẻ bảo hiểm [y tế]","[health] insurance card","ほけんしょうを みせて ください。／Cho xem thẻ bảo hiểm.",""],["かぜ","風邪","n","Cảm lạnh","cold","かぜを ひきました。／Tôi bị cảm.","かぜを ひきます: bị cảm. 風 (gió) đồng âm."],["ねつ","熱","n","Sốt","fever","ねつが あります。／Tôi bị sốt.",""],["びょうき","病気","n","Bệnh","illness, disease","びょうきで かいしゃを やすみました。／Nghỉ làm vì ốm.",""],["くすり","薬","n","Thuốc","medicine","この くすりを のんで ください。／Hãy uống thuốc này.",""],["［お］ふろ","［お］風呂","n","Bồn tắm","bath","きょうは おふろに はいらないで ください。／Hôm nay đừng tắm bồn.",""],["うわぎ","上着","n","Áo khoác","jacket, outerwear","うわぎを ぬいで ください。／Hãy cởi áo khoác.",""],["したぎ","下着","n","Đồ lót","underwear","したぎを せんたくします。／Giặt đồ lót.",""],["せんせい","先生","n","Bác sĩ (cách gọi)","doctor (addressing a doctor)","せんせい、かぜですか。／Thưa bác sĩ, tôi bị cảm ạ?","Cũng dùng gọi thầy cô giáo."],["２、３にち","２、３日","n","Hai, ba ngày","a few days","2、3にち やすんで ください。／Hãy nghỉ 2, 3 ngày.",""],["２、３～","","ctr","Hai, ba ~","a few ~","2、3にん きました。／Có 2, 3 người đến.","~ là hậu tố đếm."],["～までに","","pt","Trước ~ (hạn chót)","before ~, by ~ (deadline)","きんようびまでに だして ください。／Hãy nộp trước thứ sáu.","Khác まで (liên tục đến ~)."],["ですから","","cj","Vì thế, do đó","therefore, so","あしたは しけんです。ですから、きょうは べんきょうします。／Mai thi. Vì vậy hôm nay học.","Lịch sự của だから."],["どうしましたか","","ex","Anh/chị bị làm sao?","What's the matter?","どうしましたか。ーのどが いたいです。／Bị sao vậy? — Tôi đau họng.","Bác sĩ hỏi bệnh nhân."],["［～が］いたいです","［～が］痛いです","ex","Tôi bị đau [~]","I have a pain [in my ~].","あたまが いたいです。／Tôi đau đầu.",""],["のど","喉","n","Họng","throat","のどが いたいです。／Tôi đau họng.",""],["おだいじに","お大事に","ex","Anh/chị nhớ giữ gìn sức khoẻ nhé","Take care of yourself. (to someone ill)","おだいじに。／Chúc mau khoẻ.","Nói với người ốm."]],"ref":[["あたまが いたい","頭が 痛い","ex","Đau đầu","have a headache","けさから あたまが いたいです。／Từ sáng nay tôi đau đầu.",""],["おなかが いたい","おなかが 痛い","ex","Đau bụng","have a stomachache","たべすぎて おなかが いたいです。／Ăn nhiều quá nên tôi đau bụng.",""],["はが いたい","歯が 痛い","ex","Đau răng","have a toothache","はが いたいですから、はいしゃへ いきます。／Đau răng nên tôi đi nha sĩ.",""],["ねつが あります","熱が あります","ex","Bị sốt","have a fever","ねつが ありますから、やすみます。／Tôi bị sốt nên xin nghỉ.",""],["せきが でます","せきが 出ます","ex","Bị ho","have a cough","よる せきが でます。／Ban đêm tôi bị ho.",""],["はなみずが でます","鼻水が 出ます","ex","Chảy nước mũi, sổ mũi","have a runny nose","かぜで はなみずが でます。／Bị cảm nên tôi sổ mũi.",""],["ちが でます","血が 出ます","ex","Chảy máu","bleed","ゆびから ちが でて います。／Ngón tay đang chảy máu.",""],["はきけが します","吐き気が します","ex","Buồn nôn","feel nauseous","すこし はきけが します。／Tôi hơi buồn nôn.",""],["さむけが します","寒気が します","ex","Gai người, ớn lạnh","have chills","さむけが しますから、はやく ねます。／Tôi thấy ớn lạnh nên đi ngủ sớm.",""],["めまいが します","","ex","Chóng mặt","feel dizzy","たつと めまいが します。／Đứng dậy là tôi chóng mặt.",""],["げりを します","下痢を します","ex","Ỉa chảy, tiêu chảy","have diarrhea","きのうから げりを して います。／Từ hôm qua tôi bị tiêu chảy.",""],["べんぴを します","便秘を します","ex","Táo bón","be constipated","みずを のまないと べんぴを します。／Không uống nước thì bị táo bón.",""],["けがを します","","ex","Bị thương","get injured","サッカーで けがを しました。／Tôi bị thương khi chơi bóng đá.",""],["やけどを します","","ex","Bị bỏng","get burned","てに やけどを しました。／Tôi bị bỏng tay.",""],["しょくよくが ありません","食欲が ありません","ex","Không muốn ăn, chán ăn","have no appetite","かぜで しょくよくが ありません。／Bị cảm nên tôi không muốn ăn.",""],["かたが こります","肩が こります","ex","Đau vai, mỏi vai","have stiff shoulders","パソコンを つかうと かたが こります。／Dùng máy tính là tôi mỏi vai.",""],["からだが だるい","体が だるい","ex","Mỏi người, uể oải","feel sluggish","きょうは からだが だるいです。／Hôm nay tôi thấy mỏi người.",""],["かゆい","","ai","Ngứa","itchy","せなかが かゆいです。／Lưng tôi ngứa.",""],["はな","鼻","n","Mũi","nose","ぞうは はなが ながいです。／Voi có mũi dài.",""],["あご","","n","Cằm","chin, jaw","あごが いたいです。／Tôi đau cằm.",""],["くび","首","n","Cổ","neck","くびが ながいです。／Cổ dài.",""],["かた","肩","n","Vai","shoulder","かたを もみます。／Tôi xoa bóp vai.",""],["むね","胸","n","Ngực","chest","むねが いたいです。／Tôi đau ngực.",""],["せなか","背中","n","Lưng","back","せなかが かゆいです。／Lưng ngứa.",""],["うで","腕","n","Cánh tay","arm","うでが ながいです。／Cánh tay dài.",""],["ひじ","","n","Khuỷu tay","elbow","ひじを ぶつけました。／Tôi bị va khuỷu tay.",""],["ゆび","指","n","Ngón tay","finger","ゆびに やけどを しました。／Tôi bị bỏng ngón tay.",""],["つめ","爪","n","Móng tay","nail","つめを きります。／Tôi cắt móng tay.",""],["こし","腰","n","Hông, eo, thắt lưng","lower back","こしが いたいです。／Tôi đau lưng (hông).",""],["しり","尻","n","Mông","buttocks","ながく すわると しりが いたいです。／Ngồi lâu là đau mông.",""],["ひざ","","n","Đầu gối","knee","ひざが いたいです。／Tôi đau đầu gối.",""],["ほね","骨","n","Xương","bone","さかなの ほねに きを つけて ください。／Cẩn thận xương cá.",""],["インフルエンザ","","n","Cúm (dịch)","influenza","インフルエンザで がっこうを やすみました。／Tôi nghỉ học vì bị cúm.",""],["もうちょう","盲腸","n","Ruột thừa","appendix","もうちょうの しゅじゅつを しました。／Tôi đã mổ ruột thừa.",""],["ぎっくりごし","ぎっくり腰","n","Trật đốt sống, trẹo hông","strained back","おもい にもつを もって ぎっくりごしに なりました。／Mang đồ nặng nên tôi bị trẹo lưng.",""],["ねんざ","","n","Bong gân","sprain","あしを ねんざしました。／Tôi bị bong gân chân.",""],["こっせつ","骨折","n","Gãy xương","bone fracture","スキーで こっせつしました。／Tôi bị gãy xương khi trượt tuyết.",""],["ふつかよい","二日酔い","n","Say xỉn hôm sau, dư vị khó chịu sau khi uống rượu","hangover","けさは ふつかよいです。／Sáng nay tôi bị váng đầu vì rượu.",""]],"refTitle":"Cơ thể & các loại bệnh","grammar":[{"title":"Thể ない của động từ","form":"Nhóm I: ～い・ます → ～あ・ない (～い → ～わない) · Nhóm II: bỏ ます + ない · Nhóm III: しない／こない","explain":"Thể ない là dạng phủ định thân mật, dùng để ghép mẫu câu.\n\nNhóm I: đổi âm trước ます từ hàng い sang hàng あ rồi thêm ない: かきます→かかない, よみます→よまない, まちます→またない, はなします→はなさない. Nếu âm đó là い thì đổi thành わ (không phải あ): かいます→かわない, すいます→すわない.\n\nNhóm II: たべます→たべない, みます→みない. Nhóm III: します→しない, きます→こない.","examples":[{"s":"かきます → かかない","t":"không viết"},{"s":"かいます → かわない","t":"không mua"},{"s":"きます → こない","t":"không đến"}],"tip":"Sai: かいます → かあない. Đúng: かわない. Và あります → ない (không phải あらない)."},{"title":"V ないで ください – xin đừng","form":"V ない で ください","explain":"Yêu cầu hoặc chỉ thị người nghe đừng làm gì. Cũng dùng để nói ai đó không cần phải làm thế (đừng lo).","examples":[{"s":"ここで しゃしんを とらないで ください。","t":"Xin đừng chụp ảnh ở đây."},{"s":"わたしは げんきですから、しんぱいしないで ください。","t":"Tôi khỏe nên anh đừng lo lắng."}],"tip":""},{"title":"V なければ なりません – phải","form":"V (bỏ ない) なければ なりません","explain":"Diễn tả việc bắt buộc phải làm: “phải…”. Lưu ý đây là câu khẳng định dù có hình thức phủ định kép.","examples":[{"s":"くすりを のまなければ なりません。","t":"Tôi phải uống thuốc."},{"s":"あした 7じに おきなければ なりません。","t":"Mai tôi phải dậy lúc 7 giờ."}],"tip":""},{"title":"V なくても いいです – không cần","form":"V (bỏ ない) なくても いいです","explain":"Diễn tả không cần thiết phải làm gì: “không cần… cũng được”.","examples":[{"s":"あした こなくても いいです。","t":"Ngày mai anh không cần đến."},{"s":"くつを ぬがなくても いいです。","t":"Không cần cởi giày cũng được."}],"tip":""},{"title":"Chủ đề hóa tân ngữ – N を → N は","form":"N は (thay cho N を) ～","explain":"Muốn đưa tân ngữ ra đầu câu làm chủ đề, thay を bằng は. Câu có ý “còn N thì…”.","examples":[{"s":"にもつは ここに おかないで ください。","t":"Hành lý thì xin đừng để ở đây."},{"s":"ひるごはんは かいしゃの しょくどうで たべます。","t":"Cơm trưa thì tôi ăn ở nhà ăn công ty."}],"tip":""},{"title":"N (thời gian) までに V – trước, chậm nhất","form":"N (thời gian) までに V","explain":"までに chỉ thời hạn chót mà hành động phải xảy ra trước đó. Khác まで (Bài 4) – hành động kéo dài liên tục đến thời điểm đó.","examples":[{"s":"かいぎは 5じまでに おわります。","t":"Cuộc họp sẽ kết thúc trước 5 giờ."},{"s":"どようびまでに ほんを かえさなければ なりません。","t":"Phải trả sách trước thứ Bảy."},{"s":"5じまで はたらきます。","t":"Tôi làm việc đến 5 giờ. (so sánh)"}],"tip":"までに = hạn chót (một lần); まで = liên tục đến lúc đó."}]},{"n":18,"title":"Bài 18","jp":"趣味は何ですか","sub":"Thể từ điển · ～ことができます · sở thích","rows":[["できます","出来ます","v2","Có thể","be able to, can","ミラーさんは かんじが できます。／Anh Miller biết chữ Hán.","Nhóm II · thể từ điển: できる · đối tượng dùng が; V-る ことが できます."],["あらいます","洗います","v1","Rửa","wash","ねる まえに、てを あらいます。／Rửa tay trước khi ngủ.","Nhóm I · thể từ điển: あらう"],["ひきます","弾きます","v1","Chơi (nhạc cụ dây, piano)","play (piano, stringed instrument)","ピアノを ひく ことが できます。／Tôi biết chơi piano.","Nhóm I · thể từ điển: ひく · kèn, sáo dùng ふきます."],["うたいます","歌います","v1","Hát","sing","にほんの うたを うたいます。／Hát bài hát Nhật.","Nhóm I · thể từ điển: うたう"],["あつめます","集めます","v2","Sưu tập, thu thập","collect, gather","しゅみは きってを あつめる ことです。／Sở thích là sưu tập tem.","Nhóm II · thể từ điển: あつめる"],["すてます","捨てます","v2","Vứt bỏ","throw away","ごみを すてて ください。／Hãy vứt rác.","Nhóm II · thể từ điển: すてる"],["かえます","換えます","v2","Đổi","exchange, change","ドルを えんに かえます。／Đổi đô la sang yên.","Nhóm II · thể từ điển: かえる"],["うんてんします","運転します","v3","Lái (xe)","drive","くるまを うんてんする ことが できます。／Tôi biết lái ô tô.","Nhóm III"],["よやくします","予約します","v3","Đặt trước","reserve, book","レストランを よやくしました。／Đã đặt nhà hàng.","Nhóm III"],["けんがくします","見学します","v3","Tham quan học tập","visit some place for study","こうじょうを けんがくします。／Tham quan nhà máy.","Nhóm III"],["ピアノ","","n","Đàn piano","piano","ピアノを ひきます。／Chơi piano.",""],["～メートル","","ctr","~ mét","~ meter","100メートル およぐ ことが できます。／Tôi bơi được 100 mét.",""],["こくさい～","国際～","sf","~ quốc tế","international ~","こくさいでんわを かけます。／Gọi điện quốc tế.",""],["げんきん","現金","n","Tiền mặt","cash","げんきんで はらいます。／Trả bằng tiền mặt.",""],["しゅみ","趣味","n","Sở thích","hobby","しゅみは なんですか。ーえを かく ことです。／Sở thích là gì? — Là vẽ tranh.",""],["にっき","日記","n","Nhật ký","diary","ねる まえに、にっきを かきます。／Viết nhật ký trước khi ngủ.",""],["［お］いのり","［お］祈り","n","Cầu nguyện","prayer","ねる まえに、おいのりを します。／Cầu nguyện trước khi ngủ.","～をします: cầu nguyện."],["かちょう","課長","n","Trưởng nhóm, trưởng ban","section chief","かちょうは いま かいぎちゅうです。／Trưởng ban đang họp.",""],["ぶちょう","部長","n","Trưởng phòng","department chief","ぶちょうに そうだんします。／Trao đổi với trưởng phòng.",""],["しゃちょう","社長","n","Giám đốc","company president","しゃちょうは いま いません。／Giám đốc hiện không có ở đây.",""],["どうぶつ","動物","n","Động vật","animal","どんな どうぶつが すきですか。／Bạn thích con vật nào?",""],["うま","馬","n","Con ngựa","horse","うまに のる ことが できます。／Tôi cưỡi được ngựa.",""],["へえ","","it","Thế à! Ồ!","Really! (surprise)","へえ、すごいですね。／Ồ, giỏi thế.",""],["それはおもしろいですね","それは面白いですね","ex","Điều đó thú vị nhỉ","That must be interesting.","しゅみは うまに のる ことです。ーへえ、それは おもしろいですね。／Sở thích là cưỡi ngựa. — Ồ, thú vị nhỉ.",""],["なかなか","中々","adv","Mãi mà không, khó mà","not easily (with negatives)","にほんでは なかなか うまを みる ことが できません。／Ở Nhật khó mà thấy ngựa.","Đi với phủ định."],["ぼくじょう","牧場","n","Trang trại chăn nuôi","ranch, stock farm","ぼくじょうへ いきました。／Đã đi trang trại.",""],["ほんとうですか","本当ですか","ex","Thật không?","Really?","あした やすみです。ーほんとうですか。／Mai được nghỉ. — Thật không?",""],["ぜひ","是非","adv","Nhất định","by all means","ぜひ きて ください。／Nhất định hãy đến nhé.","Đi với mong muốn, nhờ vả."]],"ref":[["うごき","動き","n","Động tác, cử động","movement","この うごきは むずかしいです。／Động tác này khó.",""],["とぶ","飛ぶ","v1","Bay","fly","とりが そらを とんで います。／Chim đang bay trên trời.",""],["とぶ","跳ぶ","v1","Nhảy (bật lên)","jump","みずたまりを とびます。／Tôi nhảy qua vũng nước.","Cùng âm với 飛ぶ (bay)"],["のぼる","登る","v1","Leo, trèo","climb","きに のぼります。／Tôi trèo cây.",""],["はしる","走る","v1","Chạy","run","まいあさ こうえんを はしります。／Sáng nào tôi cũng chạy ở công viên.",""],["もぐる","","v1","Lặn","dive","うみに もぐります。／Tôi lặn xuống biển.",""],["とびこむ","飛び込む","v1","Nhảy xuống, lao vào","dive in","プールに とびこまないで ください。／Đừng nhảy xuống bể bơi.",""],["さかだちする","逆立ちする","v3","Lộn ngược, trồng cây chuối","do a handstand","さかだちが できますか。／Bạn trồng cây chuối được không?",""],["はう","","v1","Bò","crawl","あかちゃんが はって います。／Em bé đang bò.",""],["ける","","v1","Đá","kick","ボールを けります。／Tôi đá bóng.",""],["ふる","振る","v1","Vẫy","wave","てを ふります。／Tôi vẫy tay.",""],["もちあげる","持ち上げる","v2","Nâng, nhấc lên","lift","おもい にもつを もちあげます。／Tôi nhấc đồ nặng lên.",""],["なげる","投げる","v2","Ném","throw","ボールを なげて ください。／Hãy ném bóng đi.",""],["たたく","","v1","Đấm, đập, vỗ","hit, tap","ドアを たたきます。／Tôi gõ cửa.",""],["ひく","引く","v1","Kéo","pull","ドアを ひいて ください。／Hãy kéo cửa.",""],["おす","押す","v1","Đẩy, ấn","push","ボタンを おします。／Tôi ấn nút.",""],["まげる","曲げる","v2","Uốn, gập, bẻ cong","bend","ひざを まげて ください。／Hãy gập đầu gối.",""],["のばす","伸ばす","v1","Duỗi thẳng, kéo dài ra","stretch","うでを のばします。／Tôi duỗi tay.",""],["ころぶ","転ぶ","v1","Ngã","fall down","みちで ころびました。／Tôi bị ngã trên đường.",""],["ふりむく","振り向く","v1","Ngoảnh lại","turn around","なまえを よばれて ふりむきました。／Bị gọi tên nên tôi ngoảnh lại.",""]],"refTitle":"Động tác","grammar":[{"title":"Thể từ điển (thể nguyên dạng) của động từ","form":"Nhóm I: ～い・ます → ～う · Nhóm II: bỏ ます + る · Nhóm III: する／くる","explain":"Là dạng cơ bản được ghi trong từ điển.\n\nNhóm I: đổi âm trước ます từ hàng い sang hàng う: かきます→かく, のみます→のむ, かいます→かう, まちます→まつ, はなします→はなす.\n\nNhóm II: たべます→たべる, みます→みる. Nhóm III: します→する, きます→くる.","examples":[{"s":"かきます → かく","t":"viết"},{"s":"たべます → たべる","t":"ăn"},{"s":"きます → くる","t":"đến"}],"tip":""},{"title":"N／V (thể từ điển) こと が できます – có thể","form":"N が できます · V (thể từ điển) こと が できます","explain":"できます diễn tả năng lực (biết làm) hoặc khả năng (hoàn cảnh cho phép làm). Đối tượng là danh từ chỉ hoạt động (うんてん, スキー), kỹ năng (にほんご, ピアノ), hoặc cụm “động từ + こと”.","examples":[{"s":"ミラーさんは にほんごが できます。","t":"Anh Miller có thể nói tiếng Nhật."},{"s":"ゆきが たくさん ふりましたから、ことしは スキーが できます。","t":"Tuyết rơi nhiều nên năm nay có thể trượt tuyết."},{"s":"ミラーさんは かんじを よむ ことが できます。","t":"Anh Miller có thể đọc chữ Hán."},{"s":"カードで はらう ことが できます。","t":"Có thể trả tiền bằng thẻ."}],"tip":""},{"title":"わたしの 趣味は ～です – sở thích","form":"わたしの しゅみは N です · わたしの しゅみは V (thể từ điển) こと です","explain":"Nói sở thích. Dùng “động từ + こと” để nói cụ thể hơn.","examples":[{"s":"わたしの しゅみは おんがくです。","t":"Sở thích của tôi là âm nhạc."},{"s":"わたしの しゅみは おんがくを きく ことです。","t":"Sở thích của tôi là nghe nhạc."}],"tip":""},{"title":"V1 (từ điển)／N の／thời gian まえに、V2 – trước khi","form":"V1 (thể từ điển) まえに · N の まえに · Số lượng (thời gian) まえに","explain":"V2 xảy ra trước V1. Động từ trước まえに LUÔN ở thể từ điển dù câu ở quá khứ. Với danh từ thêm の; với khoảng thời gian thì KHÔNG thêm の.","examples":[{"s":"にほんへ くる まえに、にほんごを べんきょうしました。","t":"Trước khi đến Nhật tôi đã học tiếng Nhật."},{"s":"ねる まえに、ほんを よみます。","t":"Trước khi ngủ tôi đọc sách."},{"s":"しょくじの まえに、てを あらいます。","t":"Trước bữa ăn tôi rửa tay."},{"s":"たなかさんは 1じかんまえに、でかけました。","t":"Anh Tanaka đã ra ngoài cách đây 1 tiếng."}],"tip":"Sai: きた まえに. Đúng: くる まえに."},{"title":"なかなか – mãi mà không, khó mà","form":"なかなか + V (phủ định)","explain":"Đi với phủ định: “mãi không…”, “khó mà…”, không dễ, không như kỳ vọng.","examples":[{"s":"にほんでは なかなか うまを みる ことが できません。","t":"Ở Nhật khó mà có cơ hội thấy ngựa."},{"s":"バスが なかなか きません。","t":"Xe buýt mãi không đến."}],"tip":""},{"title":"ぜひ – nhất định, rất muốn","form":"ぜひ + ～たいです／～て ください","explain":"Nhấn mạnh mong muốn, lời mời tha thiết của người nói.","examples":[{"s":"ぜひ ほっかいどうへ いきたいです。","t":"Tôi rất muốn đi Hokkaidō."},{"s":"ぜひ あそびに きて ください。","t":"Nhất định anh phải đến chơi nhé."}],"tip":""},{"title":"V (thể từ điển) の – danh từ hóa thân mật · bổ sung N5","form":"V (thể từ điển) の が すきです／じょうずです／へたです","explain":"Ngoài こと, có thể thêm の sau động từ để biến nó thành danh từ, hay dùng với すき, きらい, じょうず, へた trong hội thoại.","examples":[{"s":"わたしは えを かくのが すきです。","t":"Tôi thích vẽ tranh."},{"s":"かれは うたうのが じょうずです。","t":"Anh ấy hát giỏi."}],"tip":""}]},{"n":19,"title":"Bài 19","jp":"ダイエットはあしたからします","sub":"Thể た · ～たことがあります · ～たり～たり","rows":[["のぼります［やまに～］","登ります","v1","Leo [núi]","climb [a mountain]","ふじさんに のぼった ことが あります。／Tôi đã từng leo núi Phú Sĩ.","Nhóm I · thể từ điển: のぼる"],["とまります［ホテルに～］","泊まります","v1","Trọ, nghỉ lại [khách sạn]","stay [at a hotel]","ホテルに とまります。／Nghỉ ở khách sạn.","Nhóm I · thể từ điển: とまる"],["そうじします","掃除します","v3","Dọn dẹp, quét dọn","clean (a room)","にちようびは へやを そうじします。／Chủ nhật dọn phòng.","Nhóm III"],["せんたくします","洗濯します","v3","Giặt (quần áo)","wash (clothes)","そうじしたり、せんたくしたり します。／Lúc thì dọn dẹp, lúc thì giặt giũ.","Nhóm III"],["れんしゅうします","練習します","v3","Luyện tập","practice","まいにち ピアノを れんしゅうします。／Ngày nào cũng tập piano.","Nhóm III"],["なります","","v1","Trở thành, trở nên","become","さむく なりました。／Trời đã trở lạnh.","Nhóm I · thể từ điển: なる · tính từ い→く, な/danh từ→に."],["ねむい","眠い","ai","Buồn ngủ","sleepy","きのう おそく ねましたから、ねむいです。／Hôm qua ngủ muộn nên buồn ngủ.",""],["つよい","強い","ai","Mạnh","strong","かぜが つよいです。／Gió mạnh.",""],["よわい","弱い","ai","Yếu","weak","からだが よわいです。／Cơ thể yếu.",""],["ちょうしがいい","調子がいい","ex","Tình trạng tốt","be in good condition","きょうは ちょうしが いいです。／Hôm nay tình trạng tốt.",""],["ちょうしがわるい","調子が悪い","ex","Tình trạng không tốt","be in bad condition","パソコンの ちょうしが わるいです。／Máy tính trục trặc.",""],["ちょうし","調子","n","Tình trạng","condition","からだの ちょうしは どうですか。／Sức khoẻ thế nào?",""],["ゴルフ","","n","Gôn","golf","しゅうまつ ゴルフを します。／Cuối tuần chơi gôn.","～をします: chơi gôn."],["すもう","相撲","n","Vật Sumo","sumo wrestling","すもうを みた ことが ありますか。／Đã xem Sumo chưa?",""],["パチンコ","","n","Trò chơi Pachinko","pachinko","パチンコを します。／Chơi pachinko.","～をします."],["おちゃ","お茶","n","Trà đạo","tea ceremony","おちゃを ならって います。／Đang học trà đạo.","Bài 6: nghĩa “trà”."],["ひ","日","n","Ngày","day, date","あめの ひは うちに います。／Ngày mưa ở nhà.",""],["いちど","一度","n","Một lần","once","いちど きょうとへ いきたいです。／Muốn đi Kyoto một lần.",""],["いちども","一度も","adv","Chưa lần nào","not once, never (with negatives)","いちども すもうを みた ことが ありません。／Chưa xem Sumo lần nào.","Đi với phủ định."],["だんだん","段々","adv","Dần dần","gradually","だんだん あつく なります。／Trời dần dần nóng lên.",""],["もうすぐ","","adv","Sắp sửa","soon","もうすぐ なつやすみです。／Sắp đến nghỉ hè rồi.",""],["おかげさまで","お蔭様で","ex","Nhờ trời, nhờ ơn anh/chị","Thank you. (for help received)","おげんきですか。ーおかげさまで、げんきです。／Khoẻ không? — Nhờ trời tôi khoẻ.",""],["かんぱい","乾杯","ex","Cạn ly! Dô!","Cheers! / Bottoms up!","では、かんぱい！／Nào, cạn ly!",""],["じつは","実は","adv","Thật ra là","actually, to tell the truth","じつは、ダイエットを して います。／Thật ra tôi đang ăn kiêng.",""],["ダイエット","","n","Ăn kiêng","diet","ダイエットは あしたから。／Ăn kiêng từ mai.","～をします: ăn kiêng."],["なんかいも","何回も","adv","Nhiều lần","many times","なんかいも ダイエットを しました。／Đã ăn kiêng nhiều lần.",""],["しかし","","cj","Tuy nhiên","but, however","しかし、むりな ダイエットは からだに よくないです。／Tuy nhiên ăn kiêng quá mức không tốt.","Văn viết, trang trọng hơn でも."],["むり［な］","無理［な］","ana","Quá sức, không thể","excessive, impossible","むりを しないで ください。／Đừng làm quá sức.","Tính từ đuôi な."],["からだにいい","体にいい","ex","Tốt cho sức khoẻ","good for one's health","やさいは からだに いいです。／Rau tốt cho sức khoẻ.",""],["ケーキ","","n","Bánh ngọt","cake","ケーキを たべすぎました。／Ăn quá nhiều bánh.",""]],"ref":[["でんとうぶんか","伝統文化","n","Văn hóa truyền thống","traditional culture","にほんの でんとうぶんかを ならいたいです。／Tôi muốn học văn hóa truyền thống Nhật.",""],["ごらく","娯楽","n","Giải trí","entertainment","ごらくは なにが すきですか。／Bạn thích thú giải trí nào?",""],["さどう","茶道","n","Trà đạo","tea ceremony","さどうを ならった ことが あります。／Tôi đã từng học trà đạo.","Còn gọi お茶"],["かどう","華道","n","Nghệ thuật cắm hoa","flower arrangement","かどうは うつくしいです。／Nghệ thuật cắm hoa thật đẹp.","Còn gọi 生け花"],["しょどう","書道","n","Thư pháp","calligraphy","しょどうで かんじを かきます。／Tôi viết chữ Hán bằng thư pháp.",""],["のう","能","n","Kịch Nō","Noh","のうは ふるい げきです。／Nō là loại kịch cổ.",""],["ぶんらく","文楽","n","Nghệ thuật múa rối Bunraku","bunraku (puppet theater)","おおさかで ぶんらくを みました。／Tôi đã xem Bunraku ở Ōsaka.",""],["からて","空手","n","Karate","karate","からてを ならって います。／Tôi đang học karate.",""],["まんざい","漫才","n","Hài đối đáp (manzai)","manzai (comic dialogue)","テレビで まんざいを みて わらいました。／Tôi xem manzai trên tivi và cười.",""],["らくご","落語","n","Nghệ thuật kể chuyện cười (rakugo)","rakugo (comic storytelling)","らくごは ひとりで はなします。／Rakugo do một người kể.",""],["いご","囲碁","n","Cờ vây","go (board game)","そふと いごを します。／Tôi chơi cờ vây với ông.",""],["しょうぎ","将棋","n","Cờ tướng Nhật (shōgi)","shogi","しょうぎが できますか。／Bạn chơi cờ shōgi được không?",""],["ぼんおどり","盆踊り","n","Múa Bon (lễ hội Obon)","Bon dance","なつに ぼんおどりを おどりました。／Mùa hè tôi đã múa Bon.",""]],"refTitle":"Văn hóa truyền thống & giải trí","grammar":[{"title":"Thể た của động từ","form":"Thể て → đổi て／で thành た／だ","explain":"Thể た là dạng quá khứ thân mật, tạo bằng cách thay て/で của thể て bằng た/だ: かいて→かいた, のんで→のんだ, たべて→たべた, きて→きた, して→した.","examples":[{"s":"かいて → かいた","t":"đã viết"},{"s":"のんで → のんだ","t":"đã uống"},{"s":"して → した","t":"đã làm"}],"tip":""},{"title":"V た ことが あります – đã từng","form":"V た ことが あります · chưa từng: V た ことが ありません","explain":"Nói về kinh nghiệm đã trải qua trong quá khứ. Nếu chỉ kể việc đã làm vào một thời điểm cụ thể thì dùng thể ました bình thường.","examples":[{"s":"うまに のった ことが あります。","t":"Tôi đã từng cưỡi ngựa."},{"s":"きょねん ほっかいどうで うまに のりました。","t":"Năm ngoái tôi cưỡi ngựa ở Hokkaidō. (sự việc cụ thể)"},{"s":"すしを たべた ことが ありますか。……いいえ、いちども ありません。","t":"Bạn đã từng ăn sushi chưa? – Chưa, chưa lần nào."}],"tip":""},{"title":"V1 たり、V2 たり します – lúc thì… lúc thì","form":"V1 た り、V2 た り します","explain":"Nêu vài hành động tiêu biểu (ngụ ý còn nữa), không theo thứ tự thời gian. Thì của câu do します ở cuối quyết định.\n\nKhác “V1 て、V2” (Bài 16) – các hành động liên tiếp theo thứ tự. Không dùng mẫu たり cho việc làm thường ngày ai cũng làm (dậy, ăn, ngủ).","examples":[{"s":"にちようびは テニスを したり、えいがを みたり します。","t":"Chủ nhật tôi chơi quần vợt, xem phim…"},{"s":"にちようびは テニスを したり、えいがを みたり しました。","t":"Chủ nhật tôi đã chơi quần vợt, xem phim…"},{"s":"にちようびは テニスを して、えいがを みました。","t":"Chủ nhật tôi chơi quần vợt rồi xem phim. (so sánh)"}],"tip":""},{"title":"Adjい→く／Adjな→に／N に なります – trở nên","form":"Adj(bỏ い) く なります · Adjな に なります · N に なります","explain":"なります diễn tả sự thay đổi trạng thái: “trở nên, trở thành”.","examples":[{"s":"さむく なります。","t":"Trời trở nên lạnh."},{"s":"げんきに なります。","t":"Khỏe lên."},{"s":"25さいに なります。","t":"Sang tuổi 25."},{"s":"いしゃに なりたいです。","t":"Tôi muốn trở thành bác sĩ."}],"tip":"いい → よく なります (không phải いく なります)."}]},{"n":20,"title":"Bài 20","jp":"夏休みはどうするの？","sub":"Thể thông thường · văn nói thân mật","rows":[["いります［ビザが～］","要ります","v1","Cần [visa]","need, require [a visa]","ビザが いる？／Có cần visa không?","Nhóm I · thể từ điển: いる · đối tượng dùng が."],["しらべます","調べます","v2","Tìm hiểu, tra cứu","check, investigate","じしょで しらべる。／Tra từ điển.","Nhóm II · thể từ điển: しらべる"],["なおします","直します","v1","Sửa, chữa","repair, correct","さくぶんを なおして ください。／Hãy sửa bài văn.","Nhóm I · thể từ điển: なおす"],["しゅうりします","修理します","v3","Sửa chữa (máy móc)","repair","くるまを しゅうりする。／Sửa xe.","Nhóm III"],["でんわします","電話します","v3","Gọi điện thoại","phone","あとで でんわする。／Lát nữa gọi.","Nhóm III"],["ぼく","僕","pr","Tớ, tôi (nam, thân mật)","I (informal, used by men)","ぼくは がくせいだ。／Tớ là sinh viên.",""],["きみ","君","pr","Cậu, em (nam dùng, thân mật)","you (informal, used by men)","きみは どう おもう？／Cậu nghĩ sao?","Dùng với người ngang hàng hoặc dưới."],["～くん","～君","sf","Cậu ~, bạn ~","Mr. ~ (informal, for boys/juniors)","たろうくん、げんき？／Taro, khoẻ không?","Thân mật của ～さん, thường cho nam."],["うん","","it","Ừ","yes (informal)","コーヒー のむ？ーうん、のむ。／Uống cà phê không? — Ừ, uống.","Thân mật của はい."],["ううん","","it","Không (thân mật)","no (informal)","ビザ、いる？ーううん、いらない。／Cần visa không? — Không, không cần.","Thân mật của いいえ."],["サラリーマン","","n","Nhân viên văn phòng","salaried worker, office worker","あには サラリーマンだ。／Anh tớ là nhân viên văn phòng.","PDF ghi sai: サラレーマン."],["ことば","言葉","n","Từ ngữ, ngôn ngữ","word, language","この ことばの いみは なに？／Từ này nghĩa là gì?",""],["ぶっか","物価","n","Vật giá","commodity prices","とうきょうは ぶっかが たかい。／Tokyo vật giá đắt.",""],["きもの","着物","n","Kimono","kimono (traditional Japanese attire)","きものを きた ことが ある？／Đã mặc kimono bao giờ chưa?",""],["ビザ","","n","Thị thực, visa","visa","ビザが いる。／Cần visa.",""],["はじめ","初め","n","Ban đầu, đầu","the beginning","らいげつの はじめに かえる。／Đầu tháng sau tôi về.",""],["おわり","終わり","n","Kết thúc, cuối","the end","こんげつの おわりに しけんが ある。／Cuối tháng này có thi.",""],["こっち","","pr","Bên này, phía này (thân mật)","this way, this place (informal こちら)","こっちへ きて。／Lại đây.",""],["そっち","","pr","Bên đó (thân mật)","that way, that place (informal そちら)","そっちは どう？／Bên đó thế nào?",""],["あっち","","pr","Bên kia (thân mật)","that way over there (informal あちら)","あっちに ある。／Ở đằng kia.",""],["どっち","","q","Bên nào, cái nào (thân mật)","which one, which way (informal どちら)","どっちが いい？／Cái nào được?",""],["このあいだ","この間","n","Hôm trước","the other day","このあいだ、ありがとう。／Cảm ơn chuyện hôm trước nhé.",""],["みんなで","皆で","adv","Mọi người cùng nhau","all together","みんなで いこう。／Mọi người cùng đi nào.",""],["～けど","","cj","~ nhưng ~ (thân mật)","~, but (informal が)","たかいけど、おいしい。／Đắt nhưng ngon.",""],["くにへかえるの？","国へ帰るの？","ex","Cậu về nước à?","Are you going back to your country?","なつやすみは くにへ かえるの？／Nghỉ hè cậu về nước à?","Văn thân mật: thể thường + の？"],["どうするの？","","ex","Cậu sẽ làm gì?","What will you do?","なつやすみ、どうするの？／Nghỉ hè cậu làm gì?",""],["どうしようかな","","ex","Làm gì bây giờ nhỉ?","What shall I do?","うーん、どうしようかな。／Ừm, làm gì đây nhỉ.","Tự hỏi bản thân."],["よかったら","","ex","Nếu được thì, nếu bạn thích","if you like","よかったら、いっしょに いかない？／Nếu được thì đi cùng không?",""],["いろいろ","色々","adv","Nhiều thứ, đủ điều","various","いろいろ ありがとう。／Cảm ơn vì mọi thứ.",""]],"ref":[["よびかた","呼び方","n","Cách gọi, cách xưng hô","way of addressing","にほんの よびかたは むずかしいです。／Cách xưng hô của người Nhật thật khó.",""],["おにいちゃん","お兄ちゃん","n","Anh (gọi thân mật)","big brother (familiar)","おにいちゃん、あそぼう。／Anh ơi, chơi đi.","Bố mẹ gọi con trai lớn theo vai của đứa nhỏ nhất"],["おねえちゃん","お姉ちゃん","n","Chị (gọi thân mật)","big sister (familiar)","おねえちゃん、まって。／Chị ơi, đợi em.",""],["ママ","","n","Mẹ (mama)","mama","ママ、だいすき。／Con yêu mẹ.",""],["パパ","","n","Bố (papa)","papa","パパ、きょうは たろうの たんじょうびよ。／Bố nó ơi, hôm nay là sinh nhật Taro đấy.",""],["おきゃくさま","お客様","n","Quý khách","customer (honorific)","おきゃくさま、よく おにあいですよ。／Thưa quý khách, rất vừa đấy ạ.","Nhân viên bán hàng gọi khách"]],"refTitle":"Cách xưng hô","grammar":[{"title":"Thể lịch sự và thể thông thường","form":"Lịch sự: ～です／～ます · Thông thường: thể từ điển, ない, た, なかった; Adjい／Adjな だ／N だ","explain":"Câu tiếng Nhật có hai thể. Thể lịch sự dùng です, ます. Thể thông thường (普通形) dùng dạng từ điển, ない, た, なかった; tính từ な và danh từ dùng だ／じゃ ない／だった／じゃ なかった; tính từ い giữ nguyên (いそがしい／いそがしくない／いそがしかった／いそがしくなかった).","examples":[{"s":"あした とうきょうへ いく。","t":"Ngày mai tôi đi Tōkyō. (= いきます)"},{"s":"まいにち いそがしい。","t":"Ngày nào cũng bận. (= いそがしいです)"},{"s":"すもうが すきだ。","t":"Tôi thích sumo. (= すきです)"},{"s":"ドイツへ いった ことが ない。","t":"Tôi chưa từng đi Đức. (= ありません)"}],"tip":""},{"title":"Phân biệt khi nào dùng thể lịch sự / thông thường","form":"Lịch sự: người mới gặp, người trên, người chưa thân · Thông thường: bạn thân, đồng nghiệp thân, gia đình","explain":"Hội thoại: dùng thể lịch sự với người lần đầu gặp, người lớn tuổi hơn, hoặc người cùng tuổi nhưng chưa thân; thể thông thường với bạn thân, đồng nghiệp gần gũi, người trong gia đình. Dùng nhầm thể thông thường với người cần lịch sự sẽ bị coi là thất lễ.\n\nVăn viết: thư từ thường dùng thể lịch sự; luận văn, báo cáo, nhật ký thường dùng thể thông thường.","examples":[{"s":"せんせい、あした きますか。","t":"Thưa cô, mai cô có đến không ạ? (lịch sự)"},{"s":"あした くる？","t":"Mai cậu có đến không? (thông thường, với bạn)"}],"tip":""},{"title":"Hội thoại ở thể thông thường","form":"Câu hỏi bỏ か, lên giọng · Danh từ/Adjな bỏ だ khi hỏi · lược trợ từ · ～て[い]る · けど","explain":"① Câu hỏi thường không dùng か, chỉ lên giọng cuối câu: のむ？(↗).\n\n② Câu hỏi với danh từ/tính từ な bỏ だ: ひま？. Khi trả lời, nói だ nghe dứt khoát, nam giới hay dùng; nữ giới hay bỏ だ hoặc thêm よ.\n\n③ Trợ từ は, を, へ, が hay được lược nếu hiểu được; で, に, から, まで, と thì không lược.\n\n④ い trong ～て いる hay bị lược: もって[い]る.\n\n⑤ けど dùng như が (nhưng) trong hội thoại.","examples":[{"s":"コーヒーを のむ？……うん、のむ。","t":"Uống cà phê không? – Ừ, uống."},{"s":"こんばん ひま？……うん、ひまだ","t":"ひまだよ。……ううん、ひまじゃ ない。／Tối nay rảnh không? – Ừ, rảnh. – Không, không rảnh."},{"s":"じしょ、もって[い]る？……うん、もって[い]る。","t":"Có từ điển không? – Ừ, có."},{"s":"その カレー[は] おいしい？……うん、からいけど、おいしい。","t":"Cà ri đó ngon không? – Ừ, hơi cay nhưng ngon."}],"tip":"Trả lời はい／いいえ ở thể thông thường đổi thành うん／ううん."}]},{"n":21,"title":"Bài 21","jp":"わたしもそう思います","sub":"～と思います · ～と言います · ý kiến","rows":[["おもいます","思います","v1","Nghĩ","think","あした あめが ふると おもいます。／Tôi nghĩ mai trời mưa.","Nhóm I · thể từ điển: おもう · thể thường + と おもいます."],["いいます","言います","v1","Nói","say","ねる まえに 「おやすみなさい」と いいます。／Trước khi ngủ nói “Chúc ngủ ngon”.","Nhóm I · thể từ điển: いう"],["たります","足ります","v2","Đủ","be enough","おかねが たりません。／Không đủ tiền.","Nhóm II · thể từ điển: たりる"],["かちます","勝ちます","v1","Thắng","win","どちらが かつと おもいますか。／Bạn nghĩ đội nào thắng?","Nhóm I · thể từ điển: かつ"],["まけます","負けます","v2","Thua","lose, be beaten","しあいに まけました。／Thua trận đấu.","Nhóm II · thể từ điển: まける"],["あります［おまつりが～］","","v1","Có, được tổ chức [lễ hội]","[a festival] be held, take place","あした こうえんで おまつりが あります。／Mai công viên có lễ hội.","Sự kiện diễn ra ở đâu dùng で."],["やくにたちます","役に立ちます","v1","Có ích","be useful","この じしょは やくに たちます。／Từ điển này có ích.","Nhóm I · thể từ điển: やくにたつ"],["むだ［な］","無駄［な］","ana","Lãng phí, vô ích","wasteful","じかんの むだです。／Lãng phí thời gian.","Tính từ đuôi な."],["ふべん［な］","不便［な］","ana","Bất tiện","inconvenient","この まちは こうつうが ふべんです。／Thị trấn này giao thông bất tiện.","Tính từ đuôi な."],["おなじ","同じ","ana","Giống nhau, cùng","the same","おなじ かばんを もって います。／Có chiếc cặp giống nhau.","Trước danh từ không dùng な: おなじ＋N."],["すごい","凄い","ai","Ghê, giỏi quá, tuyệt","awful, great (astonishment)","すごい ひとですね。／Người tài giỏi nhỉ.",""],["しゅしょう","首相","n","Thủ tướng","prime minister","しゅしょうは あした アメリカへ いきます。／Thủ tướng mai đi Mỹ.",""],["だいとうりょう","大統領","n","Tổng thống","president","だいとうりょうの スピーチを ききました。／Đã nghe bài phát biểu của tổng thống.",""],["せいじ","政治","n","Chính trị","politics","せいじに きょうみが あります。／Tôi quan tâm đến chính trị.",""],["ニュース","","n","Tin tức","news","けさの ニュースを みましたか。／Đã xem tin sáng nay chưa?",""],["スピーチ","","n","Bài phát biểu","speech","パーティーで スピーチを します。／Phát biểu ở bữa tiệc.","～をします: phát biểu."],["しあい","試合","n","Trận đấu","game, match","サッカーの しあいを みます。／Xem trận bóng đá.",""],["アルバイト","","n","Việc làm thêm","part-time job","コンビニで アルバイトを して います。／Đang làm thêm ở cửa hàng tiện lợi.","～をします: làm thêm."],["いけん","意見","n","Ý kiến","opinion","あなたの いけんは どうですか。／Ý kiến của bạn thế nào?",""],["［お］はなし","［お］話","n","Câu chuyện, bài nói","talk, speech, story","せんせいの おはなしは おもしろかったです。／Bài nói của thầy rất thú vị.","～をします: kể chuyện, nói chuyện."],["ユーモア","","n","Sự hài hước","humor","かれは ユーモアが あります。／Anh ấy có khiếu hài hước.",""],["デザイン","","n","Thiết kế","design","この くるまは デザインが いいです。／Xe này thiết kế đẹp.",""],["こうつう","交通","n","Giao thông","transportation, traffic","とうきょうは こうつうが べんりです。／Giao thông Tokyo tiện lợi.",""],["ラッシュ","","n","Giờ cao điểm","rush hour","あさの ラッシュは たいへんです。／Giờ cao điểm buổi sáng vất vả.",""],["さいきん","最近","adv","Gần đây","recently, these days","さいきん いそがしいです。／Dạo này bận.",""],["たぶん","多分","adv","Có lẽ","probably, perhaps","たぶん こないと おもいます。／Tôi nghĩ có lẽ anh ấy không đến.",""],["きっと","","adv","Chắc chắn","surely","きっと かつと おもいます。／Tôi nghĩ chắc chắn sẽ thắng.",""],["ほんとうに","本当に","adv","Thật sự","really","ほんとうに ありがとう ございました。／Thật sự cảm ơn anh.",""],["そんなに","","adv","(Không)… đến thế","not so much (with negatives)","そんなに むずかしくないです。／Không khó đến thế.","Đi với phủ định."],["～について","","pt","Về ~","about ~, concerning ~","にほんの ぶんかに ついて はなします。／Nói về văn hoá Nhật.",""],["しかたがありません","仕方がありません","ex","Đành chịu, không còn cách nào","It can't be helped.","あめですから、しかたが ありません。／Trời mưa nên đành chịu.",""],["しばらくですね","暫くですね","ex","Lâu rồi không gặp nhỉ","Long time no see.","しばらくですね。おげんきですか。／Lâu rồi không gặp, khoẻ không?","Tương tự おひさしぶりです."],["～でものみませんか","～でも飲みませんか","ex","Uống ~ hay gì đó nhé?","How about drinking ~ or something?","コーヒーでも のみませんか。／Uống cà phê hay gì nhé?","PDF ghi sai chữ 野 → đúng 飲."],["みないと…","見ないと…","ex","Phải xem mới được…","I've got to watch it.","きょうの しあいは みないと…。／Trận hôm nay phải xem mới được.","Rút gọn của みないと いけません."],["もちろん","","adv","Tất nhiên","of course","もちろん いきます。／Tất nhiên tôi đi.",""]],"ref":[["やくしょくめい","役職名","n","Chức danh","job title","かいしゃでは やくしょくめいで よびます。／Ở công ty người ta gọi nhau bằng chức danh.",""],["くに","国","n","Nhà nước, chính phủ; đất nước","country, state","くにの しごとを します。／Tôi làm việc cho nhà nước.",""],["とどうふけん","都道府県","n","Tỉnh, thành phố (cấp tỉnh)","prefectures","にほんには 47の とどうふけんが あります。／Nhật Bản có 47 đơn vị hành chính cấp tỉnh.",""],["ちじ","知事","n","Tỉnh trưởng, thị trưởng (cấp tỉnh)","governor","ちじの せんきょが あります。／Có bầu cử tỉnh trưởng.",""],["しちょう","市長","n","Thị trưởng","mayor","しちょうに あいました。／Tôi đã gặp thị trưởng.",""],["ちょう","町","n","Khu phố, thị trấn (đơn vị hành chính)","town","この ちょうは ちいさいです。／Thị trấn này nhỏ.","Cũng đọc まち"],["ちょうちょう","町長","n","Trưởng khu phố, trưởng thị trấn","town mayor","ちょうちょうが あいさつしました。／Trưởng thị trấn đã phát biểu chào mừng.",""],["むら","村","n","Thôn, làng","village","そふは むらに すんで います。／Ông tôi sống ở làng.",""],["そんちょう","村長","n","Trưởng thôn","village head","そんちょうは 70さいです。／Trưởng thôn 70 tuổi.",""],["がくちょう","学長","n","Hiệu trưởng, giám đốc (đại học)","university president","がくちょうの はなしを ききました。／Tôi đã nghe hiệu trưởng nói.",""],["こうちょう","校長","n","Hiệu trưởng (trường phổ thông)","principal","こうちょうせんせいは きびしいです。／Thầy hiệu trưởng nghiêm khắc.",""],["えんちょう","園長","n","Hiệu trưởng (mẫu giáo), giám đốc (vườn thú…)","kindergarten principal","ようちえんの えんちょうせんせい／cô hiệu trưởng trường mẫu giáo",""],["かいちょう","会長","n","Chủ tịch","chairman","かいちょうは きょう かいしゃに きません。／Chủ tịch hôm nay không đến công ty.",""],["じゅうやく","重役","n","Thành viên ban quản trị","executive","じゅうやくかいぎが あります。／Có cuộc họp ban quản trị.",""],["とうどり","頭取","n","Giám đốc (ngân hàng)","bank president","ぎんこうの とうどりに なりました。／Ông ấy đã thành giám đốc ngân hàng.",""],["してんちょう","支店長","n","Trưởng chi nhánh","branch manager","してんちょうは どなたですか。／Trưởng chi nhánh là vị nào?",""],["いんちょう","院長","n","Giám đốc bệnh viện","hospital director","いんちょうせんせいに みて もらいました。／Tôi được giám đốc bệnh viện khám.",""],["かんごしちょう","看護師長","n","Y tá trưởng","head nurse","かんごしちょうに ききました。／Tôi đã hỏi y tá trưởng.",""],["えきちょう","駅長","n","Trưởng ga","stationmaster","えきちょうは どこに いますか。／Trưởng ga ở đâu?",""],["しょちょう","署長","n","Trưởng đồn (cảnh sát)","police chief","けいさつの しょちょうが はなしました。／Trưởng đồn cảnh sát đã phát biểu.",""]],"refTitle":"Chức danh","grammar":[{"title":"Thể thông thường と 思います – tôi nghĩ là","form":"Thể thông thường と おもいます","explain":"と chỉ nội dung suy nghĩ. Dùng để ① phỏng đoán, ② bày tỏ ý kiến. Muốn phỏng đoán phủ định thì để phần trước と ở dạng phủ định. Hỏi ý kiến người khác: ～に ついて どう おもいますか (sau どう không dùng と). Đồng ý: わたしも そう おもいます.","examples":[{"s":"あした あめが ふると おもいます。","t":"Tôi nghĩ ngày mai trời sẽ mưa."},{"s":"ミラーさんは この ニュースを しって いますか。……いいえ、しらないと おもいます。","t":"Anh Miller có biết tin này không? – Không, tôi nghĩ là anh ấy không biết."},{"s":"あたらしい くうこうに ついて どう おもいますか。……きれいですが、ちょっと こうつうが ふべんだと おもいます。","t":"Anh nghĩ sao về sân bay mới? – Đẹp nhưng tôi nghĩ đi lại hơi bất tiện."}],"tip":"Danh từ, tính từ な trước と phải có だ: ふべんだと おもいます."},{"title":"「Câu」／Thể thông thường と 言います – nói rằng","form":"「Câu nguyên văn」と いいます · Thể thông thường と いいます","explain":"と chỉ nội dung phát ngôn. Trích dẫn trực tiếp thì để nguyên câu trong 「」; trích dẫn gián tiếp dùng thể thông thường. Thì của phần trích dẫn không phụ thuộc thì của cả câu. Người nghe đánh dấu bằng に.","examples":[{"s":"ねる まえに、「おやすみなさい」と いいます。","t":"Trước khi ngủ người ta nói “Oyasuminasai”."},{"s":"ミラーさんは「らいしゅう とうきょうへ しゅっちょうします」と いいました。","t":"Anh Miller đã nói: “Tuần sau tôi đi công tác Tōkyō”."},{"s":"ミラーさんは とうきょうへ しゅっちょうすると いいました。","t":"Anh Miller nói là anh ấy sẽ đi công tác Tōkyō."},{"s":"ちちに りゅうがくしたいと いいました。","t":"Tôi đã nói với bố là tôi muốn đi du học."}],"tip":""},{"title":"Thể thông thường でしょう？ – … phải không?","form":"V／Adjい／Adjな(bỏ だ)／N(bỏ だ) + でしょう？(lên giọng)","explain":"Dùng khi mong người nghe đồng ý hoặc xác nhận điều mình nghĩ. Đọc lên giọng. Trước でしょう dùng thể thông thường nhưng tính từ な và danh từ bỏ だ.","examples":[{"s":"あした パーティーに いくでしょう？……ええ、いきます。","t":"Mai chắc anh đi dự tiệc chứ? – Vâng, tôi sẽ đi."},{"s":"ほっかいどうは さむかったでしょう？……いいえ、そんなに さむくなかったです。","t":"Hokkaidō chắc lạnh lắm nhỉ? – Không, không lạnh lắm."}],"tip":""},{"title":"N1 (nơi chốn) で N2 が あります – được tổ chức","form":"N1 で N2 (sự kiện) が あります","explain":"Khi N2 là sự kiện (tiệc, hòa nhạc, lễ hội, trận đấu, tai nạn…) thì あります mang nghĩa “được tổ chức, diễn ra”, và nơi chốn dùng で (không phải に).","examples":[{"s":"とうきょうで にほんと ブラジルの サッカーの しあいが あります。","t":"Trận bóng đá Nhật–Braxin được tổ chức ở Tōkyō."}],"tip":"Sai: とうきょうに しあいが あります."},{"title":"N (tình huống) で – trong (dịp)","form":"N で ～","explain":"で chỉ tình huống, dịp mà việc gì đó xảy ra.","examples":[{"s":"かいぎで なにか いけんを いいましたか。","t":"Trong cuộc họp anh có phát biểu ý kiến gì không?"}],"tip":""},{"title":"N でも V – … chẳng hạn","form":"N でも + V (mời, đề nghị)","explain":"Khi mời, đề nghị, dùng でも để đưa ra một ví dụ mà không giới hạn đúng thứ đó: “… hay gì đó”.","examples":[{"s":"ちょっと ビールでも のみませんか。","t":"Anh dùng chút bia (hay gì đó) không?"}],"tip":""},{"title":"V ないと…… – phải… (rút gọn)","form":"V ない と……","explain":"Dạng rút gọn của V ないと いけません, nghĩa gần như V なければ なりません: “phải…”. Thường dùng trong hội thoại khi sắp phải đi.","examples":[{"s":"もう かえらないと……。","t":"Tôi phải về rồi…"}],"tip":""}]},{"n":22,"title":"Bài 22","jp":"どんなアパートがいいですか","sub":"Mệnh đề định ngữ · quần áo, nhà ở","rows":[["きます［シャツを～］","着ます","v2","Mặc [áo sơ mi]","put on [a shirt, etc.]","あかい シャツを きて いる ひとは だれですか。／Người mặc áo đỏ là ai?","Nhóm II · thể từ điển: きる · dùng cho áo, đồ phần thân trên."],["はきます［くつを～］","履きます","v1","Đi, mặc [giày, quần]","put on [shoes, trousers, etc.]","くつを はきます。／Đi giày.","Nhóm I · thể từ điển: はく · dùng cho phần thân dưới."],["かぶります［ぼうしを～］","被ります","v1","Đội [mũ]","put on [a hat, etc.]","ぼうしを かぶって いる ひとが たなかさんです。／Người đội mũ là anh Tanaka.","Nhóm I · thể từ điển: かぶる"],["かけます［めがねを～］","掛けます","v2","Đeo [kính]","put on [glasses]","めがねを かけて いる ひとです。／Là người đeo kính.","Nhóm II · thể từ điển: かける"],["うまれます","生まれます","v2","Sinh ra","be born","わたしは 1990ねんに うまれました。／Tôi sinh năm 1990.","Nhóm II · thể từ điển: うまれる"],["コート","","n","Áo khoác (dài)","coat","コートを きて ください。／Hãy mặc áo khoác.",""],["スーツ","","n","Com-lê","suit","スーツを きて かいしゃへ いきます。／Mặc com-lê đi làm.",""],["セーター","","n","Áo len","sweater","ははが つくった セーターです。／Áo len mẹ đan.",""],["ぼうし","帽子","n","Mũ","hat, cap","ぼうしを かぶります。／Đội mũ.",""],["めがね","眼鏡","n","Kính","glasses","めがねを わすれました。／Quên kính.",""],["よく","","adv","Thường, hay","often","よく この みせへ きます。／Hay đến cửa hàng này.","Bài 9: “rõ, tốt”."],["おめでとうございます","","ex","Xin chúc mừng","Congratulations.","おたんじょうび おめでとう ございます。／Chúc mừng sinh nhật.","Dùng cho sinh nhật, đám cưới, năm mới…"],["こちら","","pr","Cái này (lịch sự)","this (polite equivalent of これ)","こちらは いかがですか。／Cái này thì sao ạ?",""],["やちん","家賃","n","Tiền thuê nhà","house rent","やちんは いくらですか。／Tiền thuê nhà bao nhiêu?",""],["うーん","","it","Ừm…","Let me see.","うーん、ちょっと たかいですね。／Ừm, hơi đắt nhỉ.","Ngập ngừng suy nghĩ."],["ダイニングキッチン","","n","Bếp kèm phòng ăn","kitchen with a dining area","ダイニングキッチンが ひろいです。／Bếp ăn rộng.",""],["わしつ","和室","n","Phòng kiểu Nhật","Japanese-style room","わしつに ふとんを しきます。／Trải đệm ở phòng kiểu Nhật.",""],["おしいれ","押し入れ","n","Tủ âm tường kiểu Nhật","Japanese-style closet","ふとんは おしいれに あります。／Đệm ở trong tủ âm tường.",""],["ふとん","布団","n","Chăn đệm kiểu Nhật","Japanese-style mattress and quilt","ふとんで ねます。／Ngủ trên đệm futon.",""],["アパート","","n","Căn hộ","apartment","えきに ちかい アパートが いいです。／Căn hộ gần ga thì tốt.",""]],"ref":[["いふく","衣服","n","Quần áo","clothing","いふくは デパートで かいます。／Tôi mua quần áo ở cửa hàng bách hóa.",""],["ワンピース","","n","Váy liền thân","dress","あかい ワンピースを きて います。／Cô ấy mặc váy liền màu đỏ.",""],["ズボン","","n","Quần âu, quần dài","trousers","ズボンを はきます。／Tôi mặc quần.","Mặc phần dưới: はきます · còn gọi パンツ"],["ジーンズ","","n","Quần bò, quần jeans","jeans","ジーンズを はいて います。／Tôi đang mặc quần bò.",""],["スカート","","n","Váy ngắn","skirt","スカートを はきます。／Tôi mặc váy.",""],["ブラウス","","n","Áo bờ-lu-zông, áo sơ mi nữ","blouse","しろい ブラウスを きます。／Tôi mặc áo blouse trắng.",""],["ワイシャツ","","n","Áo sơ-mi (trắng)","dress shirt","ワイシャツに ネクタイを します。／Tôi mặc áo sơ mi và đeo cà vạt.",""],["マフラー","","n","Khăn quàng cổ","scarf","マフラーを します。／Tôi quàng khăn.",""],["てぶくろ","手袋","n","Găng tay","gloves","てぶくろを はめます。／Tôi đeo găng tay.",""],["くつした","靴下","n","Tất","socks","くつしたを はきます。／Tôi đi tất.",""],["ストッキング","","n","Quần tất","stockings","ストッキングを はきます。／Tôi mặc quần tất.","Còn gọi パンティーストッキング"],["おび","帯","n","Đai (thắt lưng kimono)","obi sash","きものの おびは ながいです。／Thắt lưng kimono dài.",""],["レインコート","","n","Áo mưa","raincoat","あめの ひは レインコートを きます。／Ngày mưa tôi mặc áo mưa.",""],["ベルト","","n","Thắt lưng","belt","ベルトを します。／Tôi thắt dây lưng.",""],["ハイヒール","","n","Giày cao gót","high heels","ハイヒールは あるきにくいです。／Giày cao gót khó đi.",""],["ブーツ","","n","Ủng, giày cao cổ","boots","ゆきの ひは ブーツを はきます。／Ngày tuyết tôi đi ủng.",""],["うんどうぐつ","運動靴","n","Giày thể thao","sneakers","うんどうぐつで はしります。／Tôi chạy bằng giày thể thao.",""],["ぞうり","","n","Guốc (dép xỏ ngón đi với kimono)","zori sandals","きものに ぞうりを はきます。／Mặc kimono thì đi guốc zōri.",""],["たび","","n","Tất đi với kimono (tabi)","tabi socks","たびを はいて ぞうりを はきます。／Đi tất tabi rồi xỏ guốc.",""]],"refTitle":"Quần áo","grammar":[{"title":"Mệnh đề bổ nghĩa cho danh từ","form":"[Mệnh đề ở thể thông thường] + N · Adjな → な · N → の","explain":"Trong tiếng Nhật, mọi thành phần bổ nghĩa luôn đứng TRƯỚC danh từ, kể cả cả một mệnh đề. Mệnh đề bổ nghĩa dùng thể thông thường; tính từ な giữ な, danh từ dùng の.\n\nDanh từ đã được bổ nghĩa có thể đứng ở mọi vị trí trong câu (chủ ngữ, tân ngữ, sau に, へ…).","examples":[{"s":"きょうとへ いく ひと","t":"người đi Kyōto"},{"s":"きょうとへ いかなかった ひと","t":"người đã không đi Kyōto"},{"s":"せが たかくて、かみが くろい ひと","t":"người cao, tóc đen"},{"s":"これは ミラーさんが すんで いた うちです。","t":"Đây là ngôi nhà anh Miller đã ở."},{"s":"ミラーさんが すんで いた うちは ふるいです。","t":"Ngôi nhà anh Miller đã ở thì cũ."}],"tip":"Sai: ひと きょうとへ いく. Đúng: きょうとへ いく ひと."},{"title":"Chủ ngữ trong mệnh đề bổ nghĩa dùng が","form":"[N が V] + N","explain":"Chủ ngữ của mệnh đề bổ nghĩa cho danh từ đánh dấu bằng が, không dùng は.","examples":[{"s":"これは ミラーさんが つくった ケーキです。","t":"Đây là bánh anh Miller làm."},{"s":"わたしは カリナさんが かいた えが すきです。","t":"Tôi thích bức tranh chị Karina vẽ."},{"s":"[あなたは] かれが うまれた ところを しって いますか。","t":"Bạn có biết nơi anh ấy sinh ra không?"}],"tip":"Sai: ミラーさんは つくった ケーキ."},{"title":"V (thể từ điển) 時間／約束／用事","form":"V (thể từ điển) + じかん／やくそく／ようじ","explain":"Đặt động từ thể từ điển trước じかん (thời gian để…), やくそく (hẹn để…), ようじ (việc phải…) để nói rõ nội dung.","examples":[{"s":"わたしは あさごはんを たべる じかんが ありません。","t":"Tôi không có thời gian ăn sáng."},{"s":"わたしは ともだちと えいがを みる やくそくが あります。","t":"Tôi có hẹn đi xem phim với bạn."},{"s":"きょうは しやくしょへ いく ようじが あります。","t":"Hôm nay tôi có việc phải đến văn phòng thành phố."}],"tip":""},{"title":"V ましょうか – chúng ta… nhé (đề nghị cùng làm)","form":"V(bỏ ます) ましょうか","explain":"Ở Bài 14, ～ましょうか là “để tôi làm giúp”. Ở đây nó còn là lời đề nghị người nói và người nghe cùng làm: “chúng ta… nhé?”.","examples":[{"s":"この へや、きょう みる ことが できますか。……ええ。いまから いきましょうか。","t":"Hôm nay tôi xem phòng này được không? – Vâng. Chúng ta đi ngay bây giờ nhé?"}],"tip":""}]},{"n":23,"title":"Bài 23","jp":"どうやって行きますか","sub":"～とき · ～と (hễ…thì) · chỉ đường","rows":[["ききます［せんせいに～］","聞きます","v1","Hỏi [giáo viên]","ask [the teacher]","わからない ときは、せんせいに ききます。／Khi không hiểu thì hỏi thầy.","Nhóm I · thể từ điển: きく · Bài 6: nghĩa “nghe”."],["まわします","回します","v1","Vặn, xoay","turn","この つまみを まわすと、おとが おおきく なります。／Vặn núm này thì tiếng to lên.","Nhóm I · thể từ điển: まわす"],["ひきます","引きます","v1","Kéo","pull","この レバーを ひくと、みずが でます。／Kéo cần này thì nước chảy ra.","Nhóm I · thể từ điển: ひく"],["かえます","変えます","v2","Thay đổi","change","へやの デザインを かえます。／Thay đổi thiết kế phòng.","Nhóm II · thể từ điển: かえる"],["さわります［ドアに～］","触ります","v1","Sờ, chạm [vào cửa]","touch [a door]","この ボタンに さわらないで ください。／Đừng chạm vào nút này.","Nhóm I · thể từ điển: さわる · dùng に."],["でます［おつりが～］","出ます","v2","[Tiền thừa] ra","[change] come out","ボタンを おすと、おつりが でます。／Bấm nút thì tiền thừa ra.","Nhóm II · thể từ điển: でる"],["うごきます［とけいが～］","動きます","v1","[Đồng hồ] chạy, hoạt động","[a watch] move, work","とけいが うごきません。／Đồng hồ không chạy.","Nhóm I · thể từ điển: うごく"],["あるきます［みちを～］","歩きます","v1","Đi bộ [trên đường]","walk [along a road]","この みちを まっすぐ あるくと、えきが あります。／Đi thẳng đường này thì có ga.","Nhóm I · thể từ điển: あるく · đường đi qua dùng を."],["わたります［はしを～］","渡ります","v1","Băng qua [cầu]","cross [a bridge]","はしを わたると、みぎに ゆうびんきょくが あります。／Qua cầu thì bên phải có bưu điện.","Nhóm I · thể từ điển: わたる"],["きをつけます［くるまに～］","気をつけます","v2","Chú ý, cẩn thận [xe ô tô]","pay attention [to cars], take care","くるまに きを つけて ください。／Hãy cẩn thận xe ô tô.","Nhóm II · đối tượng dùng に."],["ひっこしします","引っ越しします","v3","Chuyển nhà","move (house)","らいげつ ひっこしします。／Tháng sau chuyển nhà.","Nhóm III"],["でんきや","電気屋","n","Cửa hàng đồ điện; thợ điện","electrician, electrical shop","でんきやで テレビを かいました。／Mua ti vi ở cửa hàng điện.",""],["～や","～屋","sf","Người bán ~, cửa hàng ~","person of ~ shop","やおやさん／パンやさん。／Người bán rau / người bán bánh mì.","Thêm さん khi gọi người."],["サイズ","","n","Cỡ, kích cỡ","size","サイズが あいません。／Không vừa cỡ.",""],["おと","音","n","Âm thanh","sound","おとが ちいさいです。／Âm thanh nhỏ.",""],["きかい","機械","n","Máy móc","machine","この きかいの つかいかたを おしえて ください。／Hãy chỉ cách dùng máy này.",""],["つまみ","摘み","n","Núm vặn","knob","つまみを みぎへ まわします。／Vặn núm sang phải.",""],["こしょう","故障","n","Hỏng hóc","breakdown","エアコンが こしょうしました。／Điều hoà bị hỏng.","～します: hỏng."],["みち","道","n","Đường, con đường","road, way","みちを おしえて ください。／Chỉ đường giúp tôi.",""],["こうさてん","交差点","n","Ngã tư","crossroad","こうさてんを みぎへ まがります。／Rẽ phải ở ngã tư.",""],["しんごう","信号","n","Đèn tín hiệu giao thông","traffic light","しんごうが あおに なったら、わたります。／Đèn xanh thì qua đường.",""],["かど","角","n","Góc (phố)","corner","かどの みせです。／Là cửa hàng ở góc phố.",""],["はし","橋","n","Cây cầu","bridge","はしを わたります。／Đi qua cầu.","Khác はし (đũa) ở ngữ điệu."],["ちゅうしゃじょう","駐車場","n","Bãi đỗ xe","parking lot","ちゅうしゃじょうは ビルの うしろです。／Bãi đỗ xe ở sau toà nhà.",""],["～め","～目","sf","Thứ ~ (thứ tự)","the ~th (order)","ふたつめの かどを ひだりへ まがって ください。／Rẽ trái ở góc thứ hai.",""],["［お］しょうがつ","［お］正月","n","Tết, năm mới","New Year","おしょうがつに かぞくと すごします。／Đón Tết cùng gia đình.",""],["ごちそうさま［でした］","ご馳走さま［でした］","ex","Cảm ơn vì bữa ăn ngon","That was delicious. (after eating)","ごちそうさまでした。／Cảm ơn vì bữa ăn.","Nói sau khi ăn; đối lại いただきます."],["たてもの","建物","n","Toà nhà, công trình","building","あの たてものは びじゅつかんです。／Toà nhà kia là bảo tàng mỹ thuật.",""],["がいこくじんとうろくしょう","外国人登録証","n","Thẻ đăng ký người nước ngoài","alien registration card","がいこくじんとうろくしょうを みせて ください。／Cho xem thẻ đăng ký người nước ngoài.",""]],"ref":[["どうろ","道路","n","Đường sá","road","どうろが こんで います。／Đường đông xe.",""],["ほどう","歩道","n","Đường cho người đi bộ, vỉa hè","sidewalk","ほどうを あるいて ください。／Hãy đi trên vỉa hè.",""],["しゃどう","車道","n","Đường cho xe ô-tô","roadway","しゃどうを あるかないで ください。／Đừng đi bộ dưới lòng đường.",""],["こうそくどうろ","高速道路","n","Đường cao tốc","expressway","こうそくどうろで おおさかへ いきます。／Tôi đi Ōsaka bằng đường cao tốc.",""],["とおり","通り","n","Đường, phố","street","この とおりを まっすぐ いって ください。／Hãy đi thẳng con đường này.",""],["おうだんほどう","横断歩道","n","Vạch qua đường cho người đi bộ","crosswalk","おうだんほどうを わたります。／Tôi sang đường ở vạch qua đường.",""],["ほどうきょう","歩道橋","n","Cầu vượt cho người đi bộ","pedestrian bridge","ほどうきょうを わたって ください。／Hãy đi qua cầu vượt.",""],["さか","坂","n","Dốc","slope","さかを のぼります。／Tôi leo dốc.",""],["ふみきり","踏切","n","Chắn tàu, chỗ chắn đường sắt","railroad crossing","ふみきりで とまって ください。／Hãy dừng lại ở chỗ chắn tàu.",""],["ガソリンスタンド","","n","Trạm xăng, cây xăng","gas station","ガソリンスタンドは どこですか。／Cây xăng ở đâu?",""],["とまれ","止まれ","ex","Dừng lại (biển báo)","stop (sign)","「とまれ」の ひょうしきが あります。／Có biển báo \"Dừng lại\".",""],["しんにゅうきんし","進入禁止","n","Cấm đi vào","no entry","ここは しんにゅうきんしです。／Chỗ này cấm đi vào.",""],["いっぽうつうこう","一方通行","n","Đường một chiều","one-way traffic","この みちは いっぽうつうこうです。／Con đường này là đường một chiều.",""],["ちゅうしゃきんし","駐車禁止","n","Cấm đỗ xe","no parking","ここは ちゅうしゃきんしです。／Ở đây cấm đỗ xe.",""],["うせつきんし","右折禁止","n","Cấm rẽ phải","no right turn","この こうさてんは うせつきんしです。／Ngã tư này cấm rẽ phải.",""]],"refTitle":"Đường sá & giao thông","grammar":[{"title":"～とき、～ – khi","form":"V (từ điển／ない／た)・Adjい・Adjな な・N の + とき、～","explain":"とき nối với mệnh đề chính, chỉ thời điểm xảy ra trạng thái, hành động. Dạng đứng trước とき giống cách bổ nghĩa danh từ (Bài 22). Thì của mệnh đề trước とき không phụ thuộc thì câu chính.","examples":[{"s":"としょかんで ほんを かりる とき、カードが いります。","t":"Khi mượn sách ở thư viện cần có thẻ."},{"s":"つかいかたが わからない とき、わたしに きいて ください。","t":"Khi không biết cách dùng hãy hỏi tôi."},{"s":"ひまな とき、うちへ あそびに きませんか。","t":"Khi rảnh thì đến nhà tôi chơi nhé!"},{"s":"こどもの とき、よく かわで およぎました。","t":"Hồi nhỏ tôi hay bơi ở sông."}],"tip":""},{"title":"V (từ điển)／V た とき – trước hay sau","form":"V (thể từ điển) とき · V (thể た) とき","explain":"Động từ thể từ điển + とき: việc ở câu chính xảy ra TRƯỚC (hoặc trong lúc) hành động đó hoàn thành. Thể た + とき: câu chính xảy ra SAU khi hành động đó đã xong.","examples":[{"s":"パリへ いく とき、かばんを かいました。","t":"Lúc đi Paris tôi đã mua túi xách (mua trên đường đi, trước khi tới)."},{"s":"パリへ いった とき、かばんを かいました。","t":"Khi đến Paris tôi đã mua túi xách (mua ở Paris)."}],"tip":""},{"title":"V (thể từ điển) と、～ – hễ… thì","form":"V (thể từ điển) と、～ (kết quả tất yếu)","explain":"と chỉ điều kiện: hễ hành động trước xảy ra thì kết quả, trạng thái sau tất yếu xảy ra. Hay dùng để chỉ cách dùng máy móc, chỉ đường. Câu sau không dùng ý chí, mong muốn, mời, nhờ.","examples":[{"s":"この ボタンを おすと、おつりが でます。","t":"Ấn nút này thì tiền thừa sẽ ra."},{"s":"これを まわすと、おとが おおきく なります。","t":"Vặn cái này thì âm thanh to lên."},{"s":"みぎへ まがると、ゆうびんきょくが あります。","t":"Rẽ phải là thấy bưu điện."}],"tip":"Sai: じかんが あると、コンサートに いきたいです (mong muốn) → dùng ～たら (Bài 25)."},{"title":"N が Adj – miêu tả cảm nhận","form":"N が Adj","explain":"Như N が V (Bài 14), khi truyền đạt nguyên vẹn điều cảm nhận bằng giác quan, chủ ngữ của câu tính từ cũng dùng が.","examples":[{"s":"おとが ちいさいです。","t":"Âm thanh nhỏ."},{"s":"この へやは でんきが くらいです。","t":"Phòng này đèn tối."}],"tip":""},{"title":"N を + động từ di chuyển – đi qua","form":"N を さんぽします／わたります／あるきます／まがります","explain":"を đi với động từ chuyển động chỉ nơi mà người/vật đi qua, di chuyển trên đó.","examples":[{"s":"こうえんを さんぽします。","t":"Tôi đi dạo ở công viên."},{"s":"みちを わたります。","t":"Tôi qua đường."},{"s":"こうさてんを みぎへ まがります。","t":"Tôi rẽ phải ở ngã tư."}],"tip":""}]},{"n":24,"title":"Bài 24","jp":"手伝いに行きましょうか","sub":"くれます · ～てあげます/もらいます/くれます","rows":[["くれます","","v2","Cho (tôi)","give (me)","さとうさんは わたしに はなを くれました。／Chị Sato tặng hoa cho tôi.","Nhóm II · thể từ điển: くれる · người nhận là mình/người nhà mình."],["つれていきます","連れて行きます","v1","Dẫn (ai) đi","take (someone)","こどもを こうえんへ つれて いきます。／Dẫn con đi công viên.","Nhóm I · người dùng を."],["つれてきます","連れて来ます","v3","Dẫn (ai) đến","bring (someone)","ともだちを パーティーに つれて きます。／Dẫn bạn đến bữa tiệc.","Nhóm III"],["おくります［ひとを～］","送ります","v1","Đưa, tiễn [ai]","escort [someone], go with","えきまで おくりましょう。／Để tôi tiễn anh đến ga.","Nhóm I · thể từ điển: おくる · Bài 7: “gửi”."],["しょうかいします","紹介します","v3","Giới thiệu","introduce","ともだちを しょうかいします。／Giới thiệu bạn.","Nhóm III"],["あんないします","案内します","v3","Hướng dẫn, dẫn đường","show around, show the way","きょうとを あんないして くれました。／Đã dẫn tôi đi thăm Kyoto.","Nhóm III"],["せつめいします","説明します","v3","Giải thích","explain","せんせいが ぶんぽうを せつめいして くれました。／Thầy đã giải thích ngữ pháp cho tôi.","Nhóm III"],["いれます［コーヒーを～］","淹れます","v2","Pha [cà phê]","make [coffee]","コーヒーを いれましょうか。／Tôi pha cà phê nhé?","Nhóm II · thể từ điển: いれる"],["おじいさん／おじいちゃん","お祖父さん","n","Ông; cụ ông","grandfather, old man","おじいさんは 80さいです。／Ông tôi 80 tuổi.","おじいちゃん: thân mật hơn. Ông mình: そふ."],["おばあさん／おばあちゃん","お祖母さん","n","Bà; cụ bà","grandmother, old woman","おばあちゃんが セーターを くれました。／Bà tặng tôi áo len.","Bà mình: そぼ."],["じゅんび","準備","n","Chuẩn bị","preparation","パーティーの じゅんびを します。／Chuẩn bị bữa tiệc.","～します: chuẩn bị."],["いみ","意味","n","Ý nghĩa","meaning","この ことばの いみを おしえて ください。／Hãy cho biết nghĩa từ này.",""],["［お］かし","［お］菓子","n","Bánh kẹo","sweets, snacks","こどもに おかしを あげます。／Cho trẻ con bánh kẹo.",""],["ぜんぶ","全部","n","Toàn bộ, tất cả","all","ぜんぶ たべました。／Đã ăn hết.",""],["じぶんで","自分で","adv","Tự mình","by oneself","じぶんで つくりました。／Tự mình làm.",""],["ほかに","外に","adv","Ngoài ra","besides","ほかに なにか ありますか。／Ngoài ra còn gì không?",""],["ワゴンしゃ","ワゴン車","n","Xe ô tô hòm (xe van)","station wagon","ワゴンしゃで ひっこしを てつだって くれました。／Đã dùng xe van giúp tôi chuyển nhà.",""],["［お］べんとう","［お］弁当","n","Cơm hộp","box lunch","ははが おべんとうを つくって くれました。／Mẹ làm cơm hộp cho tôi.",""]],"ref":[["ぞうとう","贈答","n","Tặng quà, biếu tặng","gift-giving","にほんには ぞうとうの しゅうかんが たくさん あります。／Ở Nhật có nhiều tập quán tặng quà.",""],["しゅうかん","習慣","n","Tập quán, thói quen","custom, habit","にほんの しゅうかんを ならいます。／Tôi học tập quán Nhật Bản.",""],["おとしだま","お年玉","n","Tiền mừng tuổi","New Year's money gift","おしょうがつに おとしだまを もらいました。／Tết tôi được nhận tiền mừng tuổi.","Bố mẹ, họ hàng tặng trẻ con ngày Tết"],["にゅうがくいわい","入学祝い","n","Quà mừng nhập học","school entrance gift","にゅうがくいわいに じしょを あげました。／Tôi tặng từ điển làm quà mừng nhập học.","Thường là tiền, văn phòng phẩm, sách"],["そつぎょういわい","卒業祝い","n","Quà mừng tốt nghiệp","graduation gift","そつぎょういわいに とけいを もらいました。／Tôi được tặng đồng hồ mừng tốt nghiệp.",""],["けっこんいわい","結婚祝い","n","Quà mừng cưới","wedding gift","けっこんいわいに おさらを おくりました。／Tôi gửi tặng bộ đĩa làm quà cưới.","Thường là tiền hoặc đồ dùng trong nhà"],["しゅっさんいわい","出産祝い","n","Quà mừng sinh con","gift for a new baby","しゅっさんいわいに こどもふくを あげます。／Tôi tặng quần áo trẻ em mừng sinh con.",""],["おちゅうげん","お中元","n","Quà giữa năm (tháng 7–8)","midsummer gift","おせわに なった ひとに おちゅうげんを おくります。／Tôi gửi quà giữa năm cho người đã giúp đỡ mình.","Tặng bác sĩ, thầy cô, cấp trên; thường là đồ ăn"],["おせいぼ","お歳暮","n","Quà cuối năm (tháng 12)","year-end gift","ぶちょうに おせいぼを おくりました。／Tôi gửi quà cuối năm cho trưởng phòng.",""],["おこうでん","お香典","n","Tiền phúng viếng","condolence money","そうしきに おこうでんを もって いきます。／Tôi mang tiền phúng viếng đến đám tang.",""],["おみまい","お見舞い","n","Quà thăm người ốm","get-well gift (visit)","びょういんへ おみまいに いきます。／Tôi đi thăm người ốm ở bệnh viện.","Thường là hoa hoặc hoa quả"],["のしぶくろ","熨斗袋","n","Phong bì mừng (đựng tiền tặng)","gift envelope","のしぶくろに おかねを いれます。／Tôi cho tiền vào phong bì mừng.","Cưới, mừng: ruy-băng đỏ-trắng/vàng-bạc; tang: trắng-đen"]],"refTitle":"Tập quán tặng quà","grammar":[{"title":"くれます – cho (mình)","form":"Người khác は わたし（gia đình）に N を くれます","explain":"あげます không dùng khi người khác cho người nói hoặc người nhà người nói. Khi đó dùng くれます.","examples":[{"s":"わたしは さとうさんに はなを あげました。","t":"Tôi đã tặng hoa cho chị Satō."},{"s":"さとうさんは わたしに クリスマスカードを くれました。","t":"Chị Satō đã tặng tôi thiệp Giáng sinh."},{"s":"さとうさんは いもうとに おかしを くれました。","t":"Chị Satō đã cho em gái tôi bánh kẹo."}],"tip":"Sai: さとうさんは わたしに カードを あげました."},{"title":"V て あげます／もらいます／くれます – làm cho, được làm cho","form":"V て あげます (làm cho người khác) · V て もらいます (được người khác làm cho) · V て くれます (người khác làm cho mình)","explain":"Ba động từ cho–nhận gắn sau thể て để nói việc làm mang lại ơn huệ, lợi ích.\n\n～てあげます: chủ thể làm cho người khác; dùng với người trên dễ nghe như kể công, nên khi đề nghị giúp hãy dùng ～ましょうか.\n\n～てもらいます: người nhận ơn là chủ ngữ (thường わたし, hay lược), người làm đánh dấu bằng に – thể hiện lòng biết ơn.\n\n～てくれます: người làm là chủ ngữ, người nhận là わたし (thường lược). Trợ từ của người nhận giữ nguyên như câu gốc (に, を, の).","examples":[{"s":"わたしは きむらさんに ほんを かして あげました。","t":"Tôi đã cho chị Kimura mượn sách."},{"s":"わたしは やまださんに としょかんの でんわばんごうを おしえて もらいました。","t":"Tôi được anh Yamada cho biết số điện thoại thư viện."},{"s":"はは は［わたしに］ セーターを おくって くれました。","t":"Mẹ đã gửi (cho tôi) một chiếc áo len."},{"s":"かれは わたしを おおさかじょうへ つれて いって くれます。","t":"Anh ấy đưa tôi đi thăm thành Ōsaka."},{"s":"かれは わたしの ひっこしを てつだって くれます。","t":"Anh ấy giúp tôi chuyển nhà."}],"tip":"Khi đề nghị giúp người trên: Sai: てつだって あげましょうか. Đúng: てつだいましょうか."},{"title":"N1 は N2 が V – nhấn ai là người làm","form":"(Tân ngữ đưa lên làm chủ đề) N1 は N2 (người làm) が V","explain":"Khi tân ngữ (vd この ワイン) đã được cả hai biết và đưa lên làm chủ đề với は, người thực hiện hành động đánh dấu bằng が.","examples":[{"s":"おいしい ワインですね。……ええ、[この ワインは] さとうさんが くれました。","t":"Rượu ngon nhỉ. – Vâng, (rượu này) chị Satō tặng tôi đấy."}],"tip":""}]},{"n":25,"title":"Bài 25","jp":"いろいろお世話になりました","sub":"～たら · ～ても · chia tay","rows":[["かんがえます","考えます","v2","Suy nghĩ, cân nhắc","think, consider","よく かんがえて ください。／Hãy suy nghĩ kỹ.","Nhóm II · thể từ điển: かんがえる"],["つきます［えきに～］","着きます","v1","Đến [ga]","arrive [at the station]","えきに ついたら、でんわして ください。／Đến ga thì gọi cho tôi.","Nhóm I · thể từ điển: つく · nơi đến dùng に."],["りゅうがくします","留学します","v3","Du học","study abroad","にほんへ りゅうがくします。／Du học Nhật Bản.","Nhóm III"],["とります［としを～］","取ります","v1","Có tuổi, già đi","grow old","としを とっても、はたらきたいです。／Dù có tuổi vẫn muốn làm việc.","Nhóm I · thể từ điển: とる"],["いなか","田舎","n","Nông thôn, quê","countryside, hometown","いなかに すみたいです。／Muốn sống ở quê.",""],["たいしかん","大使館","n","Đại sứ quán","embassy","たいしかんへ ビザを もらいに いきます。／Đến đại sứ quán xin visa.",""],["グループ","","n","Nhóm","group","グループで りょこうします。／Du lịch theo nhóm.",""],["チャンス","","n","Cơ hội","chance","いい チャンスですね。／Cơ hội tốt nhỉ.",""],["おく","億","num","Trăm triệu","hundred million","1おくえん あったら、なにを しますか。／Nếu có 100 triệu yên thì làm gì?",""],["もし［～たら］","","adv","Nếu [~]","if ~","もし あめが ふったら、いきません。／Nếu trời mưa thì không đi.","Đi với thể たら."],["いくら［～ても］","","adv","Dù ~ bao nhiêu đi nữa","however ~, even if ~","いくら かんがえても、わかりません。／Nghĩ mấy cũng không hiểu.","Đi với thể ても."],["てんきん","転勤","n","Chuyển công tác","transfer","らいげつ とうきょうへ てんきんします。／Tháng sau chuyển công tác lên Tokyo.","～します: chuyển công tác."],["こと","事","n","Việc, chuyện","thing, matter","かぞくの ことを かんがえます。／Nghĩ về chuyện gia đình.","～のこと: chuyện về ~."],["いっぱいのみましょう","一杯飲みましょう","ex","Cùng uống một ly nào","Let's have a drink together.","こんばん いっぱい のみましょう。／Tối nay cùng làm một ly nhé.",""],["［いろいろ］おせわになりました","［色々］お世話になりました","ex","Cảm ơn anh/chị đã giúp đỡ [nhiều]","Thank you for everything you have done for me.","いろいろ おせわに なりました。／Cảm ơn anh đã giúp đỡ tôi nhiều.","Nói khi chia tay, kết thúc một quan hệ."],["がんばります","頑張ります","v1","Cố gắng","do one's best","あたらしい しごとで がんばります。／Tôi sẽ cố gắng ở công việc mới.","Nhóm I · thể từ điển: がんばる · がんばって！: Cố lên!"],["どうぞおげんきで","どうぞお元気で","ex","Chúc anh/chị mạnh khoẻ","Best of luck. (on a long separation)","どうぞ おげんきで。／Chúc anh mạnh khoẻ nhé.","Nói khi chia tay lâu dài."]],"ref":[["いっしょう","一生","n","Cuộc đời, cả đời","lifetime","いっしょう わすれません。／Cả đời tôi sẽ không quên.",""],["あかちゃん","赤ちゃん","n","Em bé","baby","あかちゃんが うまれました。／Em bé đã chào đời.","0 tuổi"],["ほいくえん","保育園","n","Nhà trẻ","nursery school","むすこを ほいくえんに あずけます。／Tôi gửi con trai ở nhà trẻ.",""],["がっこうに はいります","学校に 入ります","ex","Đi học, vào trường","enter school","6さいで がっこうに はいります。／6 tuổi thì đi học.",""],["こうとうがっこう","高等学校","n","Trường THPT","senior high school","こうとうがっこうは 3ねんです。／Trường THPT học 3 năm.","Gọi tắt 高校"],["たんだい","短大","n","Cao đẳng (2 năm)","junior college","あねは たんだいを そつぎょうしました。／Chị tôi đã tốt nghiệp cao đẳng.",""],["せんもんがっこう","専門学校","n","Trường trung cấp chuyên nghiệp, dạy nghề","vocational school","せんもんがっこうで りょうりを ならいます。／Tôi học nấu ăn ở trường dạy nghề.",""],["だいがくいん","大学院","n","Cao học, sau đại học","graduate school","だいがくいんで けんきゅうして います。／Tôi đang nghiên cứu ở bậc cao học.",""],["せいねん","青年","n","Thanh niên","young person","18さいは せいねんです。／18 tuổi là thanh niên.",""],["がっこうを でます","学校を 出ます","ex","Tốt nghiệp, ra trường","graduate","がっこうを でてから、かいしゃに はいりました。／Ra trường xong tôi vào công ty.",""],["しゅうしょくします","就職します","v3","Đi làm, tìm được việc","get a job","だいがくを でて、ぎんこうに しゅうしょくしました。／Tốt nghiệp đại học xong tôi vào làm ở ngân hàng.",""],["こどもが うまれます","子どもが 生まれます","ex","Sinh con","have a child","らいげつ こどもが うまれます。／Tháng sau tôi sẽ sinh con.",""],["ちゅうねん","中年","n","Trung niên","middle age","ちちは もう ちゅうねんです。／Bố tôi đã ở tuổi trung niên.",""],["りこんします","離婚します","v3","Ly hôn","get divorced","あの ふたりは りこんしました。／Hai người đó đã ly hôn.",""],["さいこんします","再婚します","v3","Tái hôn","remarry","ははは さいこんしました。／Mẹ tôi đã tái hôn.",""],["しごとを やめます","仕事を やめます","ex","Nghỉ hưu, thôi việc","retire, quit a job","60さいで しごとを やめます。／60 tuổi tôi sẽ nghỉ hưu.",""],["ろうじん","老人","n","Người già","elderly person","ろうじんに せきを ゆずります。／Tôi nhường ghế cho người già.",""],["しにます","死にます","v1","Chết","die","その いぬは きょねん しにました。／Con chó đó đã chết năm ngoái.",""],["へいきんじゅみょう","平均寿命","n","Tuổi thọ trung bình","average life expectancy","にほんじんの へいきんじゅみょうは ながいです。／Tuổi thọ trung bình của người Nhật cao.","Theo sách: nam 79,59 · nữ 86,44 (2009)"]],"refTitle":"Cuộc đời một con người","grammar":[{"title":"Thể thông thường quá khứ ら、～ – nếu… thì","form":"V た ら · Adjい かった ら · Adjな／N だった ら","explain":"Thêm ら vào thể quá khứ thông thường để nêu điều kiện giả định. Khác と (Bài 23), câu sau ～たら có thể dùng ý chí, mong muốn, mời rủ, nhờ vả.","examples":[{"s":"おかねが あったら、りょこうします。","t":"Nếu có tiền tôi sẽ đi du lịch."},{"s":"じかんが なかったら、テレビを みません。","t":"Nếu không có thời gian tôi sẽ không xem tivi."},{"s":"やすかったら、パソコンを かいたいです。","t":"Nếu rẻ thì tôi muốn mua máy tính."},{"s":"ひまだったら、てつだって ください。","t":"Nếu rảnh thì giúp tôi nhé."},{"s":"いい てんきだったら、さんぽしませんか。","t":"Nếu trời đẹp thì đi dạo nhé?"}],"tip":""},{"title":"V たら、～ – khi (chắc chắn xảy ra)","form":"V た ら、～","explain":"Khi việc trong vế たら chắc chắn sẽ xảy ra, ～たら nghĩa là “sau khi/khi… thì”: hành động ở vế sau diễn ra sau khi vế trước hoàn thành.","examples":[{"s":"10じに なったら、でかけましょう。","t":"Đến 10 giờ thì chúng ta đi nhé."},{"s":"うちへ かえったら、すぐ シャワーを あびます。","t":"Về đến nhà là tôi tắm ngay."}],"tip":""},{"title":"V て／V なくて／Adjい くて／Adjな で／N で も、～ – cho dù","form":"V て も · V なく て も · Adj(bỏ い) く て も · Adjな で も · N で も","explain":"Điều kiện giả định ngược: dù vế trước xảy ra thì vế sau vẫn trái với điều bình thường mọi người nghĩ.","examples":[{"s":"あめが ふっても、せんたくします。","t":"Dù trời mưa tôi vẫn giặt quần áo."},{"s":"やすくても、わたしは グループりょこうが きらいです。","t":"Dù rẻ tôi vẫn không thích du lịch theo đoàn."},{"s":"べんりでも、パソコンを つかいません。","t":"Dù máy tính tiện lợi tôi cũng không dùng."},{"s":"にちようびでも、はたらきます。","t":"Dù Chủ nhật tôi vẫn làm việc."}],"tip":""},{"title":"もし – nếu (nhấn mạnh giả định)","form":"もし ～たら","explain":"もし đi với ～たら, báo trước câu là câu điều kiện và nhấn tâm lý giả định của người nói.","examples":[{"s":"もし 1おくえん あったら、いろいろな くにを りょこうしたいです。","t":"Nếu có 100 triệu yên tôi muốn đi du lịch nhiều nước."}],"tip":""},{"title":"Chủ ngữ của mệnh đề phụ dùng が","form":"[N が V] ～から／～とき／～と／～まえに／～たら／～ても, ～","explain":"Như mệnh đề ～てから (Bài 16), chủ ngữ trong các mệnh đề phụ ～から, ～とき, ～と, ～まえに, ～たら, ～ても cũng đánh dấu bằng が.","examples":[{"s":"ともだちが くる まえに、へやを そうじします。","t":"Trước khi bạn đến chơi tôi dọn phòng."},{"s":"つまが びょうきの とき、かいしゃを やすみます。","t":"Khi vợ bị ốm tôi nghỉ làm."},{"s":"ともだちが やくそくの じかんに こなかったら、どう しますか。","t":"Nếu bạn không đến đúng giờ hẹn thì anh sẽ làm gì?"}],"tip":""},{"title":"V た ほうが いいです – nên · bổ sung N5","form":"V た ほうが いいです · V ない ほうが いいです","explain":"Dùng để khuyên: “nên làm…” / “không nên làm…”. (Trong Minna mẫu này học ở Bài 32, nhưng có trong danh sách N5.)","examples":[{"s":"まいにち うんどうした ほうが いいです。","t":"Bạn nên vận động hằng ngày."},{"s":"おふろに はいらない ほうが いいです。","t":"Bạn không nên tắm bồn."}],"tip":""},{"title":"～でしょう／たぶん – có lẽ · bổ sung N5","form":"Thể thông thường (Adjな/N bỏ だ) + でしょう · たぶん ～でしょう","explain":"でしょう (xuống giọng) diễn tả phỏng đoán không chắc chắn: “có lẽ, chắc là”; hay đi cùng たぶん. Khác でしょう？ lên giọng ở Bài 21 (xác nhận). (Minna học ở Bài 32.)","examples":[{"s":"あしたは あめが ふるでしょう。","t":"Ngày mai có lẽ trời sẽ mưa."},{"s":"かれは たぶん こないでしょう。","t":"Chắc anh ấy sẽ không đến."}],"tip":""}]}],"refTotal":482,"grammarTotal":150};
